    BaniLine(id = "rehras-sahib-1", gurmukhi = "ਹਰਿ ਜੁਗੁ ਜੁਗੁ. ਭਗਤ ਉਪਾਇਆ; ਪੈਜ ਰਖਦਾ ਆਇਆ. ਰਾਮ ਰਾਜੇ ॥", transliteration = "har jug jug. bhagat upaaiaa; paij rakhdaa aaiaa. raam raaje ||", translation = "In each and every age, He creates His devotees and preserves their honor, O Lord King.", hindi = "हरि जुगु जुगु. भगत उपाइआ; पैज रखदा आइआ. राम राजे ॥", punjabi = "ਪਰਮਾਤਮਾ ਹਰੇਕ ਜੁਗ ਵਿਚ ਹੀ ਭਗਤ ਪੈਦਾ ਕਰਦਾ ਹੈ, ਤੇ, (ਭੀੜਾ ਸਮੇ) ਉਹਨਾਂ ਦੀ ਇੱਜ਼ਤ ਰੱਖਦਾ ਆ ਰਿਹਾ ਹੈ।", wordMeaning = "ਜੁਗੁ ਜੁਗੁ = ਹਰੇਕ ਜੁਗ ਵਿਚ {ਵੇਖੋ 'ਗੁਰਬਾਣੀ ਵਿਆਕਰਣ'}। ਉਪਾਇਆ = ਪੈਦਾ ਕਰਦਾ ਆ ਰਿਹਾ ਹੈ। ਪੈਜ = ਇੱਜ਼ਤ। ਦੇਇ = ਦੇ ਕੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-2", gurmukhi = "ਹਰਣਾਖਸੁ ਦੁਸਟੁ ਹਰਿ ਮਾਰਿਆ; ਪ੍ਰਹਲਾਦੁ ਤਰਾਇਆ ॥", transliteration = "harnaakhas dusat har maariaa; prahlaad traaiaa ||", translation = "The Lord killed the wicked Harnaakhash, and saved Prahlaad.", hindi = "हरणाखसु दुसटु हरि मारिआ; प्रहलादु तराइआ ॥", punjabi = "(ਜਿਵੇਂ ਕਿ, ਪ੍ਰਹਿਲਾਦ ਦੇ ਜ਼ਾਲਮ ਪਿਤਾ) ਚੰਦਰੇ ਹਰਣਾਖੁਸ਼ ਨੂੰ ਪਰਮਾਤਮਾ ਨੇ (ਆਖ਼ਰ ਜਾਨੋਂ) ਮਾਰ ਦਿੱਤਾ (ਤੇ ਆਪਣੇ ਭਗਤ) ਪ੍ਰਹਿਲਾਦ ਨੂੰ (ਪਿਉ ਦੇ ਦਿੱਤੇ ਕਸ਼ਟਾਂ ਤੋਂ) ਸਹੀ ਸਲਾਮਤਿ ਬਚਾ ਲਿਆ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-3", gurmukhi = "ਅਹੰਕਾਰੀਆ ਨਿੰਦਕਾ. ਪਿਠਿ ਦੇਇ; ਨਾਮਦੇਉ. ਮੁਖਿ ਲਾਇਆ ॥", transliteration = "ahankaareeaa nindkaa. pith dei; naamdeu. mukh laaiaa ||", translation = "He turned his back on the egotists and slanderers, and showed His Face to Naam Dayv.", hindi = "अहंकारीआ निंदका. पिठि देइ; नामदेउ. मुखि लाइआ ॥", punjabi = "(ਜਿਵੇਂ ਕਿ, ਮੰਦਰ ਵਿਚੋਂ ਧੱਕੇ ਦੇਣ ਵਾਲੇ) ਨਿੰਦਕਾਂ ਤੇ (ਜਾਤਿ-) ਅਭਿਮਾਨੀਆਂ ਨੂੰ (ਪਰਮਾਤਮਾ ਨੇ) ਪਿੱਠ ਦੇ ਕੇ (ਆਪਣੇ ਭਗਤ) ਨਾਮਦੇਵ ਨੂੰ ਦਰਸ਼ਨ ਦਿੱਤਾ।", wordMeaning = "ਮੁਖਿ ਲਾਇਆ = ਆਪਣੇ ਮੂੰਹ ਲਾਇਆ, ਆਦਰ-ਸਨਮਾਨ ਦਿੱਤਾ, ਇੱਜ਼ਤ ਬਖ਼ਸ਼ੀ। ਐਸਾ = ਇਹੋ ਜਿਹੀ ਸਮਰਥਾ ਵਾਲਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-4", gurmukhi = "ਜਨ ਨਾਨਕ. ਐਸਾ ਹਰਿ ਸੇਵਿਆ; ਅੰਤਿ ਲਏ ਛਡਾਇਆ ॥੪॥੧੩॥੨੦॥", transliteration = "jan naanak. aisaa har seviaa; ant lae chhdaaiaa ||4||13||20||", translation = "Servant Nanak has so served the Lord, that He will deliver him in the end. ||4||13||20||", hindi = "जन नानक. ऐसा हरि सेविआ; अंति लए छडाइआ ॥४॥१३॥२०॥", punjabi = "ਹੇ ਦਾਸ ਨਾਨਕ! ਜੇਹੜਾ ਭੀ ਮਨੁੱਖ ਇਹੋ ਜਿਹੀ ਸਮਰਥਾ ਵਾਲੇ ਪਰਮਾਤਮਾ ਦੀ ਸੇਵਾ-ਭਗਤੀ ਕਰਦਾ ਹੈ ਪਰਮਾਤਮਾ ਉਸ ਨੂੰ (ਦੋਖੀਆਂ ਵਲੋਂ ਦਿੱਤੇ ਜਾ ਰਹੇ ਸਭ ਕਸ਼ਟਾਂ ਤੋਂ) ਆਖ਼ਰ ਬਚਾ ਲੈਂਦਾ ਹੈ ॥੪॥੧੩॥੨੦॥", wordMeaning = "ਅੰਤਿ = ਆਖ਼ਰ ਨੂੰ ॥੪॥੧੩॥੨੦॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-5", gurmukhi = "ਸਲੋਕੁ ਮਃ ੧ ॥", transliteration = "salok mh 1 ||", translation = "Salok, First Mehl:", hindi = "सलोकु मः १ ॥", punjabi = "ਸਲੋਕ ਪਹਿਲੀ ਪਾਤਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-6", gurmukhi = "ਦੁਖੁ ਦਾਰੂ. ਸੁਖੁ ਰੋਗੁ ਭਇਆ; ਜਾ ਸੁਖੁ. ਤਾਮਿ ਨ ਹੋਈ ॥", transliteration = "dukh daaroo. sukh rog bhaiaa; jaa sukh. taam na hoee ||", translation = "Suffering is the medicine, and pleasure the disease, because where there is pleasure, there is no desire for God.", hindi = "दुखु दारू. सुखु रोगु भइआ; जा सुखु. तामि न होई ॥", punjabi = "(ਹੇ ਪ੍ਰਭੂ! ਤੇਰੀ ਅਜਬ ਕੁਦਰਤ ਹੈ ਕਿ) ਬਿਪਤਾ (ਜੀਵਾਂ ਦੇ ਰੋਗਾਂ ਦਾ) ਇਲਾਜ (ਬਣ ਜਾਂਦੀ) ਹੈ, ਅਤੇ ਸੁਖ (ਉਹਨਾਂ ਲਈ) ਦੁੱਖ ਦਾ (ਕਾਰਨ) ਹੋ ਜਾਂਦਾ ਹੈ। ਪਰ ਜੇ (ਅਸਲੀ ਆਤਮਕ) ਸੁਖ (ਜੀਵ ਨੂੰ) ਮਿਲ ਜਾਏ, ਤਾਂ (ਦੁੱਖ) ਨਹੀਂ ਰਹਿੰਦਾ।", wordMeaning = "ਤਾਮਿ = ਤਦੋਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-7", gurmukhi = "ਤੂੰ ਕਰਤਾ ਕਰਣਾ, ਮੈ ਨਾਹੀ; ਜਾ ਹਉ ਕਰੀ. ਨ ਹੋਈ ॥੧॥", transliteration = "toon kartaa karnaa, mai naahee; jaa hau kree. na hoee ||1||", translation = "You are the Creator Lord; I can do nothing. Even if I try, nothing happens. ||1||", hindi = "तूं करता करणा, मै नाही; जा हउ करी. न होई ॥१॥", punjabi = "ਹੇ ਪ੍ਰਭੂ! ਤੂੰ ਕਰਨਹਾਰ ਕਰਤਾਰ ਹੈਂ (ਤੂੰ ਆਪ ਹੀ ਇਹਨਾਂ ਭੇਤਾਂ ਨੂੰ ਸਮਝਦਾ ਹੈਂ), ਮੇਰੀ ਸਮਰਥਾ ਨਹੀਂ ਹੈ (ਕਿ ਮੈਂ ਸਮਝ ਸਕਾਂ)। ਜੇ ਮੈਂ ਆਪਣੇ ਆਪ ਨੂੰ ਕੁਝ ਸਮਝ ਲਵਾਂ (ਭਾਵ, ਜੇ ਮੈਂ ਇਹ ਖ਼ਿਆਲ ਕਰਨ ਲੱਗ ਪਵਾਂ ਕਿ ਮੈਂ ਤੇਰੇ ਭੇਤ ਨੂੰ ਸਮਝ ਸਕਦਾ ਹਾਂ) ਤਾਂ ਇਹ ਗੱਲ ਫਬਦੀ ਨਹੀਂ ॥੧॥", wordMeaning = "ਕਰਣਾ = ਕਰਨਹਾਰ। ਮੈ ਨਾਹੀ = ਮੈਂ ਕੁਝ ਭੀ ਨਹੀਂ, ਮੇਰੀ ਕੋਈ ਪਾਂਇਆਂ ਨਹੀਂ ਹੈ। ਜਾ ਹਉ ਕਰੀ = ਜੇ ਮੈਂ 'ਹਉ' ਆਖਾਂ, ਜੇ ਮੈਂ ਆਪਣੇ ਆਪ ਨੂੰ ਕੁਝ ਸਮਝ ਬੈਠਾਂ। ਨ ਹੋਈ = ਨਹੀਂ ਫਬਦਾ, ਇਹ ਗੱਲ ਫਬਦੀ ਨਹੀਂ ॥੧॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-8", gurmukhi = "ਬਲਿਹਾਰੀ ਕੁਦਰਤਿ ਵਸਿਆ ॥", transliteration = "balihaaree kudarat vsiaa ||", translation = "I am a sacrifice to Your almighty creative power which is pervading everywhere.", hindi = "बलिहारी कुदरति वसिआ ॥", punjabi = "ਹੇ ਕੁਦਰਤ ਵਿਚ ਵੱਸ ਰਹੇ ਕਰਤਾਰ! ਮੈਂ ਤੈਥੋਂ ਸਦਕੇ ਹਾਂ,", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-9", gurmukhi = "ਤੇਰਾ ਅੰਤੁ. ਨ ਜਾਈ ਲਖਿਆ ॥੧॥ ਰਹਾਉ ॥", transliteration = "teraa ant. na jaaee lkhiaa ||1|| rhaau ||", translation = "Your limits cannot be known. ||1||Pause||", hindi = "तेरा अंतु. न जाई लखिआ ॥१॥ रहाउ ॥", punjabi = "ਤੇਰਾ ਅੰਤ ਪਾਇਆ ਨਹੀਂ ਜਾ ਸਕਦਾ ॥੧॥ ਰਹਾਉ ॥", wordMeaning = "॥੧॥ਰਹਾਉ॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-10", gurmukhi = "ਜਾਤਿ ਮਹਿ ਜੋਤਿ. ਜੋਤਿ ਮਹਿ ਜਾਤਾ; ਅਕਲ ਕਲਾ ਭਰਪੂਰਿ ਰਹਿਆ ॥", transliteration = "jaat mah jot. jot mah jaataa; akal klaa bharpoor rhiaa ||", translation = "Your Light is in Your creatures, and Your creatures are in Your Light; Your almighty power is pervading everywhere.", hindi = "जाति महि जोति. जोति महि जाता; अकल कला भरपूरि रहिआ ॥", punjabi = "ਸਾਰੀ ਸ੍ਰਿਸ਼ਟੀ ਵਿਚ ਤੇਰਾ ਹੀ ਨੂਰ ਵੱਸ ਰਿਹਾ ਹੈ, ਸਾਰੇ ਜੀਵਾਂ ਵਿਚ ਤੇਰਾ ਹੀ ਪ੍ਰਕਾਸ਼ ਹੈ, ਤੂੰ ਸਭ ਥਾਈਂ ਇਕ-ਰਸ ਵਿਆਪਕ ਹੈਂ।", wordMeaning = "ਜਾਤਿ = ਸ੍ਰਿਸ਼ਟੀ। ਜੋਤਿ = ਰੱਬ ਦਾ ਨੂਰ। ਜੋਤਿ ਮਹਿ = ਸਾਰੀਆਂ ਜੋਤੀਆਂ ਵਿਚ, ਸਾਰੇ ਜੀਵਾਂ ਵਿਚ। ਜਾਤਾ = ਵੇਖਿਆ ਜਾਂਦਾ ਹੈ, ਦਿੱਸ ਰਿਹਾ ਹੈ। ਅਕਲ = ਸੰਪੂਰਨ। ਕਲਾ = ਟੋਟਾ, ਹਿੱਸਾ। ਅਕਲ ਕਲਾ = ਜਿਸ ਦੇ ਵਖੋ ਵਖਰੇ ਟੋਟੇ ਨਾ ਹੋਣ, ਇਕ-ਰਸ ਸੰਪੂਰਣ ਪ੍ਰਭੂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-11", gurmukhi = "ਤੂੰ ਸਚਾ ਸਾਹਿਬੁ. ਸਿਫਤਿ ਸੁਆਲੑਿਉ; ਜਿਨਿ ਕੀਤੀ. ਸੋ ਪਾਰਿ ਪਇਆ ॥", transliteration = "toon schaa saahib. siphat suaalhiu; jin keetee. so paar paiaa ||", translation = "You are the True Lord and Master; Your Praise is so beautiful. One who sings it, is carried across.", hindi = "तूं सचा साहिबु. सिफति सुआल्हिउ; जिनि कीती. सो पारि पइआ ॥", punjabi = "ਹੇ ਪ੍ਰਭੂ! ਤੂੰ ਸਦਾ-ਥਿਰ ਰਹਿਣ ਵਾਲਾ ਹੈਂ, ਤੇਰੀਆਂ ਸੋਹਣੀਆਂ ਵਡਿਆਈਆਂ ਹਨ। ਜਿਸ ਜਿਸ ਨੇ ਤੇਰੇ ਗੁਣ ਗਾਏ ਹਨ, ਉਹ ਸੰਸਾਰ-ਸਮੁੰਦਰ ਤੋਂ ਤਰ ਗਿਆ ਹੈ।", wordMeaning = "ਸੁਆਲਿਉ = ਸੋਹਣੀ, ਸੁੰਦਰ। ਜਿਨਿ ਕੀਤੀ = ਜਿਸਨੇ (ਤੇਰੀ ਵਡਿਆਈ) ਕੀਤੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-12", gurmukhi = "ਕਹੁ ਨਾਨਕ. ਕਰਤੇ ਕੀਆ ਬਾਤਾ; ਜੋ ਕਿਛੁ ਕਰਣਾ, ਸੁ ਕਰਿ ਰਹਿਆ ॥੨॥", transliteration = "kah naanak. karte keeaa baataa; jo kichh karnaa, su kar rhiaa ||2||", translation = "Nanak speaks the stories of the Creator Lord; whatever He is to do, He does. ||2||", hindi = "कहु नानक. करते कीआ बाता; जो किछु करणा, सु करि रहिआ ॥२॥", punjabi = "ਹੇ ਨਾਨਕ! (ਤੂੰ ਭੀ) ਕਰਤਾਰ ਦੀ ਸਿਫ਼ਤਿ-ਸਾਲਾਹ ਕਰ, (ਤੇ ਆਖ ਕਿ) ਪ੍ਰਭੂ ਜੋ ਕੁਝ ਕਰਨਾ ਚੰਗਾ ਸਮਝਦਾ ਹੈ ਉਹ ਕਰ ਰਿਹਾ ਹੈ (ਭਾਵ, ਉਸ ਦੇ ਕੰਮਾਂ ਵਿਚ ਕਿਸੇ ਦਾ ਦਖ਼ਲ ਨਹੀਂ ਹੈ) ॥੨॥", wordMeaning = "ਨਾਨਕ = ਹੇ ਨਾਨਕ! ਕਹੁ ਕਰਤੇ ਕੀਆ ਬਾਤਾ = ਕਰਤਾਰ ਦੀਆਂ ਗੱਲਾਂ ਆਖ ॥੨॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-13", gurmukhi = "ਸੋ ਦਰੁ ਰਾਗੁ ਆਸਾ ਮਹਲਾ ੧ ॥", transliteration = "so dar raag aasaa mahlaa 1 ||", translation = "So Dar ~ That Door. Raag Aasaa, First Mehl:", hindi = "सो दरु रागु आसा महला १ ॥", punjabi = "ਰਾਗ ਆਸਾ ਵਿੱਚ ਗੁਰੂ ਨਾਨਕ ਜੀ ਦੀ ਬਾਣੀ 'ਸੋ-ਦਰ'।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-14", gurmukhi = "ੴ ਸਤਿਗੁਰ ਪ੍ਰਸਾਦਿ ॥", transliteration = "ik oankar stigur prasaad ||", translation = "One Universal Creator God. By The Grace Of The True Guru:", hindi = "एकओंकार सतिगुर प्रसादि ॥", punjabi = "ਅਕਾਲ ਪੁਰਖ ਇੱਕ ਹੈ ਅਤੇ ਸਤਿਗੁਰੂ ਦੀ ਕਿਰਪਾ ਨਾਲ ਮਿਲਦਾ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-15", gurmukhi = "ਸੋ ਦਰੁ ਤੇਰਾ ਕੇਹਾ, ਸੋ ਘਰੁ ਕੇਹਾ; ਜਿਤੁ ਬਹਿ ਸਰਬ ਸਮਾਲੇ ॥", transliteration = "so dar teraa kehaa, so ghar kehaa; jit bah sarab smaale ||", translation = "Where is That Door of Yours, and where is That Home, in which You sit and take care of all?", hindi = "सो दरु तेरा केहा, सो घरु केहा; जितु बहि सरब समाले ॥", punjabi = "(ਹੇ ਪ੍ਰਭੂ!) ਤੇਰਾ ਉਹ ਘਰ ਅਤੇ (ਉਸ ਘਰ ਦਾ) ਉਹ ਦਰਵਾਜ਼ਾ ਬੜਾ ਹੀ ਅਸਚਰਜ ਹੋਵੇਗਾ, ਜਿੱਥੇ ਬੈਠ ਕੇ ਤੂੰ ਸਾਰੇ ਜੀਵਾਂ ਦੀ ਸੰਭਾਲ ਕਰ ਰਿਹਾ ਹੈਂ।", wordMeaning = "ਕੇਹਾ = ਕਿਹੋ ਜਿਹਾ? ਬੜਾ ਅਚਰਜ। ਦਰੁ = ਦਰਵਾਜ਼ਾ। ਜਿਤੁ = ਜਿੱਥੇ। ਬਹਿ = ਬੈਠ ਕੇ। ਸਰਬ = ਸਾਰੇ ਜੀਵਾਂ ਨੂੰ। ਸਮਾਲੇ = ਤੂੰ ਸੰਭਾਲ ਕੀਤੀ ਹੈ, ਤੂੰ ਸੰਭਾਲ ਕਰ ਰਿਹਾ ਹੈਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-16", gurmukhi = "ਵਾਜੇ ਤੇਰੇ ਨਾਦ ਅਨੇਕ ਅਸੰਖਾ; ਕੇਤੇ ਤੇਰੇ ਵਾਵਣਹਾਰੇ ॥", transliteration = "vaaje tere naad anek asankhaa; kete tere vaavanhaare ||", translation = "The Sound-current of the Naad vibrates there for You, and countless musicians play all sorts of instruments there for You.", hindi = "वाजे तेरे नाद अनेक असंखा; केते तेरे वावणहारे ॥", punjabi = "(ਤੇਰੀ ਇਸ ਰਚੀ ਹੋਈ ਕੁਦਰਤ ਵਿਚ) ਅਨੇਕਾਂ ਤੇ ਅਣਗਿਣਤ ਵਾਜੇ ਤੇ ਰਾਗ ਹਨ; ਬੇਅੰਤ ਹੀ ਜੀਵ (ਉਹਨਾਂ ਵਾਜਿਆਂ ਨੂੰ) ਵਜਾਣ ਵਾਲੇ ਹਨ।", wordMeaning = "ਨਾਦ = ਆਵਾਜ਼ਾਂ, ਸਬਦ, ਰਾਗ। ਵਾਵਣਹਾਰੇ = ਵਜਾਣ ਵਾਲੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-17", gurmukhi = "ਕੇਤੇ ਤੇਰੇ, ਰਾਗ ਪਰੀ ਸਿਉ ਕਹੀਅਹਿ; ਕੇਤੇ ਤੇਰੇ ਗਾਵਣਹਾਰੇ ॥", transliteration = "kete tere, raag pree siu kheeah; kete tere gaavanhaare ||", translation = "There are so many Ragas and musical harmonies to You; so many minstrels sing hymns of You.", hindi = "केते तेरे, राग परी सिउ कहीअहि; केते तेरे गावणहारे ॥", punjabi = "ਰਾਗਣੀਆਂ ਸਮੇਤ ਬੇਅੰਤ ਹੀ ਰਾਗਾਂ ਦੇ ਨਾਮ ਲਏ ਜਾਂਦੇ ਹਨ। ਅਨੇਕਾਂ ਹੀ ਜੀਵ (ਇਹਨਾਂ ਰਾਗ-ਰਾਗਣੀਆਂ ਦੀ ਰਾਹੀਂ ਤੈਨੂੰ) ਗਾਣ ਵਾਲੇ ਹਨ (ਤੇਰੀ ਸਿਫ਼ਤਿ ਦੇ ਗੀਤ ਗਾ ਰਹੇ ਹਨ)।", wordMeaning = "ਪਰੀ = ਰਾਗ ਪਰੀ, ਰਾਗਣੀਆਂ। ਸਿਉ = ਸਮੇਤ, ਸਣੇ। ਪਰੀ ਸਿਉ = ਰਾਗਣੀਆਂ ਸਮੇਤ। ਕਹੀਅਹਿ = ਕਹੇ ਜਾਂਦੇ ਹਨ, ਆਖੇ ਜਾਂਦੇ ਹਨ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-18", gurmukhi = "ਗਾਵਨਿ ਤੁਧਨੋ ਪਵਣੁ ਪਾਣੀ ਬੈਸੰਤਰੁ; ਗਾਵੈ ਰਾਜਾ ਧਰਮੁ ਦੁਆਰੇ ॥", transliteration = "gaavan tudhno pavan paanee baisantar; gaavai raajaa dharam duaare ||", translation = "Wind, water and fire sing of You. The Righteous Judge of Dharma sings at Your Door.", hindi = "गावनि तुधनो पवणु पाणी बैसंतरु; गावै राजा धरमु दुआरे ॥", punjabi = "(ਹੇ ਪ੍ਰਭੂ!) ਹਵਾ ਪਾਣੀ ਅੱਗ (ਆਦਿਕ ਤੱਤ) ਤੇਰੇ ਗੁਣ ਗਾ ਰਹੇ ਹਨ (ਤੇਰੀ ਰਜ਼ਾ ਵਿਚ ਤੁਰ ਰਹੇ ਹਨ)। ਧਰਮ ਰਾਜ (ਤੇਰੇ) ਦਰ ਤੇ (ਖਲੋ ਕੇ ਤੇਰੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਦੇ ਗੀਤ) ਗਾ ਰਿਹਾ ਹੈ।", wordMeaning = "ਗਾਵਨਿ = ਗਾਂਦੇ ਹਨ। ਤੁਧ ਨੋ = ਤੈਨੂੰ। ਬੈਸੰਤਰੁ = ਅੱਗ। ਗਾਵੈ = ਗਾਂਦਾ ਹੈ {'ਗਾਵੈ' ਇਕ-ਵਚਨ ਹੈ, 'ਗਾਵਨਿ' ਬਹੁ-ਵਚਨ ਹੈ}। ਰਾਜਾ ਧਰਮੁ = ਧਰਮ ਰਾਜ। ਦੁਆਰੇ = (ਹੇ ਪ੍ਰਭੂ! ਤੇਰੇ) ਦਰ ਤੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-19", gurmukhi = "ਗਾਵਨਿ ਤੁਧਨੋ ਚਿਤੁ ਗੁਪਤੁ ਲਿਖਿ ਜਾਣਨਿ; ਲਿਖਿ ਲਿਖਿ ਧਰਮੁ ਬੀਚਾਰੇ ॥", transliteration = "gaavan tudhno chit gupat likh jaanan; likh likh dharam beechaare ||", translation = "Chitr and Gupt, the angels of the conscious and the subconscious who keep the record of actions, and the Righteous Judge of Dharma who reads this record, sing of You.", hindi = "गावनि तुधनो चितु गुपतु लिखि जाणनि; लिखि लिखि धरमु बीचारे ॥", punjabi = "ਉਹ ਚਿੱਤਰ ਗੁਪਤ ਭੀ ਜੋ (ਜੀਵਾਂ ਦੇ ਚੰਗੇ ਮੰਦੇ ਕਰਮਾਂ ਦੇ ਲੇਖੇ) ਲਿਖਣੇ ਜਾਣਦੇ ਹਨ ਅਤੇ ਜਿਨ੍ਹਾਂ ਦੇ ਲਿਖੇ ਹੋਏ ਧਰਮ ਰਾਜ ਵਿਚਾਰਦਾ ਹੈ ਤੇਰੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਦੇ ਗੀਤ ਗਾ ਰਹੇ ਹਨ।", wordMeaning = "ਚਿਤੁ ਗੁਪਤੁ = ਪੁਰਾਤਨ ਹਿੰਦੂ ਖ਼ਿਆਲ ਤੁਰਿਆ ਆ ਰਿਹਾ ਹੈ ਕਿ ਇਹ ਦੋਵੇਂ ਵਿਅਕਤੀਆਂ ਚਿੱਤਰ ਅਤੇ ਗੁਪਤ ਸਾਰੇ ਜੀਵਾਂ ਦੇ ਕੀਤੇ ਚੰਗੇ ਮੰਦੇ ਕਰਮਾਂ ਦੇ ਲੇਖੇ ਲਿਖਦੇ ਰਹਿੰਦੇ ਹਨ। ਲਿਖਿ ਜਾਣਹਿ = {Know to write} ਲਿਖਣਾ ਜਾਣਦੇ ਹਨ। ਲਿਖਿ ਲਿਖਿ = (ਹਰ ਵੇਲੇ) ਲਿਖ ਲਿਖ ਕੇ (ਜੋ ਕੁਝ ਉਹ ਚਿੱਤਰ ਗੁਪਤ ਹਰ ਵੇਲੇ ਲਿਖਦੇ ਰਹਿੰਦੇ ਹਨ)।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-20", gurmukhi = "ਗਾਵਨਿ ਤੁਧਨੋ ਈਸਰੁ ਬ੍ਰਹਮਾ ਦੇਵੀ; ਸੋਹਨਿ ਤੇਰੇ ਸਦਾ ਸਵਾਰੇ ॥", transliteration = "gaavan tudhno eesar brahmaa devee; sohan tere sdaa svaare ||", translation = "Shiva, Brahma and the Goddess of Beauty, ever adorned by You, sing of You.", hindi = "गावनि तुधनो ईसरु ब्रहमा देवी; सोहनि तेरे सदा सवारे ॥", punjabi = "(ਹੇ ਪ੍ਰਭੂ!) ਅਨੇਕਾਂ ਦੇਵੀਆਂ ਸ਼ਿਵ ਅਤੇ ਬ੍ਰਹਮਾ (ਆਦਿਕ ਦੇਵਤੇ) ਜੋ ਤੇਰੇ ਸਵਾਰੇ ਹੋਏ ਹਨ ਸਦਾ (ਤੇਰੇ ਦਰ ਤੇ) ਸੋਭ ਰਹੇ ਹਨ ਤੈਨੂੰ ਗਾ ਰਹੇ ਹਨ (ਤੇਰੇ ਗੁਣ ਗਾ ਰਹੇ ਹਨ)।", wordMeaning = "ਈਸਰੁ = ਸ਼ਿਵ। ਦੇਵੀ = ਦੇਵੀਆਂ। ਸੋਹਨਿ = ਸੋਹਣੇ ਲੱਗਦੇ ਹਨ, ਸੋਭਦੇ ਹਨ। ਸਵਾਰੇ = ਸੋਹਣੇ ਬਣਾਏ ਹੋਏ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-21", gurmukhi = "ਗਾਵਨਿ ਤੁਧਨੋ ਇੰਦ੍ਰ. ਇੰਦ੍ਰਾਸਣਿ ਬੈਠੇ; ਦੇਵਤਿਆ ਦਰਿ ਨਾਲੇ ॥", transliteration = "gaavan tudhno indr. indraasan baithe; devtiaa dar naale ||", translation = "Indra, seated on His Throne, sings of You, with the deities at Your Door.", hindi = "गावनि तुधनो इंद्र. इंद्रासणि बैठे; देवतिआ दरि नाले ॥", punjabi = "ਕਈ ਇੰਦਰ ਦੇਵਤੇ ਆਪਣੇ ਤਖ਼ਤ ਉੱਤੇ ਬੈਠੇ ਹੋਏ ਦੇਵਤਿਆਂ ਸਮੇਤ ਤੇਰੇ ਦਰ ਉੱਤੇ ਤੈਨੂੰ ਗਾ ਰਹੇ ਹਨ (ਤੇਰੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਦੇ ਗੀਤ ਗਾ ਰਹੇ ਹਨ)।", wordMeaning = "ਇੰਦ੍ਰਾਸਣਿ = {ਇੰਦ੍ਰ = ਆਸਣ} ਇੰਦਰ ਦੇ ਆਸਣ ਉੱਤੇ (ਬੈਠੇ ਹੋਏ)। ਦਰਿ = ਤੇਰੇ ਦਰਵਾਜ਼ੇ ਉੱਤੇ। ਦੇਵਤਿਆ ਨਾਲੇ = ਦੇਵਤਿਆਂ ਸਮੇਤ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-22", gurmukhi = "ਗਾਵਨਿ ਤੁਧਨੋ ਸਿਧ ਸਮਾਧੀ ਅੰਦਰਿ; ਗਾਵਨਿ ਤੁਧਨੋ ਸਾਧ ਬੀਚਾਰੇ ॥", transliteration = "gaavan tudhno sidh smaadhee andar; gaavan tudhno saadh beechaare ||", translation = "The Siddhas in Samaadhi sing of You; the Saadhus sing of You in contemplation.", hindi = "गावनि तुधनो सिध समाधी अंदरि; गावनि तुधनो साध बीचारे ॥", punjabi = "(ਹੇ ਪ੍ਰਭੂ!) ਸਿੱਧ ਲੋਕ ਸਮਾਧੀਆਂ ਲਾ ਕੇ ਤੈਨੂੰ ਗਾ ਰਹੇ ਹਨ। ਸਾਧ ਜਨ (ਤੇਰੇ ਗੁਣਾਂ ਦੀ) ਵਿਚਾਰ ਕਰ ਕੇ ਤੈਨੂੰ ਸਲਾਹ ਰਹੇ ਹਨ।", wordMeaning = "ਸਮਾਧੀ ਅੰਦਰਿ = ਸਮਾਧੀ ਵਿਚ ਜੁੜ ਕੇ। ਸਿਧ = ਜੋਗ ਸਾਧਨਾਂ ਵਿਚ ਪੁੱਗੇ ਹੋਏ ਜੋਗੀ, ਉਹ ਵਿਅਕਤੀਆਂ ਜੋ ਮਨੁੱਖਾਂ ਦੀ ਸ਼੍ਰੇਣੀ ਤੋਂ ਅਗਾਂਹ ਅਤੇ ਦੇਵਤਿਆਂ ਤੋਂ ਹੇਠ ਮੰਨੀਆਂ ਜਾਂਦੀਆਂ ਹਨ; ਇਹ ਸਿੱਧ ਪਵਿਤ੍ਰਤਾ ਦਾ ਪੁੰਜ ਅਤੇ ਅੱਠਾਂ ਹੀ ਸਿੱਧੀਆਂ ਦੇ ਮਾਲਕ ਸਮਝੇ ਜਾਂਦੇ ਹਨ। ਬੀਚਾਰੇ = ਬੀਚਾਰਿ, ਵਿਚਾਰ ਕੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-23", gurmukhi = "ਗਾਵਨਿ ਤੁਧਨੋ ਜਤੀ ਸਤੀ ਸੰਤੋਖੀ; ਗਾਵਨਿ ਤੁਧਨੋ ਵੀਰ ਕਰਾਰੇ ॥", transliteration = "gaavan tudhno jtee stee santokhee; gaavan tudhno veer kraare ||", translation = "The celibates, the fanatics, and the peacefully accepting sing of You; the fearless warriors sing of You.", hindi = "गावनि तुधनो जती सती संतोखी; गावनि तुधनो वीर करारे ॥", punjabi = "ਜਤੀ, ਦਾਨੀ ਅਤੇ ਸੰਤੋਖੀ ਬੰਦੇ ਭੀ ਤੇਰੇ ਹੀ ਗੁਣ ਗਾ ਰਹੇ ਹਨ। ਬੇਅੰਤ ਤਕੜੇ ਸੂਰਮੇ ਤੇਰੀਆਂ ਹੀ ਵਡਿਆਈਆਂ ਕਰ ਰਹੇ ਹਨ।", wordMeaning = "ਜਤੀ = ਕਾਮ-ਵਾਸ਼ਨਾ ਨੂੰ ਰੋਕ ਕੇ ਰੱਖਣ ਵਾਲੇ। ਸਤੀ = ਦਾਨੀ। ਵੀਰ = ਸੂਰਮੇ। ਕਰਾਰੇ = ਤਕੜੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-24", gurmukhi = "ਗਾਵਨਿ ਤੁਧਨੋ, ਪੰਡਿਤ ਪੜਨਿ ਰਖੀਸੁਰ; ਜੁਗੁ ਜੁਗੁ ਵੇਦਾ ਨਾਲੇ ॥", transliteration = "gaavan tudhno, pandit paran rkheesur; jug jug vedaa naale ||", translation = "The Pandits, the religious scholars who recite the Vedas, with the supreme sages of all the ages, sing of You.", hindi = "गावनि तुधनो, पंडित पड़नि रखीसुर; जुगु जुगु वेदा नाले ॥", punjabi = "(ਹੇ ਪ੍ਰਭੂ!) ਪੰਡਿਤ ਅਤੇ ਮਹਾ ਰਿਖੀ ਜੋ (ਵੇਦਾਂ ਨੂੰ ਪੜ੍ਹਦੇ ਹਨ, ਵੇਦਾਂ ਸਣੇ ਤੇਰਾ ਹੀ ਜਸ ਕਰ ਰਹੇ ਹਨ।", wordMeaning = "ਪੜਨਿ = ਪੜ੍ਹਦੇ ਹਨ। ਰਖੀਸੁਰ = {ਰਿਖੀ = ਈਸਰੁ} ਵੱਡੇ ਵੱਡੇ ਰਿਖੀ, ਮਹਾਂ ਰਿਖੀ। ਜੁਗੁ ਜੁਗੁ = ਹਰੇਕ ਜੁਗ ਵਿਚ। ਵੇਦਾ ਨਾਲੇ = ਵੇਦਾਂ ਸਣੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-25", gurmukhi = "ਗਾਵਨਿ ਤੁਧਨੋ ਮੋਹਣੀਆ ਮਨੁ ਮੋਹਨਿ; ਸੁਰਗੁ ਮਛੁ ਪਇਆਲੇ ॥", transliteration = "gaavan tudhno mohneeaa man mohan; surag machh paiaale ||", translation = "The Mohinis, the enchanting heavenly beauties who entice hearts in paradise, in this world, and in the underworld of the subconscious, sing of You.", hindi = "गावनि तुधनो मोहणीआ मनु मोहनि; सुरगु मछु पइआले ॥", punjabi = "ਸੁੰਦਰ ਇਸਤ੍ਰੀਆਂ ਜੋ (ਆਪਣੀ ਸੁੰਦਰਤਾ ਨਾਲ ਮਨੁੱਖ ਦੇ) ਮਨ ਨੂੰ ਮੋਹ ਲੈਂਦੀਆਂ ਹਨ ਤੈਨੂੰ ਹੀ ਗਾ ਰਹੀਆਂ ਹਨ, (ਭਾਵ, ਤੇਰੀ ਸੁੰਦਰਤਾ ਦਾ ਪਰਕਾਸ਼ ਕਰ ਰਹੀਆਂ ਹਨ)। ਸੁਰਗ-ਲੋਕ, ਮਾਤ-ਲੋਕ ਅਤੇ ਪਤਾਲ-ਲੋਕ (ਭਾਵ, ਸੁਰਗ ਮਾਤ ਅਤੇ ਪਤਾਲ ਦੇ ਸਾਰੇ ਜੀਆ ਜੰਤ) ਤੇਰੀ ਹੀ ਵਡਿਆਈ ਕਰ ਰਹੇ ਹਨ।", wordMeaning = "ਮੋਹਣੀਆ = ਸੁੰਦਰ ਇਸਤ੍ਰੀਆਂ। ਮਨੁ ਮੋਹਨਿ = ਜੋ ਮਨ ਨੂੰ ਮੋਹ ਲੈਂਦੀਆਂ ਹਨ। ਮਛੁ = ਮਾਤ ਲੋਕ। ਪਇਆਲੇ = ਪਾਤਾਲ ਲੋਕ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-26", gurmukhi = "ਗਾਵਨਿ ਤੁਧਨੋ, ਰਤਨ ਉਪਾਏ ਤੇਰੇ; ਅਠਸਠਿ ਤੀਰਥ ਨਾਲੇ ॥", transliteration = "gaavan tudhno, ratan upaae tere; athasath teerath naale ||", translation = "The celestial jewels created by You, and the sixty-eight sacred shrines of pilgrimage, sing of You.", hindi = "गावनि तुधनो, रतन उपाए तेरे; अठसठि तीरथ नाले ॥", punjabi = "(ਹੇ ਪ੍ਰਭੂ!) ਤੇਰੇ ਪੈਦਾ ਕੀਤੇ ਹੋਏ ਰਤਨ ਅਠਾਹਠ ਤੀਰਥਾਂ ਸਮੇਤ ਤੈਨੂੰ ਹੀ ਗਾ ਰਹੇ ਹਨ।", wordMeaning = "ਉਪਾਏ ਤੇਰੇ = ਤੇਰੇ ਕੀਤੇ ਹੋਏ। ਅਠਸਠਿ = ਅਠਾਹਠ। ਤੀਰਥ ਨਾਲੇ = ਤੀਰਥਾਂ ਸਮੇਤ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-27", gurmukhi = "ਗਾਵਨਿ ਤੁਧਨੋ ਜੋਧ ਮਹਾਬਲ ਸੂਰਾ; ਗਾਵਨਿ ਤੁਧਨੋ ਖਾਣੀ ਚਾਰੇ ॥", transliteration = "gaavan tudhno jodh mhaabal sooraa; gaavan tudhno khaanee chaare ||", translation = "The brave and mighty warriors sing of You. The spiritual heroes and the four sources of creation sing of You.", hindi = "गावनि तुधनो जोध महाबल सूरा; गावनि तुधनो खाणी चारे ॥", punjabi = "ਵੱਡੇ ਬਲ ਵਾਲੇ ਜੋਧੇ ਅਤੇ ਸੂਰਮੇ (ਤੇਰਾ ਦਿੱਤਾ ਬਲ ਵਿਖਾ ਕੇ) ਤੇਰੀ ਹੀ (ਤਾਕਤ ਦੀ) ਸਿਫ਼ਤਿ ਕਰ ਰਹੇ ਹਨ। ਚੌਹਾਂ ਹੀ ਖਾਣੀਆਂ ਦੇ ਜੀਅ ਜੰਤ ਤੈਨੂੰ ਗਾ ਰਹੇ ਹਨ।", wordMeaning = "ਜੋਧ = ਜੋਧੇ। ਮਹਾਬਲ = ਵੱਡੇ ਬਲ ਵਾਲੇ। ਸੂਰਾ = ਸੂਰਮੇ। ਖਾਣੀ ਚਾਰੇ = ਚਾਰੇ ਖਾਣੀਆਂ {ਅੰਡਜ, ਜੇਰਜ, ਸੇਤਜ, ਉਤਭੁਜ}। ਖਾਣੀ = ਖਾਣ ਜਿਸ ਨੂੰ ਪੁੱਟ ਕੇ ਵਿਚੋਂ ਧਾਤਾਂ ਜਾਂ ਰਤਨ ਆਦਿਕ ਪਦਾਰਥ ਕੱਢੇ ਜਾਣ {ਖਨ = ਪੁੱਟਣਾ}। ਪੁਰਾਤਨ ਖ਼ਿਆਲ ਤੁਰਿਆ ਆ ਰਿਹਾ ਹੈ ਕਿ ਜਗਤ ਦੇ ਸਾਰੇ ਜੀਵ ਚਾਰ ਖਾਣੀਆਂ ਤੋਂ ਪੈਦਾ ਹੋਏ ਹਨ: ਅੰਡਾ, ਜਿਓਰ, ਮੁੜਕਾ, ਪਾਣੀ ਦੀ ਸਹੈਤਾ ਨਾਲ ਧਰਤੀ ਵਿਚੋਂ ਆਪਣੇ ਆਪ ਉੱਗ ਪੈਣਾ (ਇਥੇ ਭਾਵ ਹੈ, ਚੌਹਾਂ ਹੀ ਖਾਣੀਆਂ ਦੇ ਜੀਵ, ਸਾਰੀ ਰਚਨਾ)।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-28", gurmukhi = "ਗਾਵਨਿ ਤੁਧਨੋ ਖੰਡ ਮੰਡਲ ਬ੍ਰਹਮੰਡਾ; ਕਰਿ ਕਰਿ ਰਖੇ ਤੇਰੇ ਧਾਰੇ ॥", transliteration = "gaavan tudhno khand mandal brahamandaa; kar kar rkhe tere dhaare ||", translation = "The worlds, solar systems and galaxies, created and arranged by Your Hand, sing of You.", hindi = "गावनि तुधनो खंड मंडल ब्रहमंडा; करि करि रखे तेरे धारे ॥", punjabi = "ਸਾਰੀ ਸ੍ਰਿਸ਼ਟੀ, ਸ੍ਰਿਸ਼ਟੀ ਦੇ ਸਾਰੇ ਖੰਡ ਤੇ ਮੰਡਲ, ਜੋ ਤੂੰ ਪੈਦਾ ਕਰ ਕੇ ਟਿਕਾ ਰੱਖੇ ਹਨ, ਤੈਨੂੰ ਹੀ ਗਾਉਂਦੇ ਹਨ।", wordMeaning = "ਖੰਡ = ਟੋਟਾ, ਬ੍ਰਹਮੰਡ ਦਾ ਟੋਟਾ, ਹਰੇਕ ਧਰਤੀ। ਮੰਡਲ = ਚੱਕ੍ਰ, ਬ੍ਰਹਮੰਡ ਦਾ ਇਕ ਚੱਕ੍ਰ ਜਿਸ ਵਿਚ ਇੱਕ ਸੂਰਜ, ਇੱਕ ਚੰਦ੍ਰਮਾ ਅਤੇ ਧਰਤੀ ਆਦਿਕ ਗਿਣੇ ਜਾਂਦੇ ਹਨ। ਬ੍ਰਹਮੰਡ = ਸਾਰੀ ਸ੍ਰਿਸ਼ਟੀ। ਕਰਿ ਕਰਿ = ਬਣਾ ਕੇ। ਧਾਰੇ = ਟਿਕਾਏ ਹੋਏ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-29", gurmukhi = "ਸੇਈ ਤੁਧਨੋ ਗਾਵਨਿ, ਜੋ ਤੁਧੁ ਭਾਵਨਿ; ਰਤੇ ਤੇਰੇ ਭਗਤ ਰਸਾਲੇ ॥", transliteration = "seee tudhno gaavan, jo tudh bhaavan; rte tere bhagat rsaale ||", translation = "They alone sing of You, who are pleasing to Your Will. Your devotees are imbued with Your Sublime Essence.", hindi = "सेई तुधनो गावनि, जो तुधु भावनि; रते तेरे भगत रसाले ॥", punjabi = "(ਹੇ ਪ੍ਰਭੂ!) ਅਸਲ ਵਿਚ ਉਹੀ ਬੰਦੇ ਤੇਰੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਕਰਦੇ ਹਨ (ਭਾਵ, ਉਹਨਾਂ ਦੀ ਕੀਤੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਸਫਲ ਹੈ) ਜੋ ਤੇਰੇ ਪ੍ਰੇਮ ਵਿਚ ਰੰਗੇ ਹੋਏ ਹਨ ਅਤੇ ਤੇਰੇ ਰਸੀਏ ਭਗਤ ਹਨ, ਉਹੀ ਬੰਦੇ ਤੈਨੂੰ ਪਿਆਰੇ ਲੱਗਦੇ ਹਨ।", wordMeaning = "ਸੇਈ = ਉਹੀ ਬੰਦੇ। ਤੁਧੁ ਭਾਵਨਿ = ਤੈਨੂੰ ਚੰਗੇ ਲੱਗਦੇ ਹਨ। ਰਤੇ = ਰੱਤੇ, ਰੰਗੇ ਹੋਏ, ਪ੍ਰੇਮ ਵਿਚ ਮਸਤ। ਰਸਾਲੇ = {ਰਸ-ਆਲਯ} ਰਸ ਦੇ ਘਰ, ਰਸੀਏ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-30", gurmukhi = "ਹੋਰਿ ਕੇਤੇ ਤੁਧਨੋ ਗਾਵਨਿ, ਸੇ. ਮੈ ਚਿਤਿ ਨ ਆਵਨਿ; ਨਾਨਕੁ. ਕਿਆ ਬੀਚਾਰੇ ॥", transliteration = "hor kete tudhno gaavan, se. mai chit na aavan; naanak. kiaa beechaare ||", translation = "So many others sing of You, they do not come to mind. O Nanak, how can I think of them all?", hindi = "होरि केते तुधनो गावनि, से. मै चिति न आवनि; नानकु. किआ बीचारे ॥", punjabi = "ਅਨੇਕਾਂ ਹੋਰ ਜੀਵ ਤੇਰੀ ਵਡਿਆਈ ਕਰ ਰਹੇ ਹਨ, ਜੋ ਮੈਥੋਂ ਗਿਣੇ ਨਹੀਂ ਜਾ ਸਕਦੇ। (ਭਲਾ, ਇਸ ਗਿਣਤੀ ਬਾਰੇ) ਨਾਨਕ ਕੀਹ ਵਿਚਾਰ ਕਰ ਸਕਦਾ ਹੈ? (ਨਾਨਕ ਇਹ ਵਿਚਾਰ ਕਰਨ-ਜੋਗਾ ਨਹੀਂ ਹੈ)।", wordMeaning = "ਹੋਰਿ ਕੇਤੇ = ਅਨੇਕਾਂ ਹੋਰ ਜੀਵ {ਲਫ਼ਜ਼ 'ਹੋਰਿ' ਲਫ਼ਜ਼ 'ਹੋਰ' ਤੋਂ ਬਹੁ-ਵਚਨ ਹੈ}। ਮੈ ਚਿਤਿ = ਮੇਰੇ ਚਿੱਤ ਵਿਚ। ਮੈ ਚਿਤਿ ਨ ਆਵਨਿ = ਮੇਰੇ ਚਿੱਤ ਵਿਚ ਨਹੀਂ ਆਉਂਦੇ, ਮੈਥੋਂ ਗਿਣੇ ਨਹੀਂ ਜਾ ਸਕਦੇ, ਮੇਰੀ ਵਿਚਾਰ ਤੋਂ ਪਰੇ ਹਨ। ਕਿਆ ਬੀਚਾਰੇ = ਕੀਹ ਵਿਚਾਰ ਕਰ ਸਕਦਾ ਹੈ?", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-31", gurmukhi = "ਸੋਈ ਸੋਈ ਸਦਾ ਸਚੁ ਸਾਹਿਬੁ; ਸਾਚਾ ਸਾਚੀ ਨਾਈ ॥", transliteration = "soee soee sdaa sach saahib; saachaa saachee naaee ||", translation = "That True Lord is True, forever True, and True is His Name.", hindi = "सोई सोई सदा सचु साहिबु; साचा साची नाई ॥", punjabi = "ਜਿਸ (ਪ੍ਰਭੂ) ਨੇ ਇਹ ਸ੍ਰਿਸ਼ਟੀ ਪੈਦਾ ਕੀਤੀ ਹੈ, ਉਹ ਇਸ ਵੇਲੇ ਭੀ ਮੌਜੂਦ ਹੈ, ਤੇ ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ ਹੈ।", wordMeaning = "ਸਚੁ = ਥਿਰ ਰਹਿਣ ਵਾਲਾ। ਨਾਈ = ਵਡਿਆਈ {ਅਰਬੀ ਲਫ਼ਜ਼ स्ना। ਇਸ ਅਰਬੀ ਲਫ਼ਜ਼ ਦੇ ਪੰਜਾਬੀ ਵਿਚ ਦੋ ਪਾਠ ਹਨ: ਅਸਨਾਈ, ਨਾਈ। 'ਜੋ ਕਿਛੁ ਹੋਇਆ ਸਭੁ ਕਿਛੁ ਤੁਝ ਤੇ, ਤੇਰੀ ਸਭ ਅਸਨਾਈ'} ਇਸੇ ਤਰ੍ਹਾਂ ਸੰਸਕ੍ਰਿਤ ਦੇ ਲਫ਼ਜ਼ਾਂ ਤੋਂ: स्थान = ਅਸਥਾਨ, ਥਾਨ, स्नान = ਅਸਨਾਨ, ਨ੍ਹਾਨ, स्तंभ = ਅਸਥੰਭ, ਥੰਭ, स्नेह = ਅਸਨੇਹ, ਨੇਹ, स्थिर = ਅਸਥਿਰ, ਥਿਰ, स्थल = ਅਸਥਲ, ਤਲ, {ਵੇਖੋ 'ਗੁਰਬਾਣੀ ਵਿਆਕਰਣ'}। {ਨੋਟ: ਲਫ਼ਜ਼ 'ਸਾਚਾ' ਪੁਲਿੰਗ ਹੈ ਅਤੇ 'ਸਾਹਿਬ' ਦਾ ਵਿਸ਼ੇਸ਼ਣ ਹੈ। ਲਫ਼ਜ਼ 'ਸਾਚੀ' ਇਸਤ੍ਰੀ-ਲਿੰਗ ਹੈ ਤੇ ਲਫ਼ਜ਼ 'ਨਾਈ' ਦਾ ਵਿਸ਼ੇਸ਼ਣ ਹੈ। ਇਸ ਤੁਕ ਦੇ ਪਾਠ ਵਿਚ ਵਿਸ੍ਰਾਮਾਂ ਦਾ ਖ਼ਿਆਲ ਰੱਖਣਾ}।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-32", gurmukhi = "ਹੈ ਭੀ ਹੋਸੀ, ਜਾਇ ਨ ਜਾਸੀ; ਰਚਨਾ ਜਿਨਿ ਰਚਾਈ ॥", transliteration = "hai bhee hosee, jaai na jaasee; rachnaa jin rchaaee ||", translation = "He is, and shall always be. He shall not depart, even when this Universe which He has created departs.", hindi = "है भी होसी, जाइ न जासी; रचना जिनि रचाई ॥", punjabi = "ਉਹ ਮਾਲਕ-ਪ੍ਰਭੂ ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ ਹੈ। ਉਸ ਦੀ ਵਡਿਆਈ ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲੀ ਹੈ।", wordMeaning = "ਹੋਸੀ = ਹੋਵੇਗਾ, ਥਿਰ ਰਹੇਗਾ। ਜਾਇ ਨ = ਜੰਮਦਾ ਨਹੀਂ। ਨ ਜਾਸੀ = ਨਾਹ ਹੀ ਮਰੇਗਾ। ਜਿਨਿ = ਜਿਸ (ਪ੍ਰਭੂ) ਨੇ। ਰਚਾਈ = ਪੈਦਾ ਕੀਤੀ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L)
)

private fun generatedRehrasSahibLines1(): List<BaniLine> = listOf(
    BaniLine(id = "rehras-sahib-33", gurmukhi = "ਰੰਗੀ ਰੰਗੀ ਭਾਤੀ, ਕਰਿ ਕਰਿ ਜਿਨਸੀ; ਮਾਇਆ ਜਿਨਿ ਉਪਾਈ ॥", transliteration = "rangee rangee bhaatee, kar kar jinsee; maaiaa jin upaaee ||", translation = "He created the world, with its various colors, species of beings, and the variety of Maya.", hindi = "रंगी रंगी भाती, करि करि जिनसी; माइआ जिनि उपाई ॥", punjabi = "ਜਿਸ ਪ੍ਰਭੂ ਨੇ ਕਈ ਰੰਗਾਂ ਕਿਸਮਾਂ ਤੇ ਜਿਨਸਾਂ ਦੀ ਮਾਇਆ ਰਚ ਦਿੱਤੀ ਹੈ।", wordMeaning = "ਰੰਗੀ ਰੰਗੀ = ਰੰਗਾਂ ਰੰਗਾਂ ਦੀ, ਕਈ ਰੰਗਾਂ ਦੀ। ਭਾਤੀ = ਕਈ ਕਿਸਮਾਂ ਦੀ। ਜਿਨਸੀ = ਕਈ ਜਿਨਸਾਂ ਦੀ। ਜਿਨਿ = ਜਿਸ (ਪ੍ਰਭੂ) ਨੇ। ਉਪਾਈ = ਪੈਦਾ ਕੀਤੀ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-34", gurmukhi = "ਕਰਿ ਕਰਿ ਦੇਖੈ. ਕੀਤਾ ਆਪਣਾ; ਜਿਉ ਤਿਸ ਦੀ ਵਡਿਆਈ ॥", transliteration = "kar kar dekhai. keetaa aapnaa; jiu tis dee vdiaaee ||", translation = "Having created the creation, He watches over it Himself, by His Greatness.", hindi = "करि करि देखै. कीता आपणा; जिउ तिस दी वडिआई ॥", punjabi = "ਉਹ, ਜਿਵੇਂ ਉਸ ਦੀ ਰਜ਼ਾ ਹੈ, ਜਗਤ ਨੂੰ ਪੈਦਾ ਕਰ ਕੇ ਆਪਣੇ ਪੈਦਾ ਕੀਤੇ ਹੋਏ ਦੀ ਸੰਭਾਲ ਕਰ ਰਿਹਾ ਹੈ।", wordMeaning = "ਕਰਿ ਕਰਿ = ਪੈਦਾ ਕਰ ਕੇ। ਦੇਖੈ = ਸੰਭਾਲ ਕਰਦਾ ਹੈ। ਕੀਤਾ ਆਪਣਾ = ਆਪਣਾ ਰਚਿਆ ਜਗਤ। ਜਿਉ = ਜਿਵੇਂ। ਵਡਿਆਈ = ਰਜ਼ਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-35", gurmukhi = "ਜੋ ਤਿਸੁ ਭਾਵੈ ਸੋਈ ਕਰਸੀ; ਫਿਰਿ. ਹੁਕਮੁ ਨ ਕਰਣਾ ਜਾਈ ॥", transliteration = "jo tis bhaavai soee karsee; phir. hukam na karnaa jaaee ||", translation = "He does whatever He pleases. No one can issue any order to Him.", hindi = "जो तिसु भावै सोई करसी; फिरि. हुकमु न करणा जाई ॥", punjabi = "ਜੋ ਕੁਝ ਉਸ (ਪ੍ਰਭੂ) ਨੂੰ ਚੰਗਾ ਲੱਗਦਾ ਹੈ ਉਹੀ ਉਹ ਕਰਦਾ ਹੈ। ਕੋਈ ਜੀਵ ਉਸ ਦੇ ਅੱਗੇ ਹੈਂਕੜ ਨਹੀਂ ਵਿਖਾ ਸਕਦਾ (ਕੋਈ ਜੀਵ ਉਸ ਨੂੰ ਇਹ ਨਹੀਂ ਆਖ ਸਕਦਾ 'ਇਉਂ ਨਹੀਂ, ਇਉਂ ਕਰ')।", wordMeaning = "ਤਿਸੁ ਭਾਵੈ = ਉਸ ਨੂੰ ਚੰਗਾ ਲੱਗਦਾ ਹੈ। ਕਰਸੀ = ਕਰੇਗਾ। ਨ ਕਰਣਾ ਜਾਈ = ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਦਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-36", gurmukhi = "ਸੋ ਪਾਤਿਸਾਹੁ ਸਾਹਾ ਪਤਿਸਾਹਿਬੁ; ਨਾਨਕ. ਰਹਣੁ ਰਜਾਈ ॥੧॥", transliteration = "so paatisaah saahaa ptisaahib; naanak. rahan rjaaee ||1||", translation = "He is the King, the King of kings, the Supreme Lord and Master of kings. Nanak remains subject to His Will. ||1||", hindi = "सो पातिसाहु साहा पतिसाहिबु; नानक. रहणु रजाई ॥१॥", punjabi = "ਉਹ ਪ੍ਰਭੂ (ਸਾਰੇ ਜਗਤ ਦਾ) ਪਾਤਿਸ਼ਾਹ ਹੈ, ਪਾਤਿਸ਼ਾਹਾਂ ਦਾ ਭੀ ਪਾਤਿਸ਼ਾਹ ਹੈ। ਹੇ ਨਾਨਕ! (ਜੀਵਾਂ ਨੂੰ) ਉਸ ਦੀ ਰਜ਼ਾ ਵਿਚ ਰਹਿਣਾ ਹੀ ਫਬਦਾ ਹੈ ॥੧॥{9}", wordMeaning = "ਸਾਹਾ ਪਤਿ ਸਾਹਿਬੁ = ਸ਼ਾਹਾਂ ਦਾ ਪਾਤਿਸ਼ਾਹ ਮਾਲਕ। ਰਹਣੁ = ਰਹਿਣਾ (ਫਬਦਾ ਹੈ)। ਰਜਾਈ = ਰਜ਼ਾ ਵਿਚ ॥੧॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-37", gurmukhi = "ਆਸਾ ਮਹਲਾ ੧ ॥", transliteration = "aasaa mahlaa 1 ||", translation = "Aasaa, First Mehl:", hindi = "आसा महला १ ॥", punjabi = "ਰਾਗ ਆਸਾ, ਪਹਿਲੀ ਪਾਤਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
