    BaniLine(id = "rehras-sahib-39", gurmukhi = "ਕੇਵਡੁ ਵਡਾ; ਡੀਠਾ ਹੋਇ ॥", transliteration = "kevad vdaa; deethaa hoi ||", translation = "But just how Great His Greatness is-this is known only to those who have seen Him.", hindi = "केवडु वडा; डीठा होइ ॥", punjabi = "ਪਰ ਤੂੰ ਕੇਡਾ ਵੱਡਾ ਹੈਂ (ਕਿਤਨਾ ਬੇਅੰਤ ਹੈਂ?) ਇਹ ਗੱਲ ਤੇਰਾ ਦਰਸਨ ਕੀਤਿਆਂ ਹੀ ਦੱਸੀ ਜਾ ਸਕਦੀ ਹੈ (ਤੇਰਾ ਦਰਸਨ ਕੀਤਿਆਂ ਹੀ ਦੱਸਿਆ ਜਾ ਸਕਦਾ ਹੈ ਕਿ ਤੂੰ ਬਹੁਤ ਬੇਅੰਤ ਹੈਂ)।", wordMeaning = "ਕੇਵਡੁ = ਕੇਡਾ। ਡੀਠਾ = ਵੇਖਿਆਂ ਹੀ। ਹੋਇ = (ਬਿਆਨ) ਹੋ ਸਕਦਾ ਹੈ, ਦੱਸਿਆ ਜਾ ਸਕਦਾ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-40", gurmukhi = "ਕੀਮਤਿ ਪਾਇ ਨ ਕਹਿਆ ਜਾਇ ॥", transliteration = "keemat paai na khiaa jaai ||", translation = "His Value cannot be estimated; He cannot be described.", hindi = "कीमति पाइ न कहिआ जाइ ॥", punjabi = "ਤੇਰੇ ਬਰਾਬਰ ਦਾ ਹੋਰ ਕੋਈ ਦੱਸਿਆ ਨਹੀਂ ਜਾ ਸਕਦਾ, ਤੇਰੇ ਸਰੂਪ ਦਾ ਬਿਆਨ ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਦਾ।", wordMeaning = "ਕੀਮਤਿ = ਮੁੱਲ, ਬਰਾਬਰ ਦੀ ਸ਼ੈ। ਕੀਮਤਿ ਪਾਇ ਨ = ਮੁੱਲ ਨਹੀਂ ਪਾਇਆ ਜਾ ਸਕਦਾ, ਉਸ ਦੇ ਬਰਾਬਰ ਦੀ ਕੋਈ ਹਸਤੀ ਨਹੀਂ ਦੱਸੀ ਜਾ ਸਕਦੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-41", gurmukhi = "ਕਹਣੈ ਵਾਲੇ ਤੇਰੇ; ਰਹੇ ਸਮਾਇ ॥੧॥", transliteration = "kahnai vaale tere; rhe smaai ||1||", translation = "Those who describe You, Lord, remain immersed and absorbed in You. ||1||", hindi = "कहणै वाले तेरे; रहे समाइ ॥१॥", punjabi = "ਤੇਰੀ ਵਡਿਆਈ ਆਖਣ ਵਾਲੇ (ਆਪਾ ਭੁੱਲ ਕੇ) ਤੇਰੇ ਵਿਚ (ਹੀ) ਲੀਨ ਹੋ ਜਾਂਦੇ ਹਨ ॥੧॥", wordMeaning = "ਰਹੇ ਸਮਾਇ = ਲੀਨ ਹੋ ਜਾਂਦੇ ਹਨ॥੧॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-42", gurmukhi = "ਵਡੇ ਮੇਰੇ ਸਾਹਿਬਾ; ਗਹਿਰ ਗੰਭੀਰਾ ਗੁਣੀ ਗਹੀਰਾ ॥", transliteration = "vade mere saahibaa; ghir gambheeraa gunee gheeraa ||", translation = "O my Great Lord and Master of Unfathomable Depth, You are the Ocean of Excellence.", hindi = "वडे मेरे साहिबा; गहिर गंभीरा गुणी गहीरा ॥", punjabi = "ਹੇ ਮੇਰੇ ਵੱਡੇ ਮਾਲਕ! ਤੂੰ (ਮਾਨੋ, ਇਕ) ਡੂੰਘਾ (ਸਮੁੰਦਰ) ਹੈਂ। ਤੂੰ ਬੜੇ ਜਿਗਰੇ ਵਾਲਾ ਹੈਂ, ਤੂੰ ਬੇਅੰਤ ਗੁਣਾਂ ਵਾਲਾ ਹੈਂ।", wordMeaning = "ਗਹਿਰ = ਹੇ ਡੂੰਘੇ! ਗੰਭੀਰਾ = ਹੇ ਵੱਡੇ ਜਿਗਰੇ ਵਾਲੇ! ਗੁਣੀ ਗਹੀਰਾ = ਹੇ ਗੁਣਾਂ ਕਰਕੇ ਡੂੰਘੇ! ਹੇ ਬੇਅੰਤ ਗੁਣਾਂ ਦੇ ਮਾਲਕ!", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-43", gurmukhi = "ਕੋਇ ਨ ਜਾਣੈ; ਤੇਰਾ ਕੇਤਾ, ਕੇਵਡੁ ਚੀਰਾ ॥੧॥ ਰਹਾਉ ॥", transliteration = "koi na jaanai; teraa ketaa, kevad cheeraa ||1|| rhaau ||", translation = "No one knows the extent or the vastness of Your Expanse. ||1||Pause||", hindi = "कोइ न जाणै; तेरा केता, केवडु चीरा ॥१॥ रहाउ ॥", punjabi = "ਕੋਈ ਭੀ ਜੀਵ ਨਹੀਂ ਜਾਣਦਾ ਕਿ ਤੇਰਾ ਕਿਤਨਾ ਵੱਡਾ ਵਿਸਥਾਰ ਹੈ ॥੧॥ ਰਹਾਉ ॥", wordMeaning = "ਚੀਰਾ = ਪਾਟ, ਚੌੜਾਈ, ਵਿਸਥਾਰ॥੧॥ਰਹਾਉ॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-44", gurmukhi = "ਸਭਿ ਸੁਰਤੀ ਮਿਲਿ; ਸੁਰਤਿ ਕਮਾਈ ॥", transliteration = "sabh surtee mil; surat kmaaee ||", translation = "All the intuitives met and practiced intuitive meditation.", hindi = "सभि सुरती मिलि; सुरति कमाई ॥", punjabi = "(ਤੂੰ ਕੇਡਾ ਵੱਡਾ ਹੈਂ-ਇਹ ਗੱਲ ਲੱਭਣ ਵਾਸਤੇ) ਸਮਾਧੀਆਂ ਲਾਉਣ ਵਾਲੇ ਕਈ ਵੱਡੇ ਵੱਡੇ ਪ੍ਰਸਿੱਧ ਜੋਗੀਆਂ ਨੇ ਧਿਆਨ ਜੋੜਨ ਦੇ ਜਤਨ ਕੀਤੇ , ਮੁੜ ਮੁੜ ਜਤਨ ਕੀਤੇ।", wordMeaning = "ਸਭਿ ਮਿਲਿ = ਸਾਰਿਆਂ ਨੇ ਮਿਲ ਕੇ, ਸਾਰਿਆਂ ਨੇ ਇਕ ਦੂਜੇ ਦੀ ਸਹੈਤਾ ਲੈ ਕੇ। ਸੁਰਤੀ = ਸੁਰਤਿ। ਸੁਰਤੀ ਸੁਰਤ ਕਮਾਈ = ਸੁਰਤ ਕਮਾਈ, ਸੁਰਤ ਕਮਾਈ, ਮੁੜ ਮੁੜ ਸਮਾਧੀ ਲਾਈ।", startsAtMs = 0L, endsAtMs = 0L),
