    BaniLine(id = "rehras-sahib-46", gurmukhi = "ਗਿਆਨੀ ਧਿਆਨੀ; ਗੁਰ ਗੁਰਹਾਈ ॥", transliteration = "giaanee dhiaanee; gur gurhaaee ||", translation = "The spiritual teachers, the teachers of meditation, and the teachers of teachers", hindi = "गिआनी धिआनी; गुर गुरहाई ॥", punjabi = "()", wordMeaning = "ਗਿਆਨੀ = ਵਿਚਾਰਵਾਨ, ਉੱਚੀ ਸਮਝ ਵਾਲੇ। ਧਿਆਨੀ = ਸੁਰਤ ਜੋੜਨ ਵਾਲੇ। ਗੁਰ = ਵੱਡੇ। ਗੁਰ ਹਾਈ = ਗੁਰ ਭਾਈ, ਵਡਿਆਂ ਦੇ ਭਰਾ, ਅਜਿਹੇ ਹੋਰ ਕੋਈ ਵੱਡੇ। ਗੁਰ ਗੁਰਹਾਈ = ਕਈ ਵੱਡੇ ਵੱਡੇ ਪ੍ਰਸਿੱਧ {ਇਹ ਲਫ਼ਜ਼ 'ਗੁਰ ਗੁਰਹਾਈ' ਲਫ਼ਜ਼ 'ਗਿਆਨੀ ਧਿਆਨੀ' ਦਾ ਵਿਸ਼ੇਸ਼ਣ ਹਨ}।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-47", gurmukhi = "ਕਹਣੁ ਨ ਜਾਈ; ਤੇਰੀ ਤਿਲੁ ਵਡਿਆਈ ॥੨॥", transliteration = "kahan na jaaee; teree til vdiaaee ||2||", translation = "-they cannot describe even an iota of Your Greatness. ||2||", hindi = "कहणु न जाई; तेरी तिलु वडिआई ॥२॥", punjabi = "ਪਰ ਤੇਰੀ ਵਡਿਆਈ ਦਾ ਇਕ ਤਿਲ ਜਿਤਨਾ ਭੀ ਹਿੱਸਾ ਨਹੀਂ ਦੱਸ ਸਕੇ ॥੨॥", wordMeaning = "ਤਿਲੁ = ਰਤਾ ਜਿਤਨੀ ਭੀ॥੨॥", startsAtMs = 0L, endsAtMs = 0L),
