    BaniLine(id = "rehras-sahib-66", gurmukhi = "ਵਡਾ ਨ ਹੋਵੈ; ਘਾਟਿ ਨ ਜਾਇ ॥੨॥", transliteration = "vadaa na hovai; ghaat na jaai ||2||", translation = "He would not become any greater or any lesser. ||2||", hindi = "वडा न होवै; घाटि न जाइ ॥२॥", punjabi = "ਤਾਂ ਉਹ ਪ੍ਰਭੂ (ਆਪਣੇ ਅਸਲੇ ਨਾਲੋਂ) ਵੱਡਾ ਨਹੀਂ ਹੋ ਜਾਂਦਾ (ਤੇ, ਜੇ ਕੋਈ ਭੀ ਉਸ ਦੀ ਵਡਿਆਈ ਨਾਹ ਕਰੇ), ਤਾਂ ਉਹ (ਅੱਗੇ ਨਾਲੋਂ) ਘੱਟ ਨਹੀਂ ਜਾਂਦਾ। (ਉਸ ਨੂੰ ਆਪਣੀ ਸੋਭਾ ਦਾ ਲਾਲਚ ਨਹੀਂ) ॥੨॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-67", gurmukhi = "ਨਾ ਓਹੁ ਮਰੈ; ਨ ਹੋਵੈ ਸੋਗੁ ॥", transliteration = "naa oh mrai; na hovai sog ||", translation = "That Lord does not die; there is no reason to mourn.", hindi = "ना ओहु मरै; न होवै सोगु ॥", punjabi = "ਉਹ ਪ੍ਰਭੂ ਕਦੇ ਮਰਦਾ ਨਹੀਂ, ਨਾਹ ਹੀ (ਉਸ ਦੀ ਖ਼ਾਤਰ) ਸੋਗ ਹੁੰਦਾ ਹੈ।", wordMeaning = "ਸੋਗੁ = ਅਫ਼ਸੋਸ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-68", gurmukhi = "ਦੇਦਾ ਰਹੈ; ਨ ਚੂਕੈ ਭੋਗੁ ॥", transliteration = "dedaa rhai; na chookai bhog ||", translation = "He continues to give, and His Provisions never run short.", hindi = "देदा रहै; न चूकै भोगु ॥", punjabi = "ਉਹ ਸਦਾ (ਜੀਵਾਂ ਨੂੰ ਰਿਜ਼ਕ ਦਿੰਦਾ ਹੈ, ਉਸ ਦੀਆਂ ਦਿੱਤੀਆਂ ਦਾਤਾਂ ਦਾ ਵਰਤਣਾ ਕਦੇ ਮੁੱਕਦਾ ਨਹੀਂ (ਉਸ ਦੀਆਂ ਦਾਤਾਂ ਵਰਤਣ ਨਾਲ ਕਦੇ ਮੁਕਦੀਆਂ ਨਹੀਂ)।", wordMeaning = "ਦੇਦਾ = ਦੇਂਦਾ। ਨ ਚੂਕੈ = ਨਹੀਂ ਮੁੱਕਦਾ। ਭੋਗੁ = ਵਰਤਣਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-69", gurmukhi = "ਗੁਣੁ ਏਹੋ; ਹੋਰੁ ਨਾਹੀ ਕੋਇ ॥", transliteration = "gun eho; hor naahee koi ||", translation = "This Virtue is His alone; there is no other like Him.", hindi = "गुणु एहो; होरु नाही कोइ ॥", punjabi = "ਉਸ ਦੀ ਵੱਡੀ ਖ਼ੂਬੀ ਇਹ ਹੈ ਕਿ ਕੋਈ ਹੋਰ ਉਸ ਵਰਗਾ ਨਹੀਂ ਹੈ।", wordMeaning = "ਗੁਣੁ ਏਹੋ = ਇਹੀ ਖ਼ੂਬੀ। ਕੋ = ਕੋਈ (ਹੋਰ)।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-70", gurmukhi = "ਨਾ ਕੋ ਹੋਆ; ਨਾ ਕੋ ਹੋਇ ॥੩॥", transliteration = "naa ko hoaa; naa ko hoi ||3||", translation = "There never has been, and there never will be. ||3||", hindi = "ना को होआ; ना को होइ ॥३॥", punjabi = "(ਉਸ ਵਰਗਾ ਅਜੇ ਤਕ) ਨਾਹ ਕੋਈ ਹੋਇਆ ਹੈ, ਨਾਹ ਕਦੇ ਹੋਵੇਗਾ ॥੩॥", wordMeaning = "ਹੋਆ = ਹੋਇਆ ਹੈ। ਨਾ ਹੋਇ = ਨਾਹ ਹੀ ਹੋਵੇਗਾ॥੩॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-71", gurmukhi = "ਜੇਵਡੁ ਆਪਿ; ਤੇਵਡ ਤੇਰੀ ਦਾਤਿ ॥", transliteration = "jevad aap; tevad teree daat ||", translation = "As Great as You Yourself are, O Lord, so Great are Your Gifts.", hindi = "जेवडु आपि; तेवड तेरी दाति ॥", punjabi = "(ਹੇ ਪ੍ਰਭੂ!) ਜਿਤਨਾ ਬੇਅੰਤ ਤੂੰ ਆਪ ਹੈਂ ਉਤਨੀ ਬੇਅੰਤ ਤੇਰੀ ਬਖ਼ਸ਼ਸ਼।", wordMeaning = "ਜੇਵਡੁ = ਜਿਤਨਾ ਵੱਡਾ। ਤੇਵਡ = ਉਤਨੀ ਵੱਡੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-72", gurmukhi = "ਜਿਨਿ ਦਿਨੁ ਕਰਿ ਕੈ; ਕੀਤੀ ਰਾਤਿ ॥", transliteration = "jin din kar kai; keetee raat ||", translation = "The One who created the day also created the night.", hindi = "जिनि दिनु करि कै; कीती राति ॥", punjabi = "(ਤੂੰ ਐਸਾ ਹੈਂ) ਜਿਸ ਨੇ ਦਿਨ ਬਣਾਇਆ ਹੈ ਤੇ ਰਾਤ ਬਣਾਈ ਹੈ।", wordMeaning = "ਜਿਨਿ = ਜਿਸ (ਤੈਂ) ਨੇ। ਕਰਿ ਕੈ = ਪੈਦਾ ਕਰ ਕੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-73", gurmukhi = "ਖਸਮੁ ਵਿਸਾਰਹਿ; ਤੇ ਕਮਜਾਤਿ ॥", transliteration = "khasam visaarah; te kamjaat ||", translation = "Those who forget their Lord and Master are vile and despicable.", hindi = "खसमु विसारहि; ते कमजाति ॥", punjabi = "ਜੋ (ਅਜਿਹੇ) ਖਸਮ-ਪ੍ਰਭੂ ਨੂੰ ਭੁਲਾ ਦੇਂਦੇ ਹਨ, ਉਹ ਬੰਦੇ ਨੀਵੇਂ ਜੀਵਨ ਵਾਲੇ ਬਣ ਜਾਂਦੇ ਹਨ।", wordMeaning = "ਵਿਸਾਰਹਿ = ਭੁਲਾ ਦੇਂਦੇ ਹਨ। ਤੇ = ਉਹ (ਬੰਦੇ) {ਬਹੁ-ਵਚਨ}। ਕਮਜਾਤਿ = ਭੈੜੀ ਜਾਤ ਵਾਲੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-74", gurmukhi = "ਨਾਨਕ. ਨਾਵੈ ਬਾਝੁ; ਸਨਾਤਿ ॥੪॥੩॥", transliteration = "naanak. naavai baajh; snaat ||4||3||", translation = "O Nanak, without the Name, they are wretched outcasts. ||4||3||", hindi = "नानक. नावै बाझु; सनाति ॥४॥३॥", punjabi = "ਹੇ ਨਾਨਕ! ਨਾਮ ਤੋਂ ਖੁੰਝੇ ਹੋਏ ਜੀਵ (ਹੀ) ਨੀਚ ਹਨ ॥੪॥੩॥{9}", wordMeaning = "ਨਾਵੈ ਬਾਝੁ = ਹਰਿ-ਨਾਮ ਤੋਂ ਬਿਨਾ। ਸਨਾਤਿ = ਨੀਚ॥੪॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-75", gurmukhi = "ਰਾਗੁ ਗੂਜਰੀ ਮਹਲਾ ੪ ॥", transliteration = "raag goojree mahlaa 4 ||", translation = "Raag Goojaree, Fourth Mehl:", hindi = "रागु गूजरी महला ४ ॥", punjabi = "ਰਾਗ ਗੂਜਰੀ, ਚੌਥੀ ਪਾਤਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-76", gurmukhi = "ਹਰਿ ਕੇ ਜਨ, ਸਤਿਗੁਰ ਸਤਪੁਰਖਾ; ਬਿਨਉ ਕਰਉ ਗੁਰ ਪਾਸਿ ॥", transliteration = "har ke jan, stigur satpurkhaa; binau karau gur paas ||", translation = "O humble servant of the Lord, O True Guru, O True Primal Being: I offer my humble prayer to You, O Guru.", hindi = "हरि के जन, सतिगुर सतपुरखा; बिनउ करउ गुर पासि ॥", punjabi = "ਹੇ ਮਹਾਪੁਰਖ ਗੁਰੂ! ਹੇ ਪ੍ਰਭੂ ਦੇ ਭਗਤ ਸਤਿਗੁਰੂ! ਮੈਂ, ਹੇ ਗੁਰੂ! ਤੇਰੇ ਅੱਗੇ ਬੇਨਤੀ ਕਰਦਾ ਹਾਂ,", wordMeaning = "ਹਰਿ ਕੇ ਜਨ = ਹੇ ਹਰੀ ਦੇ ਸੇਵਕ! ਸਤਿਗੁਰੂ = ਹੇ ਸਤਿਗੁਰ! ਸਤ ਪੁਰਖਾ = ਹੇ ਮਹਾ ਪੁਰਖ ਗੁਰੂ! ਬਿਨਉ = {विनय} ਬੇਨਤੀ। ਕਰਉ = ਕਰਉਂ, ਮੈਂ ਕਰਦਾ ਹਾਂ। ਗੁਰ ਪਾਸਿ = ਹੇ ਗੁਰੂ! ਤੇਰੇ ਪਾਸ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-77", gurmukhi = "ਹਮ ਕੀਰੇ ਕਿਰਮ. ਸਤਿਗੁਰ ਸਰਣਾਈ; ਕਰਿ ਦਇਆ. ਨਾਮੁ ਪਰਗਾਸਿ ॥੧॥", transliteration = "ham keere kiram. stigur sarnaaee; kar daiaa. naam pargaas ||1||", translation = "I am a mere insect, a worm. O True Guru, I seek Your Sanctuary. Please be merciful, and bless me with the Light of the Naam, the Name of the Lord. ||1||", hindi = "हम कीरे किरम. सतिगुर सरणाई; करि दइआ. नामु परगासि ॥१॥", punjabi = "ਹੇ ਸਤਿਗੁਰੂ! ਮੈਂ ਨਿਮਾਣਾ ਤੇਰੀ ਸਰਨ ਆਇਆ ਹਾਂ। ਕਿਰਪਾ ਕਰ ਕੇ (ਮੇਰੇ ਅੰਦਰ) ਪ੍ਰਭੂ ਦਾ ਨਾਮ-ਚਾਨਣ ਪੈਦਾ ਕਰ ॥੧॥", wordMeaning = "ਸਤਿਗੁਰ ਸਰਣਾਈ = ਹੇ ਗੁਰੂ! ਤੇਰੀ ਸਰਨ। ਕੀਰੇ ਕਿਰਮ = ਨਿਮਾਣੇ ਦੀਨ ਜੀਵ। ਪਰਗਾਸਿ = ਪਰਗਟ ਕਰ, ਚਾਨਣ ਕਰ॥੧॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-78", gurmukhi = "ਮੇਰੇ ਮੀਤ ਗੁਰਦੇਵ; ਮੋ ਕਉ. ਰਾਮ ਨਾਮੁ ਪਰਗਾਸਿ ॥", transliteration = "mere meet gurdev; mo kau. raam naam pargaas ||", translation = "O my Best Friend, O Divine Guru, please enlighten me with the Name of the Lord.", hindi = "मेरे मीत गुरदेव; मो कउ. राम नामु परगासि ॥", punjabi = "ਹੇ ਮੇਰੇ ਮਿੱਤਰ ਗੁਰੂ! ਮੈਨੂੰ ਪ੍ਰਭੂ ਦਾ ਨਾਮ-ਚਾਨਣ ਬਖ਼ਸ਼।", wordMeaning = "ਮੋ ਕਉ = ਮੈਨੂੰ, ਮੇਰੇ ਅੰਦਰ। ਮੀਤ = ਹੇ ਮਿੱਤਰ!", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-79", gurmukhi = "ਗੁਰਮਤਿ ਨਾਮੁ, ਮੇਰਾ ਪ੍ਰਾਨ ਸਖਾਈ; ਹਰਿ ਕੀਰਤਿ ਹਮਰੀ ਰਹਰਾਸਿ ॥੧॥ ਰਹਾਉ ॥", transliteration = "guramat naam, meraa praan skhaaee; har keerat hamree rahraas ||1|| rhaau ||", translation = "Through the Guru's Teachings, the Naam is my breath of life. The Kirtan of the Lord's Praise is my life's occupation. ||1||Pause||", hindi = "गुरमति नामु, मेरा प्रान सखाई; हरि कीरति हमरी रहरासि ॥१॥ रहाउ ॥", punjabi = "ਗੁਰੂ ਦੀ ਦੱਸੀ ਮਤਿ ਦੀ ਰਾਹੀਂ ਮਿਲਿਆ ਹੋਇਆ ਹਰਿ-ਨਾਮ ਮੇਰੀ ਜਿੰਦ ਦਾ ਸਾਥੀ (ਬਣਿਆ ਰਹੇ), ਪ੍ਰਭੂ ਦੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਮੇਰੀ ਜ਼ਿੰਦਗੀ ਦੇ ਸਫ਼ਰ ਲਈ ਰਾਸਿ-ਪੂੰਜੀ ਬਣੀ ਰਹੇ ॥੧॥ ਰਹਾਉ ॥", wordMeaning = "ਗੁਰਮਤਿ = ਗੁਰੂ ਦੀ ਮਤਿ ਦੀ ਰਾਹੀਂ (ਮਿਲਿਆ ਹੋਇਆ)। ਪ੍ਰਾਨ ਸਖਾਈ = ਜਿੰਦ ਦਾ ਸਾਥੀ। ਕੀਰਤਿ = ਸੋਭਾ, ਸਿਫ਼ਤ-ਸਾਲਾਹ। ਰਹਰਾਸਿ = ਰਾਹ ਦੀ ਰਾਸਿ, ਜ਼ਿੰਦਗੀ ਦੇ ਸਫ਼ਰ ਵਾਸਤੇ ਖ਼ਰਚੀ॥੧॥ਰਹਾਉ॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-80", gurmukhi = "ਹਰਿ ਜਨ ਕੇ ਵਡ ਭਾਗ ਵਡੇਰੇ; ਜਿਨ ਹਰਿ ਹਰਿ ਸਰਧਾ, ਹਰਿ ਪਿਆਸ ॥", transliteration = "har jan ke vad bhaag vdere; jin har har sardhaa, har piaas ||", translation = "The servants of the Lord have the greatest good fortune; they have faith in the Lord, and a longing for the Lord.", hindi = "हरि जन के वड भाग वडेरे; जिन हरि हरि सरधा, हरि पिआस ॥", punjabi = "ਪ੍ਰਭੂ ਦੇ ਉਹਨਾਂ ਸੇਵਕਾਂ ਦੇ ਬੜੇ ਉੱਚੇ ਭਾਗ ਹਨ ਜਿਨ੍ਹਾਂ ਦੇ ਅੰਦਰ ਪ੍ਰਭੂ ਦੇ ਨਾਮ ਵਾਸਤੇ ਸਰਧਾ ਹੈ, ਖਿੱਚ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-81", gurmukhi = "ਹਰਿ ਹਰਿ ਨਾਮੁ ਮਿਲੈ, ਤ੍ਰਿਪਤਾਸਹਿ; ਮਿਲਿ ਸੰਗਤਿ. ਗੁਣ ਪਰਗਾਸਿ ॥੨॥", transliteration = "har har naam milai, triptaasah; mil sangat. gun pargaas ||2||", translation = "Obtaining the Name of the Lord, Har, Har, they are satisfied; joining the Sangat, the Blessed Congregation, their virtues shine forth. ||2||", hindi = "हरि हरि नामु मिलै, त्रिपतासहि; मिलि संगति. गुण परगासि ॥२॥", punjabi = "ਜਦੋਂ ਉਹਨਾਂ ਨੂੰ ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ ਪ੍ਰਾਪਤ ਹੁੰਦਾ ਹੈ ਉਹ (ਮਾਇਆ ਦੀ ਤ੍ਰਿਸ਼ਨਾ ਵਲੋਂ) ਰੱਜ ਜਾਂਦੇ ਹਨ, ਸਾਧ ਸੰਗਤਿ ਵਿਚ ਮਿਲ ਕੇ (ਉਹਨਾਂ ਦੇ ਅੰਦਰ ਭਲੇ) ਗੁਣ ਪੈਦਾ ਹੁੰਦੇ ਹਨ ॥੨॥", wordMeaning = "ਤ੍ਰਿਪਤਾਸਹਿ = ਰੱਜ ਜਾਂਦੇ ਹਨ। ਮਿਲਿ = ਮਿਲ ਕੇ॥੨॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-82", gurmukhi = "ਜਿਨ ਹਰਿ ਹਰਿ, ਹਰਿ ਰਸੁ ਨਾਮੁ. ਨ ਪਾਇਆ; ਤੇ ਭਾਗਹੀਣ ਜਮ ਪਾਸਿ ॥", transliteration = "jin har har, har ras naam. na paaiaa; te bhaagheen jam paas ||", translation = "Those who have not obtained the Sublime Essence of the Name of the Lord, Har, Har, Har, are most unfortunate; they are led away by the Messenger of Death.", hindi = "जिन हरि हरि, हरि रसु नामु. न पाइआ; ते भागहीण जम पासि ॥", punjabi = "ਪਰ ਜਿਨ੍ਹਾਂ ਮਨੁੱਖਾਂ ਨੂੰ ਪਰਮਾਤਮਾ ਦੇ ਨਾਮ ਦਾ ਸੁਆਦ ਨਹੀਂ ਆਇਆ, ਜਿਨ੍ਹਾਂ ਨੂੰ ਪ੍ਰਭੂ ਦਾ ਨਾਮ ਨਹੀਂ ਮਿਲਿਆ, ਉਹ ਬਦ-ਕਿਸਮਤ ਹਨ, ਉਹ ਜਮਾਂ ਦੇ ਵੱਸ (ਪਏ ਹੋਏ ਸਮਝੋ ਉਹਨਾਂ ਦੇ ਸਿਰ ਉਤੇ ਆਤਮਕ ਮੌਤ ਸਦਾ ਸਵਾਰ ਰਹਿੰਦੀ ਹੈ)।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-83", gurmukhi = "ਜੋ ਸਤਿਗੁਰ ਸਰਣਿ ਸੰਗਤਿ. ਨਹੀ ਆਏ; ਧ੍ਰਿਗੁ ਜੀਵੇ. ਧ੍ਰਿਗੁ ਜੀਵਾਸਿ ॥੩॥", transliteration = "jo stigur saran sangat. nhee aae; dhrig jeeve. dhrig jeevaas ||3||", translation = "Those who have not sought the Sanctuary of the True Guru and the Sangat, the Holy Congregation-cursed are their lives, and cursed are their hopes of life. ||3||", hindi = "जो सतिगुर सरणि संगति. नही आए; ध्रिगु जीवे. ध्रिगु जीवासि ॥३॥", punjabi = "ਜੋ ਮਨੁੱਖ ਗੁਰੂ ਦੀ ਸਰਨ ਨਹੀਂ ਆਉਂਦੇ, ਜੋ ਸਾਧ ਸੰਗਤਿ ਵਿਚ ਨਹੀਂ ਬੈਠਦੇ, ਲਾਹਨਤ ਹੈ ਉਹਨਾਂ ਦੇ ਜੀਊਣ ਨੂੰ, ਉਹਨਾਂ ਦਾ ਜੀਊਣਾ ਫਿਟਕਾਰ-ਜੋਗ ਹੈ ॥੩॥", wordMeaning = "ਧ੍ਰਿਗੁ ਜੀਵੇ = ਲਾਹਨਤ ਹੈ ਉਹਨਾਂ ਦੇ ਜੀਵੇ ਨੂੰ॥੩॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-84", gurmukhi = "ਜਿਨ ਹਰਿ ਜਨ, ਸਤਿਗੁਰ ਸੰਗਤਿ ਪਾਈ; ਤਿਨ ਧੁਰਿ ਮਸਤਕਿ ਲਿਖਿਆ ਲਿਖਾਸਿ ॥", transliteration = "jin har jan, stigur sangat paaee; tin dhur masatak likhiaa likhaas ||", translation = "Those humble servants of the Lord who have attained the Company of the True Guru, have such pre-ordained destiny inscribed on their foreheads.", hindi = "जिन हरि जन, सतिगुर संगति पाई; तिन धुरि मसतकि लिखिआ लिखासि ॥", punjabi = "ਜਿਨ੍ਹਾਂ ਪ੍ਰਭੂ ਦੇ ਸੇਵਕਾਂ ਨੂੰ ਗੁਰੂ ਦੀ ਸੰਗਤਿ ਵਿਚ ਬੈਠਣਾ ਨਸੀਬ ਹੋਇਆ ਹੈ, (ਸਮਝੋ) ਉਹਨਾਂ ਦੇ ਮੱਥੇ ਉਤੇ ਧੁਰੋਂ ਹੀ ਚੰਗਾ ਲੇਖ ਲਿਖਿਆ ਹੋਇਆ ਹੈ।", wordMeaning = "ਧੁਰਿ = ਧੁਰ ਤੋਂ, ਪਰਮਾਤਮਾ ਵਲੋਂ। ਮਸਤਕਿ = ਮੱਥੇ ਉੱਤੇ। ਲਿਖਾਸਿ = ਲੇਖ {ਲਫ਼ਜ਼ 'ਜੀਵਾਸਿ' ਅਤੇ 'ਲਿਖਾਸਿ' ਲਫ਼ਜ਼ 'ਜੀਵੇ' ਅਤੇ 'ਲੇਖ' ਤੋਂ ਬਦਲੇ ਹੋਏ ਹਨ ਤੁਕਾਂਤ ਪੂਰਾ ਕਰਨ ਲਈ}।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-85", gurmukhi = "ਧਨੁ ਧੰਨੁ ਸਤਸੰਗਤਿ, ਜਿਤੁ ਹਰਿ ਰਸੁ ਪਾਇਆ; ਮਿਲਿ ਜਨ ਨਾਨਕ. ਨਾਮੁ ਪਰਗਾਸਿ ॥੪॥੪॥", transliteration = "dhan dhann satasangat, jit har ras paaiaa; mil jan naanak. naam pargaas ||4||4||", translation = "Blessed, blessed is the Sat Sangat, the True Congregation, where the Lord's Essence is obtained. Meeting with His humble servant, O Nanak, the Light of the Naam shines forth. ||4||4||", hindi = "धनु धंनु सतसंगति, जितु हरि रसु पाइआ; मिलि जन नानक. नामु परगासि ॥४॥४॥", punjabi = "ਹੇ ਨਾਨਕ! ਧੰਨ ਹੈ ਸਤਸੰਗ! ਧੰਨ ਹੈ ਸਤਸੰਗ! ਜਿਸ ਵਿਚ (ਬੈਠਿਆਂ) ਪ੍ਰਭੂ ਦੇ ਨਾਮ ਦਾ ਆਨੰਦ ਮਿਲਦਾ ਹੈ, ਜਿਥੇ ਗੁਰਮੁਖਾਂ ਨੂੰ ਮਿਲਿਆਂ (ਹਿਰਦੇ ਵਿਚ ਪਰਮਾਤਮਾ ਦਾ) ਨਾਮ ਆ ਵੱਸਦਾ ਹੈ ॥੪॥੪॥", wordMeaning = "ਜਿਤੁ = ਜਿਸ ਵਿਚ, ਜਿਸ ਦੀ ਰਾਹੀਂ। ਮਿਲਿ ਜਨ = ਜਨਾਂ ਨੂੰ ਮਿਲ ਕੇ, ਪ੍ਰਭੂ ਦੇ ਸੇਵਕਾਂ ਨੂੰ ਮਿਲ ਕੇ॥੪॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-86", gurmukhi = "ਰਾਗੁ ਗੂਜਰੀ ਮਹਲਾ ੫ ॥", transliteration = "raag goojree mahlaa 5 ||", translation = "Raag Goojaree, Fifth Mehl:", hindi = "रागु गूजरी महला ५ ॥", punjabi = "ਰਾਗ ਗੁਜਰੀ, ਪੰਜਵੀਂ ਪਾਤਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-87", gurmukhi = "ਕਾਹੇ ਰੇ ਮਨ, ਚਿਤਵਹਿ ਉਦਮੁ; ਜਾ ਆਹਰਿ. ਹਰਿ ਜੀਉ ਪਰਿਆ ॥", transliteration = "kaahe re man, chitavah udam; jaa aahar. har jeeu priaa ||", translation = "Why, O mind, do you plot and plan, when the Dear Lord Himself provides for your care?", hindi = "काहे रे मन, चितवहि उदमु; जा आहरि. हरि जीउ परिआ ॥", punjabi = "ਹੇ ਮਨ! (ਤੇਰੀ ਖ਼ਾਤਰ) ਜਿਸ ਆਹਰ ਵਿਚ ਪਰਮਾਤਮਾ ਆਪ ਲੱਗਾ ਹੋਇਆ ਹੈ, ਉਸ ਵਾਸਤੇ ਤੂੰ ਕਿਉਂ (ਸਦਾ) ਸੋਚਾਂ-ਫ਼ਿਕਰ ਕਰਦਾ ਰਹਿੰਦਾ ਹੈਂ?", wordMeaning = "ਕਾਹੇ = ਕਿਉਂ? ਚਿਤਵਹਿ = ਤੂੰ ਸੋਚਦਾ ਹੈਂ। ਚਿਤਵਹਿ ਉਦਮੁ = ਤੂੰ ਉੱਦਮ ਚਿਤਵਦਾ ਹੈਂ, ਤੂੰ ਜ਼ਿਕਰ ਕਰਦਾ ਹੈਂ, {❀ ਨੋਟ:'ਉੱਦਮ ਚਿਤਵਨ' ਅਤੇ 'ਉੱਦਮ ਕਰਨ' ਵਿਚ ਫ਼ਰਕ ਚੇਤੇ ਰੱਖਣ-ਯੋਗ ਹੈ। ਰੋਜ਼ੀ ਕਮਾਣ ਲਈ ਉੱਦਮ ਕਰਨਾ ਹਰੇਕ ਮਨੁੱਖ ਦਾ ਫ਼ਰਜ਼ ਹੈ। ਗੁਰੂ ਸਾਹਿਬ ਨੇ ਚਿੰਤਾ-ਤੌਖ਼ਲਾ ਕਰੀ ਜਾਣ ਵਾਲੇ ਗ਼ਲਤ ਰਸਤੇ ਵਲੋਂ ਵਰਜਿਆ ਹੈ}। ਜਾ ਆਹਰਿ = ਜਿਸ ਆਹਰ ਵਿਚ। ਪਰਿਆ = ਪਿਆ ਹੋਇਆ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-88", gurmukhi = "ਸੈਲ ਪਥਰ ਮਹਿ. ਜੰਤ ਉਪਾਏ; ਤਾ ਕਾ ਰਿਜਕੁ, ਆਗੈ ਕਰਿ ਧਰਿਆ ॥੧॥", transliteration = "sail pathar mah. jant upaae; taa kaa rijak, aagai kar dhriaa ||1||", translation = "From rocks and stones He created living beings; He places their nourishment before them. ||1||", hindi = "सैल पथर महि. जंत उपाए; ता का रिजकु, आगै करि धरिआ ॥१॥", punjabi = "ਜੇਹੜੇ ਜੀਵ ਪ੍ਰਭੂ ਨੇ ਚਟਾਨਾਂ ਤੇ ਪੱਥਰਾਂ ਵਿਚ ਪੈਦਾ ਕੀਤੇ ਹਨ, ਉਹਨਾਂ ਦਾ ਭੀ ਰਿਜ਼ਕ ਉਸ ਨੇ (ਉਹਨਾਂ ਦੇ ਪੈਦਾ ਕਰਨ ਤੋਂ) ਪਹਿਲਾਂ ਹੀ ਬਣਾ ਰਖਿਆ ਹੈ ॥੧॥", wordMeaning = "ਸੈਲ = ਚਿਟਾਨ। ਤਾ ਕਾ = ਉਹਨਾਂ ਦਾ। ਆਗੈ = ਪਹਿਲਾਂ ਹੀ॥੧॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-89", gurmukhi = "ਮੇਰੇ ਮਾਧਉ ਜੀ; ਸਤਸੰਗਤਿ ਮਿਲੇ. ਸੁ ਤਰਿਆ ॥", transliteration = "mere maadhau jee; satasangat mile. su triaa ||", translation = "O my Dear Lord of souls, one who joins the Sat Sangat, the True Congregation, is saved.", hindi = "मेरे माधउ जी; सतसंगति मिले. सु तरिआ ॥", punjabi = "ਹੇ ਮੇਰੇ ਪ੍ਰਭੂ ਜੀ! ਜੇਹੜੇ ਮਨੁੱਖ ਸਾਧ ਸੰਗਤਿ ਵਿਚ ਮਿਲ ਬੈਠਦੇ ਹਨ, ਉਹ (ਵਿਅਰਥ ਤੌਖ਼ਲੇ-ਫ਼ਿਕਰਾਂ ਤੋਂ) ਬਚ ਜਾਂਦੇ ਹਨ।", wordMeaning = "ਮਾਧਉ ਜੀ = ਹੇ ਪ੍ਰਭੂ ਜੀ! ਹੇ ਮਾਇਆ ਦੇ ਪਤੀ ਜੀ! {ਮਾਧਉ = ਮਾ-ਧਵ। ਮਾ = ਮਾਇਆ। ਧਵ = ਪਤੀ}।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-90", gurmukhi = "ਗੁਰ ਪਰਸਾਦਿ ਪਰਮ ਪਦੁ ਪਾਇਆ; ਸੂਕੇ ਕਾਸਟ ਹਰਿਆ ॥੧॥ ਰਹਾਉ ॥", transliteration = "gur parsaad param pad paaiaa; sooke kaasat hriaa ||1|| rhaau ||", translation = "By Guru's Grace, the supreme status is obtained, and the dry wood blossoms forth again in lush greenery. ||1||Pause||", hindi = "गुर परसादि परम पदु पाइआ; सूके कासट हरिआ ॥१॥ रहाउ ॥", punjabi = "ਗੁਰੂ ਦੀ ਕਿਰਪਾ ਨਾਲ ਜਿਸ ਮਨੁੱਖ ਨੂੰ ਇਹ (ਅਡੋਲਤਾ ਵਾਲੀ) ਉੱਚੀ ਆਤਮਕ ਅਵਸਥਾ ਮਿਲ ਜਾਂਦੀ ਹੈ, ਉਹ (ਮਾਨੋ) ਸੁੱਕਾ ਕਾਠ ਹਰਾ ਹੋ ਜਾਂਦਾ ਹੈ ॥੧॥ ਰਹਾਉ ॥", wordMeaning = "ਪਰਸਾਦਿ = ਕਿਰਪਾ ਨਾਲਿ। ਪਰਮ ਪਦੁ = ਸਭ ਤੋਂ ਉੱਚਾ ਆਤਮਕ ਦਰਜਾ। ਕਾਸਟ = ਕਾਠ, ਲੱਕੜੀ॥੧॥ਰਹਾਉ॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-91", gurmukhi = "ਜਨਨਿ ਪਿਤਾ, ਲੋਕ ਸੁਤ ਬਨਿਤਾ; ਕੋਇ ਨ ਕਿਸ ਕੀ ਧਰਿਆ ॥", transliteration = "janan pitaa, lok sut bnitaa; koi na kis kee dhriaa ||", translation = "Mothers, fathers, friends, children and spouses-no one is the support of anyone else.", hindi = "जननि पिता, लोक सुत बनिता; कोइ न किस की धरिआ ॥", punjabi = "(ਹੇ ਮਨ!) ਮਾਂ, ਪਿਉ, ਪੁੱਤਰ, ਲੋਕ, ਵਹੁਟੀ-ਕੋਈ ਭੀ ਕਿਸੇ ਦਾ ਆਸਰਾ ਨਹੀਂ ਹੈ।", wordMeaning = "ਜਨਨਿ = ਮਾਂ। ਸੁਤ = ਪੁੱਤਰ। ਬਨਿਤਾ = ਵਹੁਟੀ। ਧਰਿਆ = ਆਸਰਾ। ਕਿਸ ਕੀ = ਕਿਸੇ ਦਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-92", gurmukhi = "ਸਿਰਿ ਸਿਰਿ ਰਿਜਕੁ ਸੰਬਾਹੇ ਠਾਕੁਰੁ; ਕਾਹੇ ਮਨ ਭਉ ਕਰਿਆ ॥੨॥", transliteration = "sir sir rijak sambaahe thaakur; kaahe man bhau kriaa ||2||", translation = "For each and every person, our Lord and Master provides sustenance. Why are you so afraid, O mind? ||2||", hindi = "सिरि सिरि रिजकु संबाहे ठाकुरु; काहे मन भउ करिआ ॥२॥", punjabi = "ਹੇ ਮਨ! ਤੂੰ ਕਿਉਂ ਡਰਦਾ ਹੈਂ? ਪਾਲਣਹਾਰ ਪ੍ਰਭੂ ਹਰੇਕ ਜੀਵ ਨੂੰ ਆਪ ਹੀ ਰਿਜ਼ਕ ਅਪੜਾਂਦਾ ਹੈ ॥੨॥", wordMeaning = "ਸਿਰਿ = ਸਿਰ ਉੱਤੇ। ਸਿਰਿ ਸਿਰਿ = ਹਰੇਕ ਸਿਰ ਉਤੇ, ਹਰੇਕ ਜੀਵ ਲਈ। ਸੰਬਾਹੇ = {संवाहय} ਅਪੜਾਂਦਾ ਹੈ। ਮਨ = ਹੇ ਮਨ! ॥੨॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-93", gurmukhi = "ਊਡੇ ਊਡਿ. ਆਵੈ ਸੈ ਕੋਸਾ; ਤਿਸੁ ਪਾਛੈ ਬਚਰੇ ਛਰਿਆ ॥", transliteration = "oode ood. aavai sai kosaa; tis paachhai bachre chhriaa ||", translation = "The flamingoes fly hundreds of miles, leaving their young ones behind.", hindi = "ऊडे ऊडि. आवै सै कोसा; तिसु पाछै बचरे छरिआ ॥", punjabi = "(ਹੇ ਮਨ! ਵੇਖ! ਕੂੰਜ) ਉੱਡ ਉੱਡ ਕੇ ਸੈਂਕੜੇ ਕੋਹਾਂ ਤੇ ਆ ਜਾਂਦੀ ਹੈ, ਪਿੱਛੇ ਉਸ ਦੇ ਬੱਚੇ (ਇਕੱਲੇ) ਛੱਡੇ ਹੋਏ ਹੁੰਦੇ ਹਨ।", wordMeaning = "ਊਡੇ = ਊਡਿ। ਊਡੇ ਊਡਿ = ਊਡਿ ਊਡਿ, ਉੱਡ ਕੇ। ਸੈ = ਸੈਂਕੜੇ (ਲਫ਼ਜ਼ 'ਸਉ' ਤੋਂ ਬਹੁ-ਵਚਨ)। ਤਿਸੁ ਪਾਛੈ = ਉਸ (ਕੂੰਜ) ਦੇ ਪਿਛੇ। ਬਚਰੇ = ਨਿੱਕੇ ਨਿੱਕੇ ਬੱਚੇ। ਛਰਿਆ = ਛੱਡੇ ਹੋਏ ਹੁੰਦੇ ਹਨ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-94", gurmukhi = "ਤਿਨ ਕਵਣੁ ਖਲਾਵੈ, ਕਵਣੁ ਚੁਗਾਵੈ; ਮਨ ਮਹਿ. ਸਿਮਰਨੁ ਕਰਿਆ ॥੩॥", transliteration = "tin kavan khlaavai, kavan chugaavai; man mah. simaran kriaa ||3||", translation = "Who feeds them, and who teaches them to feed themselves? Have you ever thought of this in your mind? ||3||", hindi = "तिन कवणु खलावै, कवणु चुगावै; मन महि. सिमरनु करिआ ॥३॥", punjabi = "ਉਹਨਾਂ ਨੂੰ ਕੋਈ ਕੁਝ ਖੁਆਲਣ ਵਾਲਾ ਨਹੀਂ, ਕੋਈ ਉਹਨਾਂ ਨੂੰ ਚੋਗਾ ਨਹੀਂ ਚੁਗਾਂਦਾ। ਉਹ ਕੂੰਜ ਆਪਣੇ ਬੱਚਿਆਂ ਦਾ ਧਿਆਨ ਆਪਣੇ ਮਨ ਵਿਚ ਧਰਦੀ ਰਹਿੰਦੀ ਹੈ (ਤੇ, ਇਸੇ ਨੂੰ ਪ੍ਰਭੂ ਉਹਨਾਂ ਦੇ ਪਾਲਣ ਦਾ ਵਸੀਲਾ ਬਣਾਂਦਾ ਹੈ) ॥੩॥", wordMeaning = "ਚੁਗਾਵੈ = ਚੋਗਾ ਦੇਂਦਾ ਹੈ। ਮਨਿ ਮਹਿ = (ਉਹ ਕੂੰਜ ਆਪਣੇ) ਮਨ ਵਿਚ। ਸਿਮਰਨੁ = (ਉਹਨਾਂ ਬੱਚਿਆਂ ਦਾ) ਧਿਆਨ। ਖਲਾਵੈ = ਖੁਆਲਦਾ ਹੈ। ਕਵਣੁ ਖਲਾਵੈ = ਕੌਣ ਖੁਆਲਦਾ ਹੈ? ਕੋਈ ਭੀ ਕੁਝ ਖੁਆਲਦਾ ਨਹੀਂ।੩। \"ਜੈਸੀ ਗਗਨਿ ਫਿਰੰਤੀ ਊਡਤੀ, ਕਪਰੇ ਬਾਗੇ ਵਾਲੀ। ਉਹ ਰਾਖੈ ਚੀਤੁ ਪੀਛੈ ਬਿਚਿ ਬਚਰੇ, ਨਿਤ ਹਿਰਦੈ ਸਾਰਿ ਸਮਾਲੀ।੧।੭।੧੩।੫੧। (ਗਉੜੀ ਬੈਰਾਗਣਿ ਮ: ੪)।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-95", gurmukhi = "ਸਭਿ ਨਿਧਾਨ. ਦਸ ਅਸਟ ਸਿਧਾਨ; ਠਾਕੁਰ ਕਰ ਤਲ ਧਰਿਆ ॥", transliteration = "sabh nidhaan. das asat sidhaan; thaakur kar tal dhriaa ||", translation = "All the nine treasures, and the eighteen supernatural powers are held by our Lord and Master in the Palm of His Hand.", hindi = "सभि निधान. दस असट सिधान; ठाकुर कर तल धरिआ ॥", punjabi = "ਹੇ ਪਾਲਣਹਾਰ ਪ੍ਰਭੂ! ਜਗਤ ਦੇ ਸਾਰੇ ਖ਼ਜ਼ਾਨੇ ਤੇ ਅਠਾਰਾਂ ਸਿੱਧੀਆਂ (ਮਾਨੋ) ਤੇਰੇ ਹੱਥਾਂ ਦੀਆਂ ਤਲੀਆਂ ਉੱਤੇ ਰੱਖੇ ਪਏ ਹਨ।", wordMeaning = "ਸਭਿ ਨਿਧਾਨ = ਸਾਰੇ ਖ਼ਜ਼ਾਨੇ। ਅਸਟ = ਅੱਠ। ਦਸ ਅਸਟ = ਅਠਾਰਾਂ। ਸਿਧਾਨ = ਸਿੱਧੀਆਂ। ਪਦਮ = ਸੋਨਾ ਚਾਂਦੀ। ਮਹਾ ਪਦਮ = ਹੀਰੇ ਜਵਾਹਰਾਤ। ਸੰਖ = ਸੁੰਦਰ ਭੋਜਨ ਤੇ ਕੱਪੜੇ। ਮਕਰ = ਸ਼ਸਤ੍ਰ ਵਿੱਦਿਆ ਦੀ ਪ੍ਰਾਪਤੀ, ਰਾਜ ਦਰਬਾਰ ਵਿਚ ਮਾਣ। ਮੁਕੰਦੁ = ਰਾਗ ਆਦਿਕ ਕੋਮਲ ਹੁਨਰਾਂ ਦੀ ਪ੍ਰਾਪਤੀ। ਕੁੰਦ = ਸੋਨੇ ਦੀ ਸੁਦਾਗਰੀ। ਨੀਲ = ਮੋਤੀ ਮੂੰਗੇ ਦੀ ਸੁਦਾਗਰੀ। ਕੱਛਪ = ਕੱਪੜੇ ਦਾਣੇ ਦੀ ਸੁਦਾਗਰੀ। ਕਰ ਤਲ = ਹੱਥਾਂ ਦੀਆਂ ਤਲੀਆਂ ਉਤੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-96", gurmukhi = "ਜਨ ਨਾਨਕ. ਬਲਿ ਬਲਿ, ਸਦ ਬਲਿ ਜਾਈਐ; ਤੇਰਾ. ਅੰਤੁ ਨ ਪਾਰਾਵਰਿਆ ॥੪॥੫॥", transliteration = "jan naanak. bal bal, sad bal jaaeeai; teraa. ant na paaraavriaa ||4||5||", translation = "Servant Nanak is devoted, dedicated, forever a sacrifice to You, Lord. Your Expanse has no limit, no boundary. ||4||5||", hindi = "जन नानक. बलि बलि, सद बलि जाईऐ; तेरा. अंतु न पारावरिआ ॥४॥५॥", punjabi = "ਹੇ ਦਾਸ ਨਾਨਕ! ਐਸੇ ਪ੍ਰਭੂ ਤੋਂ ਸਦਾ ਸਦਕੇ ਹੋ, ਸਦਾ ਕੁਰਬਾਨ ਹੋ, (ਤੇ ਆਖ-ਹੇ ਪ੍ਰਭੂ!) ਤੇਰੀ ਬਜ਼ੁਰਗੀ ਦੇ ਉਰਲੇ ਪਾਰਲੇ ਬੰਨੇ ਦਾ ਅੰਤ ਨਹੀਂ ਪੈ ਸਕਦਾ ॥੪॥੫॥", wordMeaning = "ਪਾਰਾਵਰਿਆਂ = ਪਾਰ-ਅਵਰ, ਪਾਰਲਾ ਉਰਲਾ ਬੰਨਾ॥੪॥", startsAtMs = 0L, endsAtMs = 0L)
)

