    BaniLine(id = "rehras-sahib-97", gurmukhi = "ਰਾਗੁ ਆਸਾ ਮਹਲਾ ੪ ਸੋ ਪੁਰਖੁ ॥", transliteration = "raag aasaa mahlaa 4 so purakh ||", translation = "Raag Aasaa, Fourth Mehl, So Purakh ~ That Primal Being:", hindi = "रागु आसा महला ४ सो पुरखु ॥", punjabi = "ਰਾਗ ਆਸਾ ਵਿੱਚ ਗੁਰੂ ਰਾਮਦਾਸ ਜੀ ਦੀ ਬਾਣੀ 'ਸੋ-ਪੁਰਖੁ'।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
