    BaniLine(id = "rehras-sahib-99", gurmukhi = "ਸੋ ਪੁਰਖੁ ਨਿਰੰਜਨੁ, ਹਰਿ ਪੁਰਖੁ ਨਿਰੰਜਨੁ; ਹਰਿ ਅਗਮਾ ਅਗਮ ਅਪਾਰਾ ॥", transliteration = "so purakh niranjan, har purakh niranjan; har agmaa agam apaaraa ||", translation = "That Primal Being is Immaculate and Pure. The Lord, the Primal Being, is Immaculate and Pure. The Lord is Inaccessible, Unreachable and Unrivalled.", hindi = "सो पुरखु निरंजनु, हरि पुरखु निरंजनु; हरि अगमा अगम अपारा ॥", punjabi = "ਉਹ ਪਰਮਾਤਮਾ ਸਾਰੇ ਜੀਵਾਂ ਵਿੱਚ ਵਿਆਪਕ ਹੈ (ਫਿਰ ਵੀ) ਮਾਇਆ ਦੇ ਪ੍ਰਭਾਵ ਤੋਂ ਉਤਾਂਹ ਹੈ, ਅਪਹੁੰਚ ਹੈ ਅਤੇ ਬੇਅੰਤ ਹੈ।", wordMeaning = "ਸੋ = ਉਹ। ਪੁਰਖੁ = { पुरि शोते इति पुरषः} ਜੋ ਹਰੇਕ ਸਰੀਰ ਵਿਚ ਵਿਆਪਕ ਹੈ। ਨਿਰੰਜਨੁ = ਨਿਰ-ਅੰਜਨੁ। ਅੰਜਨੁ = ਕਾਲਖ, ਮਾਇਆ ਦਾ ਪ੍ਰਭਾਵ} ਜਿਸ ਉੱਤੇ ਮਾਇਆ ਦਾ ਪ੍ਰਭਾਵ ਨਹੀਂ ਪੈ ਸਕਦਾ। ਅਗਮ = ਅਪਹੁੰਚ {ਗਮ = ਪਹੁੰਚ}। ਅਪਾਰਾ = ਅ-ਪਾਰ, ਜਿਸ ਦਾ ਪਾਰਲਾ ਬੰਨਾ ਨਾਹ ਲੱਭ ਸਕੇ, ਬੇਅੰਤ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-100", gurmukhi = "ਸਭਿ ਧਿਆਵਹਿ ਸਭਿ ਧਿਆਵਹਿ ਤੁਧੁ ਜੀ; ਹਰਿ ਸਚੇ ਸਿਰਜਣਹਾਰਾ ॥", transliteration = "sabh dhiaavah sabh dhiaavah tudh jee; har sche sirajanhaaraa ||", translation = "All meditate, all meditate on You, Dear Lord, O True Creator Lord.", hindi = "सभि धिआवहि सभि धिआवहि तुधु जी; हरि सचे सिरजणहारा ॥", punjabi = "ਹੇ ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲੇ ਅਤੇ ਸਭ ਜੀਵਾਂ ਨੂੰ ਪੈਦਾ ਕਰਨ ਵਾਲੇ ਹਰੀ! ਸਾਰੇ ਜੀਵ ਤੈਨੂੰ ਸਦਾ ਸਿਮਰਦੇ ਹਨ, ਤੇਰਾ ਧਿਆਨ ਧਰਦੇ ਹਨ।", wordMeaning = "ਸਭਿ = ਸਾਰੇ ਜੀਵ {ਲਫ਼ਜ਼ 'ਜੀਉ' ਤੋਂ ਬਹੁ-ਵਚਨ}।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-101", gurmukhi = "ਸਭਿ ਜੀਅ ਤੁਮਾਰੇ ਜੀ; ਤੂੰ ਜੀਆ ਕਾ ਦਾਤਾਰਾ ॥", transliteration = "sabh jeea tumaare jee; toon jeeaa kaa daataaraa ||", translation = "All living beings are Yours-You are the Giver of all souls.", hindi = "सभि जीअ तुमारे जी; तूं जीआ का दातारा ॥", punjabi = "ਹੇ ਪ੍ਰਭੂ! ਸਾਰੇ ਜੀਵ ਤੇਰੇ ਹੀ ਪੈਦਾ ਕੀਤੇ ਹੋਏ ਹਨ, ਤੂੰ ਹੀ ਸਭ ਜੀਵਾਂ ਦਾ ਰਾਜ਼ਕ ਹੈਂ।", wordMeaning = "ਦਾਤਾਰਾ = ਰਾਜ਼ਕ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-102", gurmukhi = "ਹਰਿ ਧਿਆਵਹੁ ਸੰਤਹੁ ਜੀ; ਸਭਿ ਦੂਖ ਵਿਸਾਰਣਹਾਰਾ ॥", transliteration = "har dhiaavah santah jee; sabh dookh visaaranhaaraa ||", translation = "Meditate on the Lord, O Saints; He is the Dispeller of all sorrow.", hindi = "हरि धिआवहु संतहु जी; सभि दूख विसारणहारा ॥", punjabi = "ਹੇ ਸੰਤ ਜਨੋ! ਉਸ ਪਰਮਾਤਮਾ ਦਾ ਧਿਆਨ ਧਰਿਆ ਕਰੋ, ਉਹ ਸਾਰੇ ਦੁੱਖਾਂ ਦਾ ਨਾਸ ਕਰਨ ਵਾਲਾ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-103", gurmukhi = "ਹਰਿ ਆਪੇ ਠਾਕੁਰੁ, ਹਰਿ ਆਪੇ ਸੇਵਕੁ ਜੀ; ਕਿਆ ਨਾਨਕ. ਜੰਤ ਵਿਚਾਰਾ ॥੧॥", transliteration = "har aape thaakur, har aape sevak jee; kiaa naanak. jant vichaaraa ||1||", translation = "The Lord Himself is the Master, the Lord Himself is the Servant. O Nanak, the poor beings are wretched and miserable! ||1||", hindi = "हरि आपे ठाकुरु, हरि आपे सेवकु जी; किआ नानक. जंत विचारा ॥१॥", punjabi = "ਉਹ (ਸਭ ਜੀਵਾਂ ਵਿਚ ਵਿਆਪਕ ਹੋਣ ਕਰਕੇ) ਆਪ ਹੀ ਮਾਲਕ ਹੈ ਅਤੇ ਆਪ ਹੀ ਸੇਵਕ ਹੈ। ਹੇ ਨਾਨਕ! ਉਸ ਤੋਂ ਬਿਨਾ) ਜੀਵ ਵਿਚਾਰੇ ਕੀਹ ਹਨ? (ਉਸ ਹਰੀ ਤੋਂ ਵੱਖਰੀ ਜੀਵਾਂ ਦੀ ਕੋਈ ਹਸਤੀ ਨਹੀਂ) ॥੧॥", wordMeaning = "ਠਾਕੁਰੁ = ਮਾਲਕ॥੧॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-104", gurmukhi = "ਤੂੰ ਘਟ ਘਟ ਅੰਤਰਿ, ਸਰਬ ਨਿਰੰਤਰਿ ਜੀ; ਹਰਿ ਏਕੋ ਪੁਰਖੁ ਸਮਾਣਾ ॥", transliteration = "toon ghat ghat antar, sarab nirantar jee; har eko purakh smaanaa ||", translation = "You are constant in each and every heart, and in all things. O Dear Lord, you are the One.", hindi = "तूं घट घट अंतरि, सरब निरंतरि जी; हरि एको पुरखु समाणा ॥", punjabi = "ਹੇ ਹਰੀ! ਤੂੰ ਹਰੇਕ ਸਰੀਰ ਵਿਚ ਵਿਆਪਕ ਹੈਂ; ਤੂੰ ਸਾਰੇ ਜੀਵਾਂ ਵਿਚ ਇਕ-ਰਸ ਮੌਜੂਦ ਹੈਂ, ਤੂੰ ਇਕ ਆਪ ਹੀ ਸਭ ਵਿਚ ਸਮਾਇਆ ਹੋਇਆ ਹੈਂ।", wordMeaning = "ਘਟ = ਸਰੀਰ। ਅੰਤਰਿ = ਅੰਦਰ, ਵਿਚ। ਘਟ ਘਟ ਅੰਤਰਿ = ਹਰੇਕ ਸਰੀਰ ਵਿਚ। ਸਰਬ = ਸਾਰੇ। ਨਿਰੰਤਰਿ = ਅੰਦਰ ਇਕ-ਰਸ। ਸਰਬ ਨਿਰੰਤਰਿ = ਸਾਰਿਆਂ ਵਿਚ ਇਕ-ਰਸ। ਅੰਤਰੁ = ਵਿੱਥ। ਨਿਰੰਤਰਿ = ਵਿੱਥ ਤੋਂ ਬਿਨਾ, ਇਕ-ਰਸ। ਏਕੋ = ਇਕ (ਆਪ) ਹੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-105", gurmukhi = "ਇਕਿ ਦਾਤੇ. ਇਕਿ ਭੇਖਾਰੀ ਜੀ; ਸਭਿ ਤੇਰੇ ਚੋਜ ਵਿਡਾਣਾ ॥", transliteration = "ik daate. ik bhekhaaree jee; sabh tere choj vidaanaa ||", translation = "Some are givers, and some are beggars. This is all Your Wondrous Play.", hindi = "इकि दाते. इकि भेखारी जी; सभि तेरे चोज विडाणा ॥", punjabi = "(ਫਿਰ ਭੀ) ਕਈ ਜੀਵ ਦਾਨੀ ਹਨ, ਕਈ ਜੀਵ ਮੰਗਤੇ ਹਨ-ਇਹ ਸਾਰੇ ਤੇਰੇ ਹੀ ਅਚਰਜ ਤਮਾਸ਼ੇ ਹਨ,", wordMeaning = "ਇਕਿ = {ਲਫ਼ਜ਼ 'ਇਕ' ਤੋਂ ਬਹੁ-ਵਚਨ} ਕਈ ਜੀਵ। ਦਾਤੇ = ਦਾਨੀ। ਭੇਖਾਰੀ = ਮੰਗਤੇ। ਸਭਿ = ਸਾਰੇ। ਵਿਡਾਣ = ਅਚਰਜ। ਚੋਜ = ਕੌਤਕ, ਤਮਾਸ਼ੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-106", gurmukhi = "ਤੂੰ ਆਪੇ ਦਾਤਾ. ਆਪੇ ਭੁਗਤਾ ਜੀ; ਹਉ ਤੁਧੁ ਬਿਨੁ ਅਵਰੁ ਨ ਜਾਣਾ ॥", transliteration = "toon aape daataa. aape bhugtaa jee; hau tudh bin avar na jaanaa ||", translation = "You Yourself are the Giver, and You Yourself are the Enjoyer. I know no other than You.", hindi = "तूं आपे दाता. आपे भुगता जी; हउ तुधु बिनु अवरु न जाणा ॥", punjabi = "(ਕਿਉਂਕਿ ਅਸਲ ਵਿਚ) ਤੂੰ ਆਪ ਹੀ ਦਾਤਾਂ ਦੇਣ ਵਾਲਾ ਹੈਂ, ਤੇ, ਆਪ (ਹੀ ਉਹਨਾਂ ਦਾਤਾਂ ਨੂੰ) ਵਰਤਣ ਵਾਲਾ ਹੈਂ। (ਸਾਰੀ ਸ੍ਰਿਸ਼ਟੀ ਵਿਚ) ਮੈਂ ਤੈਥੋਂ ਬਿਨਾ ਕਿਸੇ ਹੋਰ ਨੂੰ ਨਹੀਂ ਪਛਾਣਦਾ (ਤੈਥੋਂ ਬਿਨਾ ਕੋਈ ਹੋਰ ਨਹੀਂ ਦਿੱਸਦਾ)।", wordMeaning = "ਭੁਗਤਾ = ਭੋਗਣ ਵਾਲਾ, ਵਰਤਣ ਵਾਲਾ। ਹਉ = ਹਉਂ, ਮੈਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-107", gurmukhi = "ਤੂੰ ਪਾਰਬ੍ਰਹਮੁ ਬੇਅੰਤੁ ਬੇਅੰਤੁ ਜੀ; ਤੇਰੇ. ਕਿਆ ਗੁਣ ਆਖਿ ਵਖਾਣਾ ॥", transliteration = "toon paarabraham beant beant jee; tere. kiaa gun aakh vkhaanaa ||", translation = "You are the Supreme Lord God, Limitless and Infinite. What Virtues of Yours can I speak of and describe?", hindi = "तूं पारब्रहमु बेअंतु बेअंतु जी; तेरे. किआ गुण आखि वखाणा ॥", punjabi = "ਤੂੰ ਬੇਅੰਤ ਪਾਰਬ੍ਰਹਮ ਹੈਂ। ਮੈਂ ਤੇਰੇ ਕੇਹੜੇ ਕੇਹੜੇ ਗੁਣ ਗਾ ਕੇ ਦੱਸਾਂ?", wordMeaning = "ਆਖਿ = ਆਖ ਕੇ। ਵਖਾਣਾ = ਮੈਂ ਬਿਆਨ ਕਰਾਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-108", gurmukhi = "ਜੋ ਸੇਵਹਿ. ਜੋ ਸੇਵਹਿ ਤੁਧੁ ਜੀ; ਜਨੁ ਨਾਨਕੁ. ਤਿਨ ਕੁਰਬਾਣਾ ॥੨॥", transliteration = "jo sevah. jo sevah tudh jee; jan naanak. tin kurbaanaa ||2||", translation = "Unto those who serve You, unto those who serve You, Dear Lord, servant Nanak is a sacrifice. ||2||", hindi = "जो सेवहि. जो सेवहि तुधु जी; जनु नानकु. तिन कुरबाणा ॥२॥", punjabi = "ਹੇ ਪ੍ਰਭੂ! ਜੇਹੜੇ ਮਨੁੱਖ ਤੈਨੂੰ ਯਾਦ ਕਰਦੇ ਹਨ ਤੈਨੂੰ ਸਿਮਰਦੇ ਹਨ (ਤੇਰਾ) ਦਾਸ ਨਾਨਕ ਉਹਨਾਂ ਤੋਂ ਸਦਕੇ ਜਾਂਦਾ ਹੈ ॥੨॥", wordMeaning = "ਸੇਵਹਿ = ਸਿਮਰਦੇ ਹਨ। ਜਨੁ ਨਾਨਕ = {ਪਿਛਲੇ ਬੰਦ ਵਿਚ ਦੇ 'ਜਨ ਨਾਨਕ' ਅਤੇ ਇਸ 'ਜਨੁ ਨਾਨਕੁ' ਦੇ ਫ਼ਰਕ ਨੂੰ ਧਿਆਨ ਨਾਲ ਵੇਖੋ}॥੨॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-109", gurmukhi = "ਹਰਿ ਧਿਆਵਹਿ. ਹਰਿ ਧਿਆਵਹਿ ਤੁਧੁ ਜੀ; ਸੇ ਜਨ. ਜੁਗ ਮਹਿ ਸੁਖਵਾਸੀ ॥", transliteration = "har dhiaavah. har dhiaavah tudh jee; se jan. jug mah sukhvaasee ||", translation = "Those who meditate on You, Lord, those who meditate on You-those humble beings dwell in peace in this world.", hindi = "हरि धिआवहि. हरि धिआवहि तुधु जी; से जन. जुग महि सुखवासी ॥", punjabi = "ਹੇ ਪ੍ਰਭੂ ਜੀ! ਜੇਹੜੇ ਮਨੁੱਖ ਤੈਨੂੰ ਸਿਮਰਦੇ ਹਨ ਤੇਰਾ ਧਿਆਨ ਧਰਦੇ ਹਨ, ਉਹ ਬੰਦੇ ਆਪਣੀ ਜ਼ਿੰਦਗੀ ਵਿਚ ਸੁਖੀ ਵੱਸਦੇ ਹਨ।", wordMeaning = "ਹਰਿ ਜੀ = ਹੇ ਪ੍ਰਭੂ ਜੀ! ਧਿਆਵਹਿ = ਸਿਮਰਦੇ ਹਨ। ਸੇ ਜਨ = ਉਹ ਬੰਦੇ। ਜੁਗਿ ਮਹਿ = ਜ਼ਿੰਦਗੀ ਵਿਚ। ਸੁਖਵਾਸੀ = ਸੁਖ ਨਾਲ ਵੱਸਣ ਵਾਲੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-110", gurmukhi = "ਸੇ ਮੁਕਤੁ. ਸੇ ਮੁਕਤੁ ਭਏ, ਜਿਨ ਹਰਿ ਧਿਆਇਆ ਜੀ; ਤਿਨ. ਤੂਟੀ ਜਮ ਕੀ ਫਾਸੀ ॥", transliteration = "se mukat. se mukat bhae, jin har dhiaaiaa jee; tin. tootee jam kee phaasee ||", translation = "They are liberated, they are liberated-those who meditate on the Lord. For them, the noose of death is cut away.", hindi = "से मुकतु. से मुकतु भए, जिन हरि धिआइआ जी; तिन. तूटी जम की फासी ॥", punjabi = "ਜਿਨ੍ਹਾਂ ਮਨੁੱਖਾਂ ਨੇ ਹਰਿ-ਨਾਮ ਸਿਮਰਿਆ ਹੈ, ਉਹ ਸਦਾ ਲਈ ਮਾਇਆ ਦੇ ਬੰਧਨਾਂ ਤੋਂ ਆਜ਼ਾਦ ਹੋ ਗਏ ਹਨ, ਉਹਨਾਂ ਦੀ ਜਮਾਂ ਵਾਲੀ ਫਾਹੀ ਟੁੱਟ ਗਈ ਹੈ (ਆਤਮਕ ਮੌਤ ਉਹਨਾਂ ਦੇ ਨੇੜੇ ਨਹੀਂ ਢੁੱਕਦੀ)।", wordMeaning = "ਮੁਕਤੁ = (ਮਾਇਆ ਦੇ ਬੰਧਨਾਂ ਤੋਂ) ਆਜ਼ਾਦ। ਫਾਸੀ = ਫਾਹੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-111", gurmukhi = "ਜਿਨ ਨਿਰਭਉ. ਜਿਨ ਹਰਿ ਨਿਰਭਉ ਧਿਆਇਆ ਜੀ; ਤਿਨ ਕਾ. ਭਉ ਸਭੁ ਗਵਾਸੀ ॥", transliteration = "jin nirabhau. jin har nirabhau dhiaaiaa jee; tin kaa. bhau sabh gvaasee ||", translation = "Those who meditate on the Fearless One, on the Fearless Lord-all their fears are dispelled.", hindi = "जिन निरभउ. जिन हरि निरभउ धिआइआ जी; तिन का. भउ सभु गवासी ॥", punjabi = "ਜਿਨ੍ਹਾਂ ਬੰਦਿਆਂ ਨੇ ਸਦਾ ਨਿਰਭਉ ਪ੍ਰਭੂ ਦਾ ਨਾਮ ਸਿਮਰਿਆ ਹੈ; ਪ੍ਰਭੂ ਉਹਨਾਂ ਦਾ ਸਾਰਾ ਡਰ ਦੂਰ ਕਰ ਦੇਂਦਾ ਹੈ।", wordMeaning = "ਭਉ ਸਭੁ = ਸਾਰਾ ਡਰ। ਗਵਾਸੀ = ਦੂਰ ਕਰ ਦੇਂਦਾ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-112", gurmukhi = "ਜਿਨ ਸੇਵਿਆ. ਜਿਨ ਸੇਵਿਆ ਮੇਰਾ ਹਰਿ ਜੀ; ਤੇ. ਹਰਿ ਹਰਿ ਰੂਪਿ ਸਮਾਸੀ ॥", transliteration = "jin seviaa. jin seviaa meraa har jee; te. har har roop smaasee ||", translation = "Those who serve, those who serve my Dear Lord, are absorbed into the Being of the Lord, Har, Har.", hindi = "जिन सेविआ. जिन सेविआ मेरा हरि जी; ते. हरि हरि रूपि समासी ॥", punjabi = "ਜਿਨ੍ਹਾਂ ਮਨੁੱਖਾਂ ਨੇ ਪਿਆਰੇ ਪ੍ਰਭੂ ਨੂੰ ਸਦਾ ਸਿਮਰਿਆ ਹੈ, ਉਹ ਪ੍ਰਭੂ ਦੇ ਰੂਪ ਵਿਚ ਹੀ ਲੀਨ ਹੋ ਗਏ ਹਨ।", wordMeaning = "ਰੂਪਿ = ਰੂਪ ਵਿਚ। ਸਮਾਸੀ = ਮਿਲ ਜਾਂਦੇ ਹਨ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-113", gurmukhi = "ਸੇ ਧੰਨੁ ਸੇ ਧੰਨੁ. ਜਿਨ ਹਰਿ ਧਿਆਇਆ ਜੀ; ਜਨੁ ਨਾਨਕੁ. ਤਿਨ ਬਲਿ ਜਾਸੀ ॥੩॥", transliteration = "se dhann se dhann. jin har dhiaaiaa jee; jan naanak. tin bal jaasee ||3||", translation = "Blessed are they, blessed are they, who meditate on their Dear Lord. Servant Nanak is a sacrifice to them. ||3||", hindi = "से धंनु से धंनु. जिन हरि धिआइआ जी; जनु नानकु. तिन बलि जासी ॥३॥", punjabi = "ਭਾਗਾਂ ਵਾਲੇ ਹਨ ਉਹ ਮਨੁੱਖ, ਧੰਨ ਹਨ ਉਹ ਮਨੁੱਖ, ਜਿਨ੍ਹਾਂ ਪ੍ਰਭੂ ਦਾ ਨਾਮ ਸਿਮਰਿਆ ਹੈ। ਦਾਸ ਨਾਨਕ ਉਹਨਾਂ ਤੋਂ ਸਦਕੇ ਜਾਂਦਾ ਹੈ ॥੩॥", wordMeaning = "ਧੰਨ = ਭਾਗਾਂ ਵਾਲੇ। ਬਲਿ ਜਾਸੀ = ਸਦਕੇ ਜਾਂਦਾ ਹੈ॥੩॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-114", gurmukhi = "ਤੇਰੀ ਭਗਤਿ ਤੇਰੀ ਭਗਤਿ ਭੰਡਾਰ ਜੀ; ਭਰੇ ਬਿਅੰਤ ਬੇਅੰਤਾ ॥", transliteration = "teree bhagat teree bhagat bhandaar jee; bhre biant beantaa ||", translation = "Devotion to You, devotion to You, is a treasure overflowing, infinite and beyond measure.", hindi = "तेरी भगति तेरी भगति भंडार जी; भरे बिअंत बेअंता ॥", punjabi = "ਹੇ ਪ੍ਰਭੂ! ਤੇਰੀ ਭਗਤੀ ਦੇ ਬੇਅੰਤ ਖ਼ਜਾਨੇ ਭਰੇ ਪਏ ਹਨ।", wordMeaning = "ਭਗਤਿ ਭੰਡਾਰ = ਭਗਤੀ ਦੇ ਖ਼ਜ਼ਾਨੇ। ਭਗਤ = ਭਗਤੀ ਕਰਨ ਵਾਲੇ {ਨੋਟ: ਲਫ਼ਜ਼ 'ਭਗਤਿ' ਅਤੇ 'ਭਗਤ' ਦਾ ਫ਼ਰਕ ਚੇਤੇ ਰੱਖਣ-ਯੋਗ ਹੈ}।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-115", gurmukhi = "ਤੇਰੇ ਭਗਤ. ਤੇਰੇ ਭਗਤ. ਸਲਾਹਨਿ ਤੁਧੁ ਜੀ; ਹਰਿ ਅਨਿਕ ਅਨੇਕ ਅਨੰਤਾ ॥", transliteration = "tere bhagat. tere bhagat. slaahan tudh jee; har anik anek anantaa ||", translation = "Your devotees, Your devotees praise You, Dear Lord, in many and various and countless ways.", hindi = "तेरे भगत. तेरे भगत. सलाहनि तुधु जी; हरि अनिक अनेक अनंता ॥", punjabi = "ਹੇ ਹਰੀ! ਅਨੇਕਾਂ ਤੇ ਬੇਅੰਤ ਤੇਰੇ ਭਗਤ ਤੇਰੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਕਰ ਰਹੇ ਹਨ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-116", gurmukhi = "ਤੇਰੀ ਅਨਿਕ ਤੇਰੀ ਅਨਿਕ, ਕਰਹਿ ਹਰਿ ਪੂਜਾ ਜੀ; ਤਪੁ ਤਾਪਹਿ, ਜਪਹਿ ਬੇਅੰਤਾ ॥", transliteration = "teree anik teree anik, karah har poojaa jee; tap taapah, japah beantaa ||", translation = "For You, many, for You, so very many perform worship services, O Dear Infinite Lord; they practice disciplined meditation and chant endlessly.", hindi = "तेरी अनिक तेरी अनिक, करहि हरि पूजा जी; तपु तापहि, जपहि बेअंता ॥", punjabi = "ਹੇ ਪ੍ਰਭੂ! ਅਨੇਕਾਂ ਜੀਵ ਤੇਰੀ ਪੂਜਾ ਕਰਦੇ ਹਨ। ਬੇਅੰਤ ਜੀਵ (ਤੈਨੂੰ ਮਿਲਣ ਲਈ) ਤਪ ਸਾਧਦੇ ਹਨ।", wordMeaning = "ਅਨਿਕ = ਅਨੇਕਾਂ। ਤਪੁ = ਧੂਣੀਆਂ ਆਦਿਕ ਦਾ ਸਰੀਰਕ ਔਖ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-117", gurmukhi = "ਤੇਰੇ ਅਨੇਕ ਤੇਰੇ ਅਨੇਕ, ਪੜਹਿ ਬਹੁ ਸਿਮ੍ਰਿਤਿ ਸਾਸਤ ਜੀ; ਕਰਿ ਕਿਰਿਆ ਖਟੁ ਕਰਮ ਕਰੰਤਾ ॥", transliteration = "tere anek tere anek, parah bah simrit saasat jee; kar kiriaa khat karam karantaa ||", translation = "For You, many, for You, so very many read the various Simritees and Shaastras. They perform rituals and religious rites.", hindi = "तेरे अनेक तेरे अनेक, पड़हि बहु सिम्रिति सासत जी; करि किरिआ खटु करम करंता ॥", punjabi = "ਤੇਰੇ ਅਨੇਕਾਂ (ਸੇਵਕ) ਕਈ ਸਿਮ੍ਰਿਤਿਆਂ ਅਤੇ ਸ਼ਾਸਤ੍ਰ ਪੜ੍ਹਦੇ ਹਨ (ਅਤੇ ਉਹਨਾਂ ਦੇ ਦੱਸੇ ਹੋਏ) ਛੇ ਧਾਰਮਿਕ ਕੰਮ ਤੇ ਹੋਰ ਕਰਮ ਕਰਦੇ ਹਨ।", wordMeaning = "ਸਿਮ੍ਰਿਤਿ = ਉਹ ਧਾਰਮਿਕ ਪੁਸਤਕ ਜੋ ਹਿੰਦੂ ਵਿਦਵਾਨ ਰਿਸ਼ੀਆਂ ਨੇ ਵੇਦਾਂ ਨੂੰ ਚੇਤੇ ਕਰ ਕੇ ਆਪਣੇ ਸਮਾਜ ਦੀ ਅਗਵਾਈ ਲਈ ਲਿਖੇ, ਇਹਨਾਂ ਦੀ ਗਿਣਤੀ ੨੭ ਦੇ ਕਰੀਬ ਹੈ। ਸਾਸਤ = ਹਿੰਦੂ ਧਰਮ ਦੇ ਫਲਸਫ਼ੇ ਦੇ ਪੁਸਤਕ ਜੋ ਗਿਣਤੀ ਵਿਚ ਛੇ ਹਨ: ਸਾਂਖ, ਯੋਗ, ਨਿਆਇ, ਵੈਸ਼ੇਸ਼ਿਕ, ਮੀਮਾਂਸਾ, ਵੇਦਾਂਤ। ਕਿਰਿਆ = ਧਾਰਮਿਕ ਸੰਸਕਾਰ। ਖਟੁ = ਛੇ। ਖਟੁ ਕਰਮ = ਮਨੂ-ਸਿਮ੍ਰਿਤੀ ਅਨੁਸਾਰ ਇਹ ਛੇ ਕਰਮ ਇਉਂ ਹਨ: ਵਿਦਿਆ ਪੜ੍ਹਨੀ ਤੇ ਪੜ੍ਹਾਣੀ; ਜੱਗ ਕਰਨਾ ਤੇ ਜੱਗ ਕਰਾਣਾ; ਦਾਨ ਦੇਣਾ ਤੇ ਦਾਨ ਲੈਣਾ। ਕਰੰਤਾ = ਕਰਦੇ ਹਨ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-118", gurmukhi = "ਸੇ ਭਗਤ ਸੇ ਭਗਤ ਭਲੇ, ਜਨ ਨਾਨਕ ਜੀ; ਜੋ ਭਾਵਹਿ ਮੇਰੇ ਹਰਿ ਭਗਵੰਤਾ ॥੪॥", transliteration = "se bhagat se bhagat bhle, jan naanak jee; jo bhaavah mere har bhagavantaa ||4||", translation = "Those devotees, those devotees are sublime, O servant Nanak, who are pleasing to my Dear Lord God. ||4||", hindi = "से भगत से भगत भले, जन नानक जी; जो भावहि मेरे हरि भगवंता ॥४॥", punjabi = "ਹੇ ਦਾਸ ਨਾਨਕ! ਉਹੀ ਭਗਤ ਭਲੇ ਹਨ (ਉਹਨਾਂ ਦੀ ਹੀ ਘਾਲ ਕਬੂਲ ਹੋਈ ਜਾਣੋ) ਜੋ ਪਿਆਰੇ ਹਰਿ-ਭਗਵੰਤ ਨੂੰ ਪਿਆਰੇ ਲੱਗਦੇ ਹਨ ॥੪॥", wordMeaning = "ਭਾਵਹਿ = ਚੰਗੇ ਲੱਗਦੇ ਹਨ॥੪॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-119", gurmukhi = "ਤੂੰ ਆਦਿ ਪੁਰਖੁ ਅਪਰੰਪਰੁ ਕਰਤਾ ਜੀ; ਤੁਧੁ ਜੇਵਡੁ. ਅਵਰੁ ਨ ਕੋਈ ॥", transliteration = "toon aad purakh aparampar kartaa jee; tudh jevad. avar na koee ||", translation = "You are the Primal Being, the Most Wonderful Creator. There is no other as Great as You.", hindi = "तूं आदि पुरखु अपरंपरु करता जी; तुधु जेवडु. अवरु न कोई ॥", punjabi = "ਹੇ ਪ੍ਰਭੂ! ਤੂੰ (ਸਾਰੇ ਜਗਤ ਦਾ) ਮੂਲ ਹੈਂ, ਸਭ ਵਿਚ ਵਿਆਪਕ ਹੈਂ, ਬੇਅੰਤ ਹੈਂ, ਸਭ ਦਾ ਪੈਦਾ ਕਰਨ ਵਾਲਾ ਹੈਂ, ਅਤੇ ਤੇਰੇ ਬਰਾਬਰ ਦਾ ਹੋਰ ਕੋਈ ਨਹੀਂ ਹੈ।", wordMeaning = "ਆਦਿ = ਮੁੱਢ। ਅਪਰੰਪਰੁ = ਅ-ਪਰੰ = ਪਰ, ਜਿਸ ਦਾ ਪਰਲੇ ਤੋਂ ਪਰਲਾ ਬੰਨਾ ਨਾਹ ਲੱਭ ਸਕੇ, ਬੇਅੰਤ। ਤੁਧੁ ਜੇਵਡੁ = ਤੇਰੇ ਜੇਡਾ, ਤੇਰੇ ਬਰਾਬਰ ਦਾ। ਅਵਰੁ = ਹੋਰ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-120", gurmukhi = "ਤੂੰ ਜੁਗੁ ਜੁਗੁ ਏਕੋ, ਸਦਾ ਸਦਾ ਤੂੰ ਏਕੋ ਜੀ; ਤੂੰ ਨਿਹਚਲੁ ਕਰਤਾ ਸੋਈ ॥", transliteration = "toon jug jug eko, sdaa sdaa toon eko jee; toon nihachal kartaa soee ||", translation = "Age after age, You are the One. Forever and ever, You are the One. You never change, O Creator Lord.", hindi = "तूं जुगु जुगु एको, सदा सदा तूं एको जी; तूं निहचलु करता सोई ॥", punjabi = "ਤੂੰ ਹਰੇਕ ਜੁਗ ਵਿਚ ਇਕ ਆਪ ਹੀ ਹੈਂ, ਤੂੰ ਸਦਾ ਹੀ ਆਪ ਹੀ ਆਪ ਹੈਂ, ਤੂੰ ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ ਹੈਂ, ਸਭ ਦਾ ਪੈਦਾ ਕਰਨ ਵਾਲਾ ਹੈਂ, ਸਭ ਦੀ ਸਾਰ ਲੈਣ ਵਾਲਾ ਹੈਂ।", wordMeaning = "ਜੁਗੁ ਜੁਗੁ = ਹਰੇਕ ਜੁਗੁ ਵਿਚ। ਏਕੋ = ਇਕ ਆਪ ਹੀ। ਨਿਹਚਲੁ = ਨਾਹ ਹਿੱਲਣ ਵਾਲਾ, ਅਟੱਲ। ਵਰਤੈ = ਹੁੰਦਾ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-121", gurmukhi = "ਤੁਧੁ ਆਪੇ ਭਾਵੈ ਸੋਈ ਵਰਤੈ ਜੀ; ਤੂੰ ਆਪੇ ਕਰਹਿ ਸੁ ਹੋਈ ॥", transliteration = "tudh aape bhaavai soee vartai jee; toon aape karah su hoee ||", translation = "Everything happens according to Your Will. You Yourself accomplish all that occurs.", hindi = "तुधु आपे भावै सोई वरतै जी; तूं आपे करहि सु होई ॥", punjabi = "ਹੇ ਪ੍ਰਭੂ! ਜਗਤ ਵਿਚ ਉਹੀ ਹੁੰਦਾ ਹੈ ਜੋ ਤੈਨੂੰ ਆਪ ਨੂੰ ਚੰਗਾ ਲੱਗਦਾ ਹੈ, ਉਹੀ ਹੁੰਦਾ ਹੈ ਜੋ ਤੂੰ ਆਪ ਹੀ ਕਰਦਾ ਹੈਂ।", wordMeaning = "ਸੁ = ਉਹ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-122", gurmukhi = "ਤੁਧੁ ਆਪੇ ਸ੍ਰਿਸਟਿ ਸਭ ਉਪਾਈ ਜੀ; ਤੁਧੁ ਆਪੇ ਸਿਰਜਿ ਸਭ ਗੋਈ ॥", transliteration = "tudh aape srisat sabh upaaee jee; tudh aape siraj sabh goee ||", translation = "You Yourself created the entire universe, and having fashioned it, You Yourself shall destroy it all.", hindi = "तुधु आपे स्रिसटि सभ उपाई जी; तुधु आपे सिरजि सभ गोई ॥", punjabi = "ਹੇ ਪ੍ਰਭੂ! ਸਾਰੀ ਸ੍ਰਿਸ਼ਟੀ ਤੂੰ ਆਪ ਹੀ ਪੈਦਾ ਕੀਤੀ ਹੈ। ਤੂੰ ਆਪ ਹੀ ਇਸ ਨੂੰ ਪੈਦਾ ਕਰਕੇ ਆਪ ਹੀ ਇਸ ਨੂੰ ਨਾਸ ਕਰਦਾ ਹੈਂ।", wordMeaning = "ਸਭ = ਸਾਰੀ। ਉਪਾਈ = ਪੈਦਾ ਕੀਤੀ। ਸਿਰਜਿ = ਪੈਦਾ ਕਰ ਕੇ। ਆਪੇ = ਆਪ ਹੀ। ਗੋਈ = ਨਾਸ ਕੀਤੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-123", gurmukhi = "ਜਨੁ ਨਾਨਕੁ. ਗੁਣ ਗਾਵੈ ਕਰਤੇ ਕੇ ਜੀ; ਜੋ ਸਭਸੈ ਕਾ ਜਾਣੋਈ ॥੫॥੧॥", transliteration = "jan naanak. gun gaavai karte ke jee; jo sabhsai kaa jaanoee ||5||1||", translation = "Servant Nanak sings the Glorious Praises of the Dear Creator, the Knower of all. ||5||1||", hindi = "जनु नानकु. गुण गावै करते के जी; जो सभसै का जाणोई ॥५॥१॥", punjabi = "ਦਾਸ ਨਾਨਕ ਉਸ ਕਰਤਾਰ ਦੇ ਗੁਣ ਗਾਂਦਾ ਹੈ ਜੋ ਹਰੇਕ ਜੀਵ ਦੇ ਦਿਲ ਦੀ ਜਾਣਨ ਵਾਲਾ ਹੈ ॥੫॥੧॥", wordMeaning = "ਜਾਣੋਈ = ਜਾਣਨ ਵਾਲਾ। ਸਭਸੈ ਕਾ = ਹਰੇਕ (ਦੇ ਦਿਲ) ਦਾ। ਸੋਈ = ਸੰਭਾਲ ਕਰਨ ਵਾਲਾ॥੫॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-124", gurmukhi = "ਆਸਾ ਮਹਲਾ ੪ ॥", transliteration = "aasaa mahlaa 4 ||", translation = "Aasaa, Fourth Mehl:", hindi = "आसा महला ४ ॥", punjabi = "ਆਸਾ ਰਾਗ, ਚਊਥੀ ਪਾਤਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-125", gurmukhi = "ਤੂੰ ਕਰਤਾ ਸਚਿਆਰੁ; ਮੈਡਾ ਸਾਂਈ ॥", transliteration = "toon kartaa schiaar; maidaa saanee ||", translation = "You are the True Creator, my Lord and Master.", hindi = "तूं करता सचिआरु; मैडा सांई ॥", punjabi = "(ਹੇ ਪ੍ਰਭੂ!) ਤੂੰ ਸਭ ਦਾ ਪੈਦਾ ਕਰਨ ਵਾਲਾ ਹੈਂ, ਤੂੰ ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ ਹੈਂ, ਤੂੰ ਹੀ ਮੇਰਾ ਖਸਮ ਹੈਂ।", wordMeaning = "ਸਚਿਆਰੁ = {ਸਚ-ਆਲਯ} ਥਿਰਤਾ ਦਾ ਘਰ, ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ। ਮੈਡਾ = ਮੇਰਾ। ਸਾਂਈ = ਖਸਮ, ਮਾਲਕ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-126", gurmukhi = "ਜੋ ਤਉ ਭਾਵੈ. ਸੋਈ ਥੀਸੀ; ਜੋ ਤੂੰ ਦੇਹਿ. ਸੋਈ ਹਉ ਪਾਈ ॥੧॥ ਰਹਾਉ ॥", transliteration = "jo tau bhaavai. soee theesee; jo toon deh. soee hau paaee ||1|| rhaau ||", translation = "Whatever pleases You comes to pass. As You give, so do we receive. ||1||Pause||", hindi = "जो तउ भावै. सोई थीसी; जो तूं देहि. सोई हउ पाई ॥१॥ रहाउ ॥", punjabi = "(ਜਗਤ ਵਿਚ) ਉਹੀ ਕੁਝ ਹੁੰਦਾ ਹੈ ਜੋ ਤੈਨੂੰ ਪਸੰਦ ਆਉਂਦਾ ਹੈ। ਜੋ ਕੁਝ ਤੂੰ ਦੇਵੇਂ, ਮੈਂ ਉਹੀ ਕੁਝ ਪ੍ਰਾਪਤ ਕਰਦਾ ਹਾਂ ॥੧॥ ਰਹਾਉ ॥", wordMeaning = "ਤਉ = ਤੈਨੂੰ। ਭਾਵੈ = ਚੰਗਾ ਲੱਗਦਾ ਹੈ। ਥੀਸੀ = ਹੋਵੇਗਾ। ਹਉ = ਹਉਂ, ਮੈਂ। ਪਾਈ = ਪਾਈਂ, ਮੈਂ ਪ੍ਰਾਪਤ ਕਰਦਾ ਹਾਂ ॥੧॥ ਰਹਾਉ ॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-127", gurmukhi = "ਸਭ ਤੇਰੀ; ਤੂੰ ਸਭਨੀ ਧਿਆਇਆ ॥", transliteration = "sabh teree; toon sabhnee dhiaaiaa ||", translation = "All belong to You, all meditate on you.", hindi = "सभ तेरी; तूं सभनी धिआइआ ॥", punjabi = "(ਹੇ ਪ੍ਰਭੂ!) ਸਾਰੀ ਸ੍ਰਿਸ਼ਟੀ ਤੇਰੀ (ਬਣਾਈ ਹੋਈ) ਹੈ, ਸਾਰੇ ਜੀਵ ਤੈਨੂੰ ਹੀ ਸਿਮਰਦੇ ਹਨ।", wordMeaning = "ਸਭ = ਸਾਰੀ (ਸ੍ਰਿਸ਼ਟੀ)। ਤੂੰ = ਤੈਨੂੰ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-128", gurmukhi = "ਜਿਸ ਨੋ ਕ੍ਰਿਪਾ ਕਰਹਿ; ਤਿਨਿ ਨਾਮ ਰਤਨੁ ਪਾਇਆ ॥", transliteration = "jis no kripaa karah; tin naam ratan paaiaa ||", translation = "Those who are blessed with Your Mercy obtain the Jewel of the Naam, the Name of the Lord.", hindi = "जिस नो क्रिपा करहि; तिनि नाम रतनु पाइआ ॥", punjabi = "ਜਿਸ ਉੱਤੇ ਤੂੰ ਦਇਆ ਕਰਦਾ ਹੈਂ ਉਸੇ ਨੇ ਤੇਰਾ ਰਤਨ ਵਰਗਾ (ਕੀਮਤੀ) ਨਾਮ ਲੱਭਾ ਹੈ।", wordMeaning = "ਤਿਨਿ = ਉਸ (ਮਨੁੱਖ) ਨੇ।", startsAtMs = 0L, endsAtMs = 0L)
)

private fun generatedRehrasSahibLines4(): List<BaniLine> = listOf(
    BaniLine(id = "rehras-sahib-129", gurmukhi = "ਗੁਰਮੁਖਿ ਲਾਧਾ; ਮਨਮੁਖਿ ਗਵਾਇਆ ॥", transliteration = "gurmukh laadhaa; manmukh gvaaiaa ||", translation = "The Gurmukhs obtain it, and the self-willed manmukhs lose it.", hindi = "गुरमुखि लाधा; मनमुखि गवाइआ ॥", punjabi = "ਜੋ ਮਨੁੱਖ ਗੁਰੂ ਦੇ ਸਨਮੁਖ ਹੋਇਆ ਉਸ ਨੇ (ਇਹ ਰਤਨ) ਲੱਭ ਲਿਆ। ਜੋ ਆਪਣੇ ਮਨ ਦੇ ਪਿੱਛੇ ਤੁਰਿਆ, ਉਸ ਨੇ ਗਵਾ ਲਿਆ।", wordMeaning = "ਗੁਰਮੁਖਿ = ਉਹ ਮਨੁੱਖ ਜਿਸ ਦਾ ਮੂੰਹ ਗੁਰੂ ਵਲ ਹੈ। ਮਨਮੁਖਿ = ਉਹ ਮਨੁੱਖ ਜਿਸ ਦਾ ਮੂੰਹ ਆਪਣੇ ਮਨ ਵਲ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
