    BaniLine(id = "rehras-sahib-143", gurmukhi = "ਆਸਾ ਮਹਲਾ ੧ ॥", transliteration = "aasaa mahlaa 1 ||", translation = "Aasaa, First Mehl:", hindi = "आसा महला १ ॥", punjabi = "ਆਸਾ ਰਾਗ, ਪਹਿਲੀ ਪਾਤਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-144", gurmukhi = "ਤਿਤੁ ਸਰਵਰੜੈ, ਭਈਲੇ ਨਿਵਾਸਾ; ਪਾਣੀ ਪਾਵਕੁ ਤਿਨਹਿ ਕੀਆ ॥", transliteration = "tit saravarrai, bhaeele nivaasaa; paanee paavak tinah keeaa ||", translation = "In that pool, people have made their homes, but the water there is as hot as fire!", hindi = "तितु सरवरड़ै, भईले निवासा; पाणी पावकु तिनहि कीआ ॥", punjabi = "(ਹੇ ਭਾਈ! ਸਾਡੀ ਜੀਵਾਂ ਦੀ) ਉਸ ਭਿਆਨਕ (ਸੰਸਾਰ-) ਸਰੋਵਰ ਵਿਚ ਵੱਸੋਂ ਹੈ (ਜਿਸ ਵਿਚ) ਉਸ ਪ੍ਰਭੂ ਨੇ ਆਪ ਹੀ ਪਾਣੀ (ਦੇ ਥਾਂ ਤ੍ਰਿਸ਼ਨਾ ਦੀ) ਅੱਗ ਪੈਦਾ ਕੀਤੀ ਹੋਈ ਹੈ।", wordMeaning = "ਤਿਤੁ = ਉਸ ਵਿਚ {ਲਫ਼ਜ਼ 'ਤਿਸੁ' ਤੋਂ 'ਤਿਤੁ' ਅਧਿਕਰਨ ਕਾਰਕ, ਇਕ-ਵਚਨ ਹੈ}। ਸਰਵਰੁ = ਤਾਲਾਬ। ਸਰਵਰੜਾ = ਭਿਆਨਕ ਤਾਲਾਬ। ਸਰਵਰੜੈ = ਭਿਆਨਕ ਤਾਲਾਬ ਵਿਚ। ਤਿਤੁ ਸਰਵਰੜੈ = ਉਸ ਭਿਆਨਕ ਸਰ ਵਿਚ। ਭਈਲੇ = ਹੋਇਆ ਹੈ। ਪਾਵਕੁ = ਅੱਗ, ਤਿਸ਼੍ਰਨਾ ਦੀ ਅੱਗ। ਤਿਨਹਿ = ਉਸ (ਪ੍ਰਭੂ) ਨੇ (ਆਪ ਹੀ)।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-145", gurmukhi = "ਪੰਕਜੁ ਮੋਹ, ਪਗੁ ਨਹੀ ਚਾਲੈ; ਹਮ ਦੇਖਾ. ਤਹ ਡੂਬੀਅਲੇ ॥੧॥", transliteration = "pankaj moh, pag nhee chaalai; ham dekhaa. tah doobeeale ||1||", translation = "In the swamp of emotional attachment, their feet cannot move. I have seen them drowning there. ||1||", hindi = "पंकजु मोह, पगु नही चालै; हम देखा. तह डूबीअले ॥१॥", punjabi = "(ਅਤੇ ਉਸ ਭਿਆਨਕ ਸਰੀਰ ਵਿਚ) ਜੋ ਮੋਹ ਦਾ ਚਿੱਕੜ ਹੈ (ਉਸ ਵਿਚ ਜੀਵਾਂ ਦਾ) ਪੈਰ ਚੱਲ ਨਹੀਂ ਸਕਦਾ (ਜੀਵ ਮੋਹ ਦੇ ਚਿੱਕੜ ਵਿਚ ਫਸੇ ਪਏ ਹਨ)। ਸਾਡੇ ਸਾਹਮਣੇ ਹੀ (ਅਨੇਕਾਂ ਜੀਵ ਮੋਹ ਦੇ ਚਿੱਕੜ ਵਿਚ ਫਸ ਕੇ) ਉਸ (ਤ੍ਰਿਸ਼ਨਾ-ਅੱਗ ਦੇ ਅਸਗਾਹ ਸਮੁੰਦਰ) ਵਿਚ ਡੁੱਬਦੇ ਜਾ ਰਹੇ ਹਨ ॥੧॥", wordMeaning = "ਪੰਕ = ਚਿੱਕੜ। ਪੰਕ ਜੁ ਮੋਹ = ਜੋ ਮੋਹ ਦਾ ਚਿੱਕੜ ਹੈ। ਪਗੁ = ਪੈਰ। ਹਮ ਦੇਖਾ = ਸਾਡੇ ਵੇਖਦਿਆਂ ਹੀ, ਸਾਡੇ ਸਾਹਮਣੇ ਹੀ। ਤਹ = ਉਸ (ਸਾਰ) ਵਿਚ। ਡੂਬੀਅਲੇ = ਡੁੱਬ ਗਏ, ਡੁੱਬ ਰਹੇ ਹਨ॥੧॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-146", gurmukhi = "ਮਨ. ਏਕੁ ਨ ਚੇਤਸਿ; ਮੂੜ ਮਨਾ ॥", transliteration = "man. ek na chetas; moor mnaa ||", translation = "In your mind, you do not remember the One Lord-you fool!", hindi = "मन. एकु न चेतसि; मूड़ मना ॥", punjabi = "ਹੇ ਮਨ! ਹੇ ਮੂਰਖ ਮਨ! ਤੂੰ ਇੱਕ ਪਰਮਾਤਮਾ ਨੂੰ ਯਾਦ ਨਹੀਂ ਕਰਦਾ।", wordMeaning = "ਮਨ = ਹੇ ਮਨ! ਮੂੜ ਮਨਾ = ਹੇ ਮੂਰਖ ਮਨ!", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-147", gurmukhi = "ਹਰਿ ਬਿਸਰਤ; ਤੇਰੇ ਗੁਣ ਗਲਿਆ ॥੧॥ ਰਹਾਉ ॥", transliteration = "har bisarat; tere gun gliaa ||1|| rhaau ||", translation = "You have forgotten the Lord; your virtues shall wither away. ||1||Pause||", hindi = "हरि बिसरत; तेरे गुण गलिआ ॥१॥ रहाउ ॥", punjabi = "ਤੂੰ ਜਿਉਂ ਜਿਉਂ ਪਰਮਾਤਮਾ ਨੂੰ ਵਿਸਾਰਦਾ ਜਾ ਰਿਹਾ ਹੈਂ, ਤੇਰੇ (ਅੰਦਰੋਂ) ਗੁਣ ਘਟਦੇ ਜਾ ਰਹੇ ਹਨ ॥੧॥ ਰਹਾਉ ॥", wordMeaning = "ਗਲਿਆ = ਗਲਦੇ ਜਾ ਰਹੇ ਹਨ, ਘਟਦੇ ਜਾ ਰਹੇ ਹਨ॥੧॥ਰਹਾਉ॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-148", gurmukhi = "ਨਾ ਹਉ ਜਤੀ ਸਤੀ. ਨਹੀ ਪੜਿਆ; ਮੂਰਖ ਮੁਗਧਾ ਜਨਮੁ ਭਇਆ ॥", transliteration = "naa hau jtee stee. nhee priaa; moorakh mugdhaa janam bhaiaa ||", translation = "I am not celibate, nor truthful, nor scholarly. I was born foolish and ignorant into this world.", hindi = "ना हउ जती सती. नही पड़िआ; मूरख मुगधा जनमु भइआ ॥", punjabi = "(ਹੇ ਪ੍ਰਭੂ!) ਨਾਹ ਮੈਂ ਜਤੀ ਹਾਂ, ਨਾਹ ਮੈਂ ਸਤੀ ਹਾਂ, ਨਾਹ ਹੀ ਮੈਂ ਪੜ੍ਹਿਆ ਹੋਇਆ ਹਾਂ, ਮੇਰਾ ਜੀਵਨ ਤਾਂ ਮੂਰਖ ਬੇਸਮਝਾਂ ਵਾਲਾ ਬਣਿਆ ਹੋਇਆ ਹੈ (ਭਾਵ, ਜਤ, ਸਤ ਅਤੇ ਵਿੱਦਿਆ ਇਸ ਤ੍ਰਿਸ਼ਨਾ ਦੀ ਅੱਗ ਅਤੇ ਮੋਹ ਦੇ ਚਿੱਕੜ ਵਿਚ ਡਿਗਣੋਂ ਬਚਾ ਨਹੀਂ ਸਕਦੇ। ਜੇ ਮਨੁੱਖ ਪ੍ਰਭੂ ਨੂੰ ਭੁਲਾ ਦੇਵੇ, ਤਾਂ ਜਤ ਸਤ ਵਿੱਦਿਆ ਦੇ ਹੁੰਦਿਆਂ ਭੀ ਮਨੁੱਖ ਦੀ ਜ਼ਿੰਦਗੀ ਮਹਾਂ ਮੂਰਖਾਂ ਵਾਲੀ ਹੁੰਦੀ ਹੈ)।", wordMeaning = "ਹਉ = ਮੈਂ। ਜਤੀ = ਕਾਮ-ਵਾਸਨਾ ਨੂੰ ਰੋਕਣ ਦਾ ਜਤਨ ਕਰਨ ਵਾਲਾ। ਸਤੀ = ਉੱਚੇ ਆਚਰਨ ਵਾਲਾ। ਮੁਗਧ = ਮੂਰਖ, ਬੇ-ਸਮਝ। ਜਨਮੁ = ਜੀਵਨ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-149", gurmukhi = "ਪ੍ਰਣਵਤਿ ਨਾਨਕ. ਤਿਨ ਕੀ ਸਰਣਾ; ਜਿਨ ਤੂ ਨਾਹੀ ਵੀਸਰਿਆ ॥੨॥੩॥", transliteration = "pranavat naanak. tin kee sarnaa; jin too naahee veesriaa ||2||3||", translation = "Prays Nanak, I seek the Sanctuary of those who have not forgotten You, O Lord! ||2||3||", hindi = "प्रणवति नानक. तिन की सरणा; जिन तू नाही वीसरिआ ॥२॥३॥", punjabi = "ਸੋ, ਨਾਨਕ ਬੇਨਤੀ ਕਰਦਾ ਹੈ (ਹੇ ਪ੍ਰਭੂ! ਮੈਨੂੰ) ਉਹਨਾਂ (ਗੁਰਮੁਖਾਂ) ਦੀ ਸਰਨ ਵਿਚ (ਰੱਖ), ਜਿਨ੍ਹਾਂ ਨੂੰ ਤੂੰ ਨਹੀਂ ਭੁੱਲਿਆ (ਜਿਨ੍ਹਾਂ ਨੂੰ ਤੇਰੀ ਯਾਦ ਨਹੀਂ ਭੁੱਲੀ) ॥੨॥੩॥", wordMeaning = "ਪ੍ਰਣਵਤਿ = ਬੇਨਤੀ ਕਰਦਾ ਹੈ॥੨॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-150", gurmukhi = "ਆਸਾ ਮਹਲਾ ੫ ॥", transliteration = "aasaa mahlaa 5 ||", translation = "Aasaa, Fifth Mehl:", hindi = "आसा महला ५ ॥", punjabi = "ਰਾਗ ਆਸਾ, ਪੰਜਵੀਂ ਪਾਤਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-151", gurmukhi = "ਭਈ ਪਰਾਪਤਿ; ਮਾਨੁਖ ਦੇਹੁਰੀਆ ॥", transliteration = "bhaee praapat; maanukh dehureeaa ||", translation = "This human body has been given to you.", hindi = "भई परापति; मानुख देहुरीआ ॥", punjabi = "(ਹੇ ਭਾਈ!) ਤੈਨੂੰ ਸੋਹਣਾ ਮਨੁੱਖਾ ਸਰੀਰ ਮਿਲਿਆ ਹੈ।", wordMeaning = "ਭਈ ਪਰਾਪਤਿ = ਮਿਲੀ ਹੈ। ਦੇਹੁਰੀਆ = ਸੋਹਣੀ ਦੇਹ, ਸੋਹਣਾ ਸਰੀਰ। ਮਾਨੁਖ ਦੇਹੁਰੀਆ = ਸੋਹਣਾ ਮਨੁੱਖਾ ਸਰੀਰ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-152", gurmukhi = "ਗੋਬਿੰਦ ਮਿਲਣ ਕੀ; ਇਹ ਤੇਰੀ ਬਰੀਆ ॥", transliteration = "gobind milan kee; ih teree breeaa ||", translation = "This is your chance to meet the Lord of the Universe.", hindi = "गोबिंद मिलण की; इह तेरी बरीआ ॥", punjabi = "ਪਰਮਾਤਮਾ ਨੂੰ ਮਿਲਣ ਦਾ ਤੇਰੇ ਲਈ ਇਹੀ ਮੌਕਾ ਹੈ।", wordMeaning = "ਬਰੀਆ = ਵਾਰੀ, ਮੌਕਾ, ਸਮਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-153", gurmukhi = "ਅਵਰਿ ਕਾਜ ਤੇਰੈ; ਕਿਤੈ ਨ ਕਾਮ ॥", transliteration = "avar kaaj terai; kitai na kaam ||", translation = "Nothing else will work.", hindi = "अवरि काज तेरै; कितै न काम ॥", punjabi = "(ਜੇ ਪ੍ਰਭੂ ਨੂੰ ਮਿਲਣ ਲਈ ਕੋਈ ਉੱਦਮ ਨਾਹ ਕੀਤਾ, ਤਾਂ) ਹੋਰ ਸਾਰੇ ਕੰਮ ਤੇਰੇ ਆਪਣੇ ਕਿਸੇ ਭੀ ਅਰਥ ਨਹੀਂ (ਤੇਰੀ ਜਿੰਦ ਨੂੰ ਕੋਈ ਲਾਭ ਨਹੀਂ ਅਪੜਾਣਗੇ)।", wordMeaning = "ਅਵਰਿ = ਹੋਰ ਸਾਰੇ {ਅਵਰੁ = ਇਕ-ਵਚਨ। ਅਵਰਿ = ਬਹੁ-ਵਚਨ}।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-154", gurmukhi = "ਮਿਲੁ ਸਾਧਸੰਗਤਿ; ਭਜੁ ਕੇਵਲ ਨਾਮ ॥੧॥", transliteration = "mil saadhasangat; bhaj keval naam ||1||", translation = "Join the Saadh Sangat, the Company of the Holy; vibrate and meditate on the Jewel of the Naam. ||1||", hindi = "मिलु साधसंगति; भजु केवल नाम ॥१॥", punjabi = "(ਇਸ ਵਾਸਤੇ) ਸਾਧ ਸੰਗਤਿ ਵਿਚ (ਭੀ) ਮਿਲ ਬੈਠਿਆ ਕਰ (ਸਾਧ ਸੰਗਤਿ ਵਿਚ ਬੈਠ ਕੇ ਭੀ) ਸਿਰਫ਼ ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ ਸਿਮਰਿਆ ਕਰ (ਸਾਧ ਸੰਗਤਿ ਵਿਚ ਬੈਠਣ ਦਾ ਭੀ ਤਦੋਂ ਹੀ ਲਾਭ ਹੈ, ਜੇ ਉਥੇ ਤੂੰ ਪਰਮਾਤਮਾ ਦੀ ਸਿਫ਼ਤਿ-ਸਲਾਹ ਵਿਚ ਜੁੜੇਂ) ॥੧॥", wordMeaning = "ਭਜੁ = ਯਾਦ ਕਰ, ਸਿਮਰ॥੧॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-155", gurmukhi = "ਸਰੰਜਾਮਿ ਲਾਗੁ; ਭਵਜਲ ਤਰਨ ਕੈ ॥", transliteration = "saranjaam laag; bhavajal taran kai ||", translation = "Make every effort to cross over this terrifying world-ocean.", hindi = "सरंजामि लागु; भवजल तरन कै ॥", punjabi = "(ਹੇ ਭਾਈ!) ਸੰਸਾਰ-ਸਮੁੰਦਰ ਤੋਂ ਪਾਰ ਲੰਘਣ ਦੇ (ਭੀ) ਆਹਰੇ ਲੱਗ।", wordMeaning = "ਸਰੰਜਾਮਿ = ਇੰਤਜ਼ਾਮ ਵਿਚ, ਆਹਰ ਵਿਚ। ਲਾਗੁ = ਲੱਗ। ਭਵਜਲ = ਸੰਸਾਰ-ਸਮੁੰਦਰ। ਤਰਨ ਕੈ ਸਰੰਜਾਮਿ = ਪਾਰ ਲੰਘਣ ਦੇ ਆਹਰ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-156", gurmukhi = "ਜਨਮੁ ਬ੍ਰਿਥਾ ਜਾਤ; ਰੰਗਿ ਮਾਇਆ ਕੈ ॥੧॥ ਰਹਾਉ ॥", transliteration = "janam brithaa jaat; rang maaiaa kai ||1|| rhaau ||", translation = "You are squandering this life uselessly in the love of Maya. ||1||Pause||", hindi = "जनमु ब्रिथा जात; रंगि माइआ कै ॥१॥ रहाउ ॥", punjabi = "(ਨਹੀਂ ਤਾਂ ਨਿਰੇ) ਮਾਇਆ ਦੇ ਪਿਆਰ ਵਿਚ ਮਨੁੱਖਾ ਜਨਮ ਵਿਅਰਥ ਜਾ ਰਿਹਾ ਹੈ ॥੧॥ ਰਹਾਉ ॥", wordMeaning = "ਬ੍ਰਿਥਾ = ਵਿਅਰਥ। ਜਾਤ = ਜਾ ਰਿਹਾ ਹੈ। ਰੰਗਿ = ਪਿਆਰ ਵਿਚ॥੧॥ਰਹਾਉ॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-157", gurmukhi = "ਜਪੁ ਤਪੁ ਸੰਜਮੁ ਧਰਮੁ ਨ ਕਮਾਇਆ ॥", transliteration = "jap tap sanjam dharam na kmaaiaa ||", translation = "I have not practiced meditation, self-discipline, self-restraint or righteous living.", hindi = "जपु तपु संजमु धरमु न कमाइआ ॥", punjabi = "(ਹੇ ਭਾਈ!) ਤੂੰ ਪ੍ਰਭੂ ਦਾ ਸਿਮਰਨ ਨਹੀਂ ਕਰਦਾ, (ਪ੍ਰਭੂ ਨੂੰ ਮਿਲਣ ਲਈ ਸੇਵਾ ਆਦਿਕ ਦਾ ਕੋਈ) ਉੱਦਮ ਨਹੀਂ ਕਰਦਾ, ਮਨ ਨੂੰ ਵਿਕਾਰਾਂ ਵਲੋਂ ਰੋਕਣ ਦਾ ਤੂੰ ਜਤਨ ਨਹੀਂ ਕਰਦਾ-ਤੂੰ (ਅਜੇਹਾ ਕੋਈ) ਧਰਮ ਨਹੀਂ ਕਮਾਂਦਾ।", wordMeaning = "ਜਪੁ = ਸਿਮਰਨ। ਤਪੁ = ਸੇਵਾ ਆਦਿਕ ਉੱਦਮ। ਸੰਜਮੁ = ਮਨ ਨੂੰ ਵਿਕਾਰਾਂ ਵਲੋਂ ਰੋਕਣ ਦਾ ਚੰਗੀ ਤਰ੍ਹਾਂ ਆਹਰ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-158", gurmukhi = "ਸੇਵਾ ਸਾਧ ਨ ਜਾਨਿਆ ਹਰਿ ਰਾਇਆ ॥", transliteration = "sevaa saadh na jaaniaa har raaiaa ||", translation = "I have not served the Holy; I have not acknowledged the Lord, my King.", hindi = "सेवा साध न जानिआ हरि राइआ ॥", punjabi = "ਨਾਹ ਤੂੰ ਗੁਰੂ ਦੀ ਸੇਵਾ ਕੀਤੀ, ਨਾਹ ਤੂੰ ਮਾਲਕ ਪ੍ਰਭੂ ਦਾ ਨਾਮ ਸਿਮਰਨ ਕੀਤਾ।", wordMeaning = "ਸਾਧੁ = ਗੁਰੂ। ਸੇਵਾ ਹਰਿ ਰਾਇਆ = ਮਾਲਕ ਪ੍ਰਭੂ ਦਾ ਸਿਮਰਨ।", startsAtMs = 0L, endsAtMs = 0L),
