    BaniLine(id = "rehras-sahib-252", gurmukhi = "ਕ੍ਰਿਪਾ ਦ੍ਰਿਸਟਿ, ਤਨ ਜਾਹਿ ਨਿਹਰਿਹੋ ॥", transliteration = "kripaa drisat, tan jaah nihriho ||", translation = "", hindi = "क्रिपा द्रिसटि, तन जाहि निहरिहो ॥", punjabi = "(ਤੁਸੀਂ) ਜਿਸ ਨੂੰ ਕ੍ਰਿਪਾ ਦ੍ਰਿਸ਼ਟੀ ਨਾਲ ਵੇਖਦੇ ਹੋ,", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-253", gurmukhi = "ਤਾ ਕੇ ਤਾਪ, ਤਨਕ ਮੋ ਹਰਿਹੋ ॥", transliteration = "taa ke taap, tanak mo hriho ||", translation = "Upon whomsoever Thou dost cast Thy favourable glance, they are absolved of sins instantly", hindi = "ता के ताप, तनक मो हरिहो ॥", punjabi = "ਉਨ੍ਹਾਂ ਦੇ (ਸਾਰੇ) ਦੁਖ ਛਿਣ ਵਿਚ ਹਰੇ ਜਾਂਦੇ ਹਨ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-254", gurmukhi = "ਰਿੱਧਿ ਸਿੱਧਿ, ਘਰ ਮੋ ਸਭ ਹੋਈ ॥", transliteration = "riddh siddh, ghar mo sabh hoee ||", translation = "They have all the worldly and spiritual pleasures in their homes", hindi = "रिध्धि सिध्धि, घर मो सभ होई ॥", punjabi = "(ਉਨ੍ਹਾਂ ਦੇ) ਘਰ ਵਿਚ ਸਭ ਰਿਧੀਆਂ ਅਤੇ ਸਿਧੀਆਂ ਹੋ ਜਾਂਦੀਆਂ ਹਨ", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-255", gurmukhi = "ਦੁਸ਼ਟ ਛਾਹ, ਛ੍ਵੈ ਸਕੈ ਨ ਕੋਈ ॥੩੯੯॥", transliteration = "dushat chhaah, chhvai skai na koee ||399||", translation = "None of th enemies can even touch their shadow.399.", hindi = "दुशट छाह, छ्वै सकै न कोई ॥३९९॥", punjabi = "ਅਤੇ ਕੋਈ ਦੁਸ਼ਟ (ਦੁਸ਼ਮਨ) (ਉਨ੍ਹਾਂ ਦੀ) ਪਰਛਾਈ ਨੂੰ ਵੀ ਛੋਹ ਨਹੀਂ ਸਕਦਾ ॥੩੯੯॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-256", gurmukhi = "ਏਕ ਬਾਰ, ਜਿਨ ਤੁਮੈ ਸੰਭਾਰਾ ॥", transliteration = "ek baar, jin tumai sambhaaraa ||", translation = "", hindi = "एक बार, जिन तुमै संभारा ॥", punjabi = "(ਹੇ ਪਰਮ ਸੱਤਾ!) ਜਿਸ ਨੇ ਇਕ ਵਾਰ ਤੁਹਾਨੂੰ ਯਾਦ ਕਰ ਲਿਆ,", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L)
