    BaniLine(id = "rehras-sahib-265", gurmukhi = "ਪਾਂਇ ਗਹੇ ਜਬ ਤੇ ਤੁਮਰੇ ਤਬ ਤੇ ਕੋਊ ਆਂਖ ਤਰੇ ਨਹੀਂ ਆਨ︀ਯੋ ॥", transliteration = "paani ghe jab te tumre tab te kooo aankh tre nheen aan︀yo ||", translation = "O God! the day when I caught hold of your feet, I do not bring anyone else under my sight", hindi = "पांइ गहे जब ते तुमरे तब ते कोऊ आंख तरे नहीं आन︀यो ॥", punjabi = "ਜਦ ਤੋਂ ਤੁਹਾਡੇ ਚਰਨ ਫੜੇ ਹਨ ਤਦ ਤੋਂ ਮੈਂ (ਹੋਰ) ਕਿਸੇ ਨੂੰ ਅੱਖਾਂ ਹੇਠਾਂ ਨਹੀਂ ਲਿਆਉਂਦਾ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-266", gurmukhi = "ਰਾਮ ਰਹੀਮ ਪੁਰਾਨ ਕੁਰਾਨ; ਅਨੇਕ ਕਹੈਂ, ਮਤ ਏਕ ਨ ਮਾਨ︀ਯੋ ॥", transliteration = "raam rheem puraan kuraan; anek khain, mat ek na maan︀yo ||", translation = "None other is liked by me now   the Puranas and the Quran try to know Thee by the names of Ram and Rahim and talk about you through several stories,", hindi = "राम रहीम पुरान कुरान; अनेक कहैं, मत एक न मान︀यो ॥", punjabi = "ਰਾਮ, ਰਹੀਮ, ਪੁਰਾਨ ਅਤੇ ਕੁਰਾਨ ਨੇ ਅਨੇਕਾਂ ਮੱਤ ਕਹੇ ਗਏ ਹਨ। (ਪਰ ਮੈਂ ਕਿਸੇ) ਇਕ ਨੂੰ ਵੀ ਨਹੀਂ ਮੰਨਦਾ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
