    BaniLine(id = "rehras-sahib-270", gurmukhi = "ਸਗਲ ਦੁਆਰ ਕਉ ਛਾਡਿ ਕੈ; ਗਹਿਓ ਤੁਹਾਰੋ ਦੁਆਰ ॥", transliteration = "sagal duaar kau chhaad kai; ghio tuhaaro duaar ||", translation = "O Lord! I have forsaken all other doors and have caught hold of only Thy door. O Lord! Thou has caught hold of my arm", hindi = "सगल दुआर कउ छाडि कै; गहिओ तुहारो दुआर ॥", punjabi = "ਸਾਰੇ ਦਰਾਂ ਨੂੰ ਛੱਡ ਕੇ, ਤੁਹਾਡਾ ਦਰ ਫੜਿਆ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-271", gurmukhi = "ਬਾਂਹਿ ਗਹੇ ਕੀ ਲਾਜ ਅਸ; ਗੋਬਿੰਦ ਦਾਸ ਤੁਹਾਰ ॥੮੬੪॥", transliteration = "baanh ghe kee laaj as; gobind daas tuhaar ||864||", translation = "I, Govind, am Thy serf, kindly take (care of me and) protect my honour.864.", hindi = "बांहि गहे की लाज अस; गोबिंद दास तुहार ॥८६४॥", punjabi = "ਤੁਹਾਨੂੰ ਬਾਂਹ ਫੜੇ ਦੀ ਲਾਜ ਹੈ, ਗੋਬਿੰਦ ਤੁਹਾਡਾ ਦਾਸ ਹਾਂ ॥੮੬੪॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-272", gurmukhi = "ਰਾਮਕਲੀ ਮਹਲਾ ੩ ਅਨੰਦੁ ॥", transliteration = "raamaklee mahlaa 3 anand ||", translation = "Raamkalee, Third Mehl, Anand ~ The Song Of Bliss:", hindi = "रामकली महला ३ अनंदु ॥", punjabi = "ਰਾਗ ਰਾਮਕਲੀ ਵਿੱਚ ਗੁਰੂ ਅਮਰਦਾਸ ਜੀ ਦੀ ਬਾਣੀ 'ਅਨੰਦ'।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-273", gurmukhi = "ੴ ਸਤਿਗੁਰ ਪ੍ਰਸਾਦਿ ॥", transliteration = "ik oankar stigur prasaad ||", translation = "One Universal Creator God. By The Grace Of The True Guru:", hindi = "एकओंकार सतिगुर प्रसादि ॥", punjabi = "ਅਕਾਲ ਪੁਰਖ ਇੱਕ ਹੈ ਅਤੇ ਸਤਿਗੁਰੂ ਦੀ ਕਿਰਪਾ ਨਾਲ ਮਿਲਦਾ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-274", gurmukhi = "ਅਨੰਦੁ ਭਇਆ ਮੇਰੀ ਮਾਏ; ਸਤਿਗੁਰੂ. ਮੈ ਪਾਇਆ ॥", transliteration = "anand bhaiaa meree maae; stiguroo. mai paaiaa ||", translation = "I am in ecstasy, O my mother, for I have found my True Guru.", hindi = "अनंदु भइआ मेरी माए; सतिगुरू. मै पाइआ ॥", punjabi = "ਹੇ ਭਾਈ ਮਾਂ! (ਮੇਰੇ ਅੰਦਰ) ਪੂਰਨ ਖਿੜਾਉ ਪੈਦਾ ਹੋ ਗਿਆ ਹੈ (ਕਿਉਂਕਿ) ਮੈਨੂੰ ਗੁਰੂ ਮਿਲ ਪਿਆ ਹੈ।", wordMeaning = "ਅਨੰਦੁ = ਪੂਰਨ ਖਿੜਾਉ। ਪਾਇਆ = ਪ੍ਰਾਪਤ ਕਰ ਲਿਆ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-275", gurmukhi = "ਸਤਿਗੁਰੁ. ਤ ਪਾਇਆ ਸਹਜ ਸੇਤੀ; ਮਨਿ ਵਜੀਆ ਵਾਧਾਈਆ ॥", transliteration = "satigur. ta paaiaa sahaj setee; man vjeeaa vaadhaaeeaa ||", translation = "I have found the True Guru, with intuitive ease, and my mind vibrates with the music of bliss.", hindi = "सतिगुरु. त पाइआ सहज सेती; मनि वजीआ वाधाईआ ॥", punjabi = "ਮੈਨੂੰ ਗੁਰੂ ਮਿਲਿਆ ਹੈ, ਤੇ ਨਾਲ ਹੀ ਅਡੋਲ ਅਵਸਥਾ ਭੀ ਪ੍ਰਾਪਤ ਹੋ ਗਈ ਹੈ (ਭਾਵ, ਗੁਰੂ ਦੇ ਮਿਲਣ ਨਾਲ ਮੇਰਾ ਮਨ ਡੋਲਣੋਂ ਹਟ ਗਿਆ ਹੈ); ਮੇਰੇ ਮਨ ਵਿਚ (ਮਾਨੋ) ਖ਼ੁਸ਼ੀ ਦੇ ਵਾਜੇ ਵੱਜ ਪਏ ਹਨ,", wordMeaning = "ਸਹਜ = ਅਡੋਲ ਅਵਸਥਾ। ਸਹਜ ਸੇਤੀ = ਅਡੋਲ ਅਵਸਥਾ ਦੇ ਨਾਲ। ਮਨਿ = ਮਨ ਵਿਚ। ਵਾਧਾਈ = ਚੜ੍ਹਦੀ ਕਲਾ, ਉਤਸ਼ਾਹ ਪੈਦਾ ਕਰਨ ਵਾਲਾ ਗੀਤ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-276", gurmukhi = "ਰਾਗ ਰਤਨ ਪਰਵਾਰ ਪਰੀਆ; ਸਬਦ ਗਾਵਣ ਆਈਆ ॥", transliteration = "raag ratan parvaar preeaa; sabad gaavan aaeeaa ||", translation = "The jewelled melodies and their related celestial harmonies have come to sing the Word of the Shabad.", hindi = "राग रतन परवार परीआ; सबद गावण आईआ ॥", punjabi = "ਸੋਹਣੇ ਰਾਗ ਆਪਣੇ ਪਰਵਾਰ ਤੇ ਰਾਣੀਆਂ ਸਮੇਤ (ਮੇਰੇ ਮਨ ਵਿਚ, ਮਾਨੋ,) ਪ੍ਰਭੂ ਦੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਦੇ ਗੀਤ ਗਾਵਣ ਆ ਗਏ ਹਨ।", wordMeaning = "ਪਰੀਆ = ਰਾਗਾਂ ਦੀਆਂ ਪਰੀਆਂ, ਰਾਗਣੀਆਂ। ਰਾਗ ਰਤਨ = ਸੋਹਣੇ ਰਾਗ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-277", gurmukhi = "ਸਬਦੋ ਤ ਗਾਵਹੁ ਹਰੀ ਕੇਰਾ; ਮਨਿ ਜਿਨੀ ਵਸਾਇਆ ॥", transliteration = "sabdo ta gaavah hree keraa; man jinee vsaaiaa ||", translation = "The Lord dwells within the minds of those who sing the Shabad.", hindi = "सबदो त गावहु हरी केरा; मनि जिनी वसाइआ ॥", punjabi = "(ਤੁਸੀ ਭੀ) ਪ੍ਰਭੂ ਦੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਦਾ ਗੀਤ ਗਾਵੋ। ਜਿਨ੍ਹਾਂ ਜਿਨ੍ਹਾਂ ਨੇ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਦਾ ਸ਼ਬਦ ਮਨ ਵਿਚ ਵਸਾਇਆ ਹੈ (ਉਹਨਾਂ ਦੇ ਅੰਦਰ ਪੂਰਨ ਖਿੜਾਉ ਪੈਦਾ ਹੋ ਜਾਂਦਾ ਹੈ)।", wordMeaning = "ਕੇਰਾ = ਦਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-278", gurmukhi = "ਕਹੈ ਨਾਨਕੁ. ਅਨੰਦੁ ਹੋਆ; ਸਤਿਗੁਰੂ ਮੈ ਪਾਇਆ ॥੧॥", transliteration = "kahai naanak. anand hoaa; stiguroo mai paaiaa ||1||", translation = "Says Nanak, I am in ecstasy, for I have found my True Guru. ||1||", hindi = "कहै नानकु. अनंदु होआ; सतिगुरू मै पाइआ ॥१॥", punjabi = "ਨਾਨਕ ਆਖਦਾ ਹੈ (ਮੇਰੇ ਅੰਦਰ ਭੀ) ਆਨੰਦ ਬਣ ਗਿਆ ਹੈ (ਕਿਉਂਕਿ) ਮੈਨੂੰ ਸਤਿਗੁਰੂ ਮਿਲ ਪਿਆ ਹੈ ॥੧॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-279", gurmukhi = "ਏ ਮਨ ਮੇਰਿਆ; ਤੂ ਸਦਾ ਰਹੁ ਹਰਿ ਨਾਲੇ ॥", transliteration = "e man meriaa; too sdaa rah har naale ||", translation = "O my mind, remain always with the Lord.", hindi = "ए मन मेरिआ; तू सदा रहु हरि नाले ॥", punjabi = "ਹੇ ਮੇਰੇ ਮਨ! ਤੂੰ ਸਦਾ ਪ੍ਰਭੂ ਦੇ ਨਾਲ (ਜੁੜਿਆ) ਰਹੁ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-280", gurmukhi = "ਹਰਿ ਨਾਲਿ ਰਹੁ ਤੂ ਮੰਨ ਮੇਰੇ; ਦੂਖ ਸਭਿ ਵਿਸਾਰਣਾ ॥", transliteration = "har naal rah too mann mere; dookh sabh visaarnaa ||", translation = "Remain always with the Lord, O my mind, and all sufferings will be forgotten.", hindi = "हरि नालि रहु तू मंन मेरे; दूख सभि विसारणा ॥", punjabi = "ਹੇ ਮੇਰੇ ਮਨ! ਤੂੰ ਸਦਾ ਪ੍ਰਭੂ ਨੂੰ ਯਾਦ ਰੱਖ।", wordMeaning = "ਮੰਨ ਮੇਰੇ = ਹੇ ਮੇਰੇ ਮਨ! ਸਭਿ = ਸਾਰੇ। ਵਿਸਾਰਣਾ = ਦੂਰ ਕਰਨ ਵਾਲਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-281", gurmukhi = "ਅੰਗੀਕਾਰੁ ਓਹੁ ਕਰੇ ਤੇਰਾ; ਕਾਰਜ ਸਭਿ ਸਵਾਰਣਾ ॥", transliteration = "angeekaar oh kre teraa; kaaraj sabh svaarnaa ||", translation = "He will accept You as His own, and all your affairs will be perfectly arranged.", hindi = "अंगीकारु ओहु करे तेरा; कारज सभि सवारणा ॥", punjabi = "ਉਹ ਪ੍ਰਭੂ ਸਾਰੇ ਦੁੱਖ ਦੂਰ ਕਰਨ ਵਾਲਾ ਹੈ।", wordMeaning = "ਅੰਗੀਕਾਰੁ = ਪੱਖ, ਸਹਾਇਤਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-282", gurmukhi = "ਸਭਨਾ ਗਲਾ ਸਮਰਥੁ ਸੁਆਮੀ; ਸੋ. ਕਿਉ ਮਨਹੁ ਵਿਸਾਰੇ ॥", transliteration = "sabhnaa glaa samarath suaamee; so. kiu manah visaare ||", translation = "Our Lord and Master is all-powerful to do all things, so why forget Him from your mind?", hindi = "सभना गला समरथु सुआमी; सो. किउ मनहु विसारे ॥", punjabi = "ਉਹ ਸਦਾ ਤੇਰੀ ਸਹਾਇਤਾ ਕਰਨ ਵਾਲਾ ਹੈ ਤੇਰੇ ਸਾਰੇ ਕੰਮ ਸਿਰੇ ਚਾੜ੍ਹਨ ਦੇ ਸਮਰੱਥ ਹੈ।", wordMeaning = "ਸਮਰਥੁ = ਕਰਨ-ਯੋਗ। ਮਨਹੁ = ਮਨ ਤੋਂ। ਵਿਸਰੇ = ਵਿਸਰਦਾ ਹੈਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-283", gurmukhi = "ਕਹੈ ਨਾਨਕੁ. ਮੰਨ ਮੇਰੇ; ਸਦਾ ਰਹੁ ਹਰਿ ਨਾਲੇ ॥੨॥", transliteration = "kahai naanak. mann mere; sdaa rah har naale ||2||", translation = "Says Nanak, O my mind, remain always with the Lord. ||2||", hindi = "कहै नानकु. मंन मेरे; सदा रहु हरि नाले ॥२॥", punjabi = "ਉਸ ਮਾਲਕ ਨੂੰ ਕਿਉਂ (ਆਪਣੇ) ਮਨ ਤੋਂ ਭੁਲਾਂਦਾ ਹੈਂ ਜੋ ਸਾਰੇ ਕੰਮ ਕਰਨ-ਜੋਗਾ ਹੈ? ਨਾਨਕ ਆਖਦਾ ਹੈ ਕਿ ਹੇ ਮੇਰੇ ਮਨ! ਤੂੰ ਸਦਾ ਪ੍ਰਭੂ ਦੇ ਚਰਨਾਂ ਵਿਚ ਜੁੜਿਆ ਰਹੁ ॥੨॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-284", gurmukhi = "ਸਾਚੇ ਸਾਹਿਬਾ; ਕਿਆ ਨਾਹੀ. ਘਰਿ ਤੇਰੈ ॥", transliteration = "saache saahibaa; kiaa naahee. ghar terai ||", translation = "O my True Lord and Master, what is there which is not in Your celestial home?", hindi = "साचे साहिबा; किआ नाही. घरि तेरै ॥", punjabi = "ਹੇ ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲੇ ਮਾਲਕ (-ਪ੍ਰਭੂ)! (ਮੈਂ ਤੇਰੇ ਦਰ ਤੋਂ ਮਨ ਦਾ ਆਨੰਦ ਮੰਗਦਾ ਹਾਂ, ਪਰ) ਤੇਰੇ ਘਰ ਵਿਚ ਕੇਹੜੀ ਚੀਜ਼ ਨਹੀਂ ਹੈ?", wordMeaning = "ਘਰਿ ਤੇਰੈ = ਤੇਰੇ ਘਰ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-285", gurmukhi = "ਘਰਿ ਤ ਤੇਰੈ. ਸਭੁ ਕਿਛੁ ਹੈ; ਜਿਸੁ ਦੇਹਿ ਸੁ ਪਾਵਏ ॥", transliteration = "ghar ta terai. sabh kichh hai; jis deh su paavae ||", translation = "Everything is in Your home; they receive, unto whom You give.", hindi = "घरि त तेरै. सभु किछु है; जिसु देहि सु पावए ॥", punjabi = "ਤੇਰੇ ਘਰ ਵਿਚ ਤਾਂ ਹਰੇਕ ਚੀਜ਼ ਮੌਜੂਦ ਹੈ, ਉਹੀ ਮਨੁੱਖ ਪ੍ਰਾਪਤ ਕਰਦਾ ਹੈ ਜਿਸ ਨੂੰ ਤੂੰ ਆਪ ਦੇਂਦਾ ਹੈਂ।", wordMeaning = "ਤ = ਤਾਂ। ਸਭੁ ਕਿਛੁ = ਹਰੇਕ ਚੀਜ਼। ਦੇਹਿ = ਤੂੰ ਦੇਂਦਾ ਹੈਂ। ਸੁ = ਉਹ ਮਨੁੱਖ। ਪਾਵਏ = ਪਾਵੈ, ਪਾ ਲੈਂਦਾ ਹੈ, ਹਾਸਲ ਕਰਦਾ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-286", gurmukhi = "ਸਦਾ ਸਿਫਤਿ ਸਲਾਹ ਤੇਰੀ; ਨਾਮੁ ਮਨਿ ਵਸਾਵਏ ॥", transliteration = "sadaa siphat slaah teree; naam man vsaavae ||", translation = "Constantly singing Your Praises and Glories, Your Name is enshrined in the mind.", hindi = "सदा सिफति सलाह तेरी; नामु मनि वसावए ॥", punjabi = "(ਫਿਰ, ਉਹ ਮਨੁੱਖ) ਤੇਰਾ ਨਾਮ ਤੇ ਤੇਰੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ (ਆਪਣੇ) ਮਨ ਵਿਚ ਵਸਾਂਦਾ ਹੈ (ਜਿਸ ਦੀ ਬਰਕਤਿ ਨਾਲ ਉਸ ਦੇ ਅੰਦਰ ਆਨੰਦ ਪੈਦਾ ਹੋ ਜਾਂਦਾ ਹੈ)।", wordMeaning = "ਸਿਫਤਿ ਸਲਾਹ = ਵਡਿਆਈ। ਮਨਿ = ਮਨ ਵਿਚ। ਵਸਾਵਏ = ਵਸਾਵੈ, ਵਸਾਂਦਾ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-287", gurmukhi = "ਨਾਮੁ ਜਿਨ ਕੈ ਮਨਿ ਵਸਿਆ; ਵਾਜੇ ਸਬਦ ਘਨੇਰੇ ॥", transliteration = "naam jin kai man vsiaa; vaaje sabad ghnere ||", translation = "The divine melody of the Shabad vibrates for those, within whose minds the Naam abides.", hindi = "नामु जिन कै मनि वसिआ; वाजे सबद घनेरे ॥", punjabi = "ਜਿਨ੍ਹਾਂ ਬੰਦਿਆਂ ਦੇ ਮਨ ਵਿਚ (ਤੇਰਾ) ਨਾਮ ਵੱਸਦਾ ਹੈ (ਉਹਨਾਂ ਦੇ ਅੰਦਰ, ਮਾਨੋ,) ਬੇਅੰਤ ਸਾਜ਼ਾਂ ਦੀਆਂ (ਮਿਲਵੀਆਂ) ਸੁਰਾਂ ਵੱਜਣ ਲੱਗ ਪੈਂਦੀਆਂ ਹਨ (ਭਾਵ, ਉਹਨਾਂ ਦੇ ਮਨ ਵਿਚ ਉਹ ਖ਼ੁਸ਼ੀ ਤੇ ਚਾਉ ਪੈਦਾ ਹੁੰਦਾ ਹੈ ਜੋ ਕਈ ਸਾਜ਼ਾਂ ਦਾ ਮਿਲਵਾਂ ਰਾਗ ਸੁਣ ਕੇ ਪੈਦਾ ਹੁੰਦਾ ਹੈ)।", wordMeaning = "ਜਿਨ ਕੈ ਮਨਿ = ਜਿਨ੍ਹਾਂ ਦੇ ਮਨ ਵਿਚ। ਵਾਜੇ = ਵੱਜਦੇ ਹਨ। ਸਬਦ = ਸਾਜਾਂ ਦੇ ਆਵਾਜ਼, ਰਾਗਾਂ ਦੀਆਂ ਸੁਰਾਂ। ਘਨੇਰੇ = ਬੇਅੰਤ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-288", gurmukhi = "ਕਹੈ ਨਾਨਕੁ. ਸਚੇ ਸਾਹਿਬ; ਕਿਆ ਨਾਹੀ. ਘਰਿ ਤੇਰੈ ॥੩॥", transliteration = "kahai naanak. sche saahib; kiaa naahee. ghar terai ||3||", translation = "Says Nanak, O my True Lord and Master, what is there which is not in Your home? ||3||", hindi = "कहै नानकु. सचे साहिब; किआ नाही. घरि तेरै ॥३॥", punjabi = "ਨਾਨਕ ਆਖਦਾ ਹੈ ਕਿ ਹੇ ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲੇ ਮਾਲਕ! ਤੇਰੇ ਘਰ ਵਿਚ ਕਿਸੇ ਸ਼ੈ ਦਾ ਘਾਟਾ ਨਹੀਂ ਹੈ (ਤੇ, ਮੈਂ ਤੇਰੇ ਦਰ ਤੋਂ ਆਨੰਦ ਦਾ ਦਾਨ ਮੰਗਦਾ ਹਾਂ) ॥੩॥", wordMeaning = "ਸਚੇ = ਹੇ ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲੇ! ॥੩॥", startsAtMs = 0L, endsAtMs = 0L)
)

