    BaniLine(id = "rehras-sahib-290", gurmukhi = "ਸਾਚੁ ਨਾਮੁ ਅਧਾਰੁ ਮੇਰਾ; ਜਿਨਿ ਭੁਖਾ ਸਭਿ ਗਵਾਈਆ ॥", transliteration = "saach naam adhaar meraa; jin bhukhaa sabh gvaaeeaa ||", translation = "The True Name is my only support; it satisfies all hunger.", hindi = "साचु नामु अधारु मेरा; जिनि भुखा सभि गवाईआ ॥", punjabi = "ਉਹ ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ ਨਾਮ ਮੇਰੀ ਜ਼ਿੰਦਗੀ ਦਾ ਆਸਰਾ ਬਣ ਗਿਆ) ਹੈ, ਜਿਸ (ਹਰਿ-ਨਾਮ) ਨੇ ਮੇਰੇ ਸਾਰੇ ਲਾਲਚ ਦੂਰ ਕਰ ਦਿੱਤੇ ਹਨ।", wordMeaning = "ਜਿਨਿ = ਜਿਸ (ਨਾਮ) ਨੇ। ਭੁਖ = ਲਾਲਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-291", gurmukhi = "ਕਰਿ ਸਾਂਤਿ ਸੁਖ ਮਨਿ ਆਇ ਵਸਿਆ; ਜਿਨਿ ਇਛਾ ਸਭਿ ਪੁਜਾਈਆ ॥", transliteration = "kar saant sukh man aai vsiaa; jin ichhaa sabh pujaaeeaa ||", translation = "It has brought peace and tranquility to my mind; it has fulfilled all my desires.", hindi = "करि सांति सुख मनि आइ वसिआ; जिनि इछा सभि पुजाईआ ॥", punjabi = "ਜੋ ਹਰਿ-ਨਾਮ (ਮੇਰੇ ਅੰਦਰ) ਸ਼ਾਂਤੀ ਤੇ ਸੁਖ ਪੈਦਾ ਕਰਕੇ ਮੇਰੇ ਮਨ ਵਿਚ ਆ ਟਿਕਿਆ ਹੈ, ਜਿਸ (ਹਰਿ-ਨਾਮ) ਨੇ ਮੇਰੇ ਮਨ ਦੀਆਂ ਸਾਰੀਆਂ ਕਾਮਨਾਂ ਪੂਰੀਆਂ ਕਰ ਦਿੱਤੀਆਂ ਹਨ।", wordMeaning = "ਕਰਿ = (ਪੈਦਾ) ਕਰ ਕੇ। ਮਨਿ = ਮਨ ਵਿਚ। ਇਛਾ = ਮਨ ਦੀਆਂ ਕਾਮਨਾਂ। ਸਭਿ = ਸਾਰੀਆਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-292", gurmukhi = "ਸਦਾ ਕੁਰਬਾਣੁ ਕੀਤਾ ਗੁਰੂ ਵਿਟਹੁ; ਜਿਸ ਦੀਆ ਏਹਿ ਵਡਿਆਈਆ ॥", transliteration = "sadaa kurbaan keetaa guroo vitah; jis deeaa eh vdiaaeeaa ||", translation = "I am forever a sacrifice to the Guru, who possesses such glorious greatness.", hindi = "सदा कुरबाणु कीता गुरू विटहु; जिस दीआ एहि वडिआईआ ॥", punjabi = "ਮੈਂ (ਆਪਣੇ ਆਪ ਨੂੰ) ਆਪਣੇ ਗੁਰੂ ਤੋਂ ਸਦਕੇ ਕਰਦਾ ਹਾਂ, ਕਿਉਂਕਿ ਇਹ ਸਾਰੀਆਂ ਬਰਕਤਾਂ ਗੁਰੂ ਦੀਆਂ ਹੀ ਹਨ।", wordMeaning = "ਕੁਰਬਾਣੁ = ਸਦਕੇ। ਵਿਟਹੁ = ਤੋਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-293", gurmukhi = "ਕਹੈ ਨਾਨਕੁ. ਸੁਣਹੁ ਸੰਤਹੁ; ਸਬਦਿ ਧਰਹੁ ਪਿਆਰੋ ॥", transliteration = "kahai naanak. sunah santah; sabad dharah piaaro ||", translation = "Says Nanak, listen, O Saints; enshrine love for the Shabad.", hindi = "कहै नानकु. सुणहु संतहु; सबदि धरहु पिआरो ॥", punjabi = "ਨਾਨਕ ਆਖਦਾ ਹੈ ਕਿ ਹੇ ਸੰਤ ਜਨੋ! (ਗੁਰੂ ਦਾ ਸ਼ਬਦ) ਸੁਣੋ, ਗੁਰੂ ਦੇ ਸ਼ਬਦ ਵਿਚ ਪਿਆਰ ਬਣਾਓ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-294", gurmukhi = "ਸਾਚਾ ਨਾਮੁ; ਮੇਰਾ ਆਧਾਰੋ ॥੪॥", transliteration = "saachaa naam; meraa aadhaaro ||4||", translation = "The True Name is my only support. ||4||", hindi = "साचा नामु; मेरा आधारो ॥४॥", punjabi = "(ਸਤਿਗੁਰੂ ਦੀ ਮੇਹਰ ਨਾਲ ਹੀ ਪ੍ਰਭੂ ਦਾ) ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ ਨਾਮ ਮੇਰੀ ਜ਼ਿੰਦਗੀ ਦਾ ਆਸਰਾ (ਬਣ ਗਿਆ) ਹੈ ॥੪॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-295", gurmukhi = "ਵਾਜੇ ਪੰਚ ਸਬਦ; ਤਿਤੁ ਘਰਿ ਸਭਾਗੈ ॥", transliteration = "vaaje panch sabad; tit ghar sbhaagai ||", translation = "The Panch Shabad, the five primal sounds, vibrate in that blessed house.", hindi = "वाजे पंच सबद; तितु घरि सभागै ॥", punjabi = "ਉਸ ਭਾਗਾਂ ਵਾਲੇ (ਹਿਰਦੇ-) ਘਰ ਵਿਚ (ਮਾਨੋ) ਪੰਜ ਕਿਸਮਾਂ ਦੇ ਸਾਜ਼ਾਂ ਦੀਆਂ ਮਿਲਵੀਆਂ ਸੁਰਾਂ ਵੱਜ ਪੈਂਦੀਆਂ ਹਨ,", wordMeaning = "ਵਾਜੇ = ਵੱਜਦੇ ਹਨ, ਵੱਜੇ ਹਨ। ਪੰਚ ਸਬਦ = ਪੰਜ ਕਿਸਮਾਂ ਦੇ ਸਾਜ਼ਾਂ ਦੀਆਂ ਮਿਲਵੀਆਂ ਸੁਰਾਂ। ਤਿਤੁ = ਉਸ ਵਿਚ। ਤਿਤੁ ਘਰਿ = ਉਸ ਹਿਰਦੇ-ਘਰਿ ਵਿਚ। ਸਭਾਗੈ = ਭਾਗਾਂ ਵਾਲੇ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-296", gurmukhi = "ਘਰਿ ਸਭਾਗੈ ਸਬਦ ਵਾਜੇ; ਕਲਾ ਜਿਤੁ ਘਰਿ ਧਾਰੀਆ ॥", transliteration = "ghar sbhaagai sabad vaaje; klaa jit ghar dhaareeaa ||", translation = "In that blessed house, the Shabad vibrates; He infuses His almighty power into it.", hindi = "घरि सभागै सबद वाजे; कला जितु घरि धारीआ ॥", punjabi = "ਜਿਸ (ਹਿਰਦੇ-) ਘਰ ਵਿਚ (ਹੇ ਪ੍ਰਭੂ! ਤੂੰ) ਸੱਤਿਆ ਪਾਈ ਹੈ, ਉਸ ਭਾਗਾਂ ਵਾਲੇ (ਹਿਰਦੇ-) ਘਰ ਵਿਚ (ਮਾਨੋ) ਪੰਜ ਕਿਸਮਾਂ ਦੇ ਸਾਜ਼ਾਂ ਦੀਆਂ ਮਿਲਵੀਆਂ ਸੁਰਾਂ ਵੱਜ ਪੈਂਦੀਆਂ ਹਨ (ਭਾਵ, ਉਸ ਹਿਰਦੇ ਵਿਚ ਪੂਰਨ ਆਨੰਦ ਬਣ ਜਾਂਦਾ ਹੈ),", wordMeaning = "ਤਿਤੁ ਸਭਾਗੈ ਘਰਿ = ਉਸ ਭਾਗਾਂ ਵਾਲੇ (ਹਿਰਦੇ-) ਘਰ ਵਿਚ। ਕਲਾ = ਸੱਤਿਆ। ਜਿਤੁ ਘਰਿ = ਜਿਸ ਘਰ ਵਿਚ। ਧਾਰੀਆ = ਤੂੰ ਪਾਈ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-297", gurmukhi = "ਪੰਚ ਦੂਤ ਤੁਧੁ ਵਸਿ ਕੀਤੇ; ਕਾਲੁ ਕੰਟਕੁ ਮਾਰਿਆ ॥", transliteration = "panch doot tudh vas keete; kaal kantak maariaa ||", translation = "Through You, we subdue the five demons of desire, and slay Death, the torturer.", hindi = "पंच दूत तुधु वसि कीते; कालु कंटकु मारिआ ॥", punjabi = "(ਹੇ ਪ੍ਰਭੂ!) ਉਸ ਦੇ ਪੰਜੇ ਕਾਮਾਦਿਕ ਵੈਰੀ ਤੂੰ ਕਾਬੂ ਵਿਚ ਕਰ ਦੇਂਦਾ ਹੈਂ, ਤੇ ਡਰਾਣ ਵਾਲਾ ਕਾਲ (ਭਾਵ, ਮੌਤ ਦਾ ਡਰ) ਦੂਰ ਕਰ ਦੇਂਦਾ ਹੈਂ।", wordMeaning = "ਪੰਚ ਦੂਤ = ਕਾਮਾਦਿਕ ਪੰਜ ਵੈਰੀ। ਕੰਟਕੁ = ਕੰਡਾ। ਕੰਟਕੁ ਕਾਲੁ = ਡਰਾਉਣਾ ਕਾਲ, ਮੌਤ ਦਾ ਡਰ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-298", gurmukhi = "ਧੁਰਿ ਕਰਮਿ ਪਾਇਆ ਤੁਧੁ. ਜਿਨ ਕਉ; ਸਿ. ਨਾਮਿ ਹਰਿ ਕੈ ਲਾਗੇ ॥", transliteration = "dhur karam paaiaa tudh. jin kau; si. naam har kai laage ||", translation = "Those who have such pre-ordained destiny are attached to the Lord's Name.", hindi = "धुरि करमि पाइआ तुधु. जिन कउ; सि. नामि हरि कै लागे ॥", punjabi = "ਪਰ ਸਿਰਫ਼ ਉਹੀ ਮਨੁੱਖ ਹਰਿ-ਨਾਮ ਵਿਚ ਜੁੜਦੇ ਹਨ ਜਿਨ੍ਹਾਂ ਦੇ ਭਾਗਾਂ ਵਿਚ ਤੂੰ ਧੁਰ ਤੋਂ ਹੀ ਆਪਣੀ ਮੇਹਰ ਨਾਲ (ਸਿਮਰਨ ਦਾ ਲੇਖ ਲਿਖ ਕੇ) ਰੱਖ ਦਿੱਤਾ ਹੈ।", wordMeaning = "ਧੁਰਿ = ਧੁਰ ਤੋਂ। ਕਰਮਿ = ਮੇਹਰ ਨਾਲ। ਸਿ = ਸੇ, ਉਹ ਬੰਦੇ। ਨਾਮਿ = ਨਾਮ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-299", gurmukhi = "ਕਹੈ ਨਾਨਕੁ. ਤਹ ਸੁਖੁ ਹੋਆ; ਤਿਤੁ ਘਰਿ ਅਨਹਦ ਵਾਜੇ ॥੫॥", transliteration = "kahai naanak. tah sukh hoaa; tit ghar anahad vaaje ||5||", translation = "Says Nanak, they are at peace, and the unstruck sound current vibrates within their homes. ||5||", hindi = "कहै नानकु. तह सुखु होआ; तितु घरि अनहद वाजे ॥५॥", punjabi = "ਨਾਨਕ ਆਖਦਾ ਹੈ ਕਿ ਉਸ ਹਿਰਦੇ-ਘਰ ਵਿਚ ਸੁਖ ਪੈਦਾ ਹੁੰਦਾ ਹੈ, ਉਸ ਹਿਰਦੇ ਵਿਚ (ਮਾਨੋ) ਇਕ-ਰਸ (ਵਾਜੇ) ਵੱਜਦੇ ਹਨ ॥੫॥", wordMeaning = "ਅਨਹਦ = ਅਨ-ਹਦ, ਬਿਨਾ ਵਜਾਏ ਵੱਜਣ ਵਾਲੇ, ਇਕ-ਰਸ, ਲਗਾਤਾਰ ॥੫॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-300", gurmukhi = "ਅਨਦੁ ਸੁਣਹੁ ਵਡਭਾਗੀਹੋ; ਸਗਲ ਮਨੋਰਥ ਪੂਰੇ ॥", transliteration = "anad sunah vadbhaageeho; sagal mnorath poore ||", translation = "Listen to the song of bliss, O most fortunate ones; all your longings shall be fulfilled.", hindi = "अनदु सुणहु वडभागीहो; सगल मनोरथ पूरे ॥", punjabi = "ਹੇ ਵੱਡੇ ਭਾਗਾਂ ਵਾਲਿਓ! ਸੁਣੋ, ਆਨੰਦ ਇਹ ਹੈ ਕਿ (ਉਸ ਅਵਸਥਾ ਵਿਚ) ਮਨ ਦੀਆਂ ਸਾਰੀਆਂ ਦੌੜਾਂ ਮੁੱਕ ਜਾਂਦੀਆਂ ਹਨ (ਸਾਰੇ ਸੰਕਲਪ ਸਿਰੇ ਚੜ੍ਹ ਜਾਂਦੇ ਹਨ),", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-301", gurmukhi = "ਪਾਰਬ੍ਰਹਮੁ ਪ੍ਰਭੁ ਪਾਇਆ; ਉਤਰੇ ਸਗਲ ਵਿਸੂਰੇ ॥", transliteration = "paarabraham prabh paaiaa; utre sagal visoore ||", translation = "I have obtained the Supreme Lord God, and all sorrows have been forgotten.", hindi = "पारब्रहमु प्रभु पाइआ; उतरे सगल विसूरे ॥", punjabi = "ਪਰਮ ਆਤਮਾ ਪ੍ਰਭੂ ਮਿਲ ਪੈਂਦਾ ਹੈ, ਸਾਰੇ ਚਿੰਤਾ-ਝੌਰੇ ਮਨ ਤੋਂ ਲਹਿ ਜਾਂਦੇ ਹਨ।", wordMeaning = "ਵਿਸੂਰੇ = ਚਿੰਤਾ-ਝੋਰੇ। ਸੰਤਾਪ = ਕਲੇਸ਼।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-302", gurmukhi = "ਦੂਖ ਰੋਗ ਸੰਤਾਪ ਉਤਰੇ; ਸੁਣੀ ਸਚੀ ਬਾਣੀ ॥", transliteration = "dookh rog santaap utre; sunee schee baanee ||", translation = "Pain, illness and suffering have departed, listening to the True Bani.", hindi = "दूख रोग संताप उतरे; सुणी सची बाणी ॥", punjabi = "ਅਕਾਲ ਪੁਰਖ ਦੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਦੀ ਬਾਣੀ ਸੁਣਿਆਂ ਸਾਰੇ ਦੁੱਖ ਰੋਗ ਕਲੇਸ਼ ਮਿਟ ਜਾਂਦੇ ਹਨ।", wordMeaning = "ਸਚੀ ਬਾਣੀ = ਸਦਾ-ਥਿਰ ਪ੍ਰਭੂ ਦੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਦੀ ਬਾਣੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-303", gurmukhi = "ਸੰਤ ਸਾਜਨ ਭਏ ਸਰਸੇ; ਪੂਰੇ ਗੁਰ ਤੇ ਜਾਣੀ ॥", transliteration = "sant saajan bhae sarse; poore gur te jaanee ||", translation = "The Saints and their friends are in ecstasy, knowing the Perfect Guru.", hindi = "संत साजन भए सरसे; पूरे गुर ते जाणी ॥", punjabi = "ਜੇਹੜੇ ਸੰਤ ਗੁਰਮੁਖਿ ਪੂਰੇ ਗੁਰੂ ਤੋਂ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਦੀ ਬਾਣੀ ਨਾਲ ਸਾਂਝੀ ਪਾਣੀ ਸਿੱਖ ਲੈਂਦੇ ਹਨ ਉਹਨਾਂ ਦੇ ਹਿਰਦੇ ਖਿੜ ਆਉਂਦੇ ਹਨ।", wordMeaning = "ਸਰਸੇ = ਸ-ਰਸ, ਰਹੇ, ਆਨੰਦ-ਭਰਪੂਰ। ਗੁਰ ਤੇ = ਗੁਰੂ ਤੋਂ। ਸਤਿਗੁਰੁ ਰਹਿਆ", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-304", gurmukhi = "ਸੁਣਤੇ ਪੁਨੀਤ. ਕਹਤੇ ਪਵਿਤੁ; ਸਤਿਗੁਰੁ ਰਹਿਆ ਭਰਪੂਰੇ ॥", transliteration = "sunte puneet. kahte pvit; stigur rhiaa bharpoore ||", translation = "Pure are the listeners, and pure are the speakers; the True Guru is all-pervading and permeating.", hindi = "सुणते पुनीत. कहते पवितु; सतिगुरु रहिआ भरपूरे ॥", punjabi = "ਇਸ ਬਾਣੀ ਨੂੰ ਸੁਣਨ ਵਾਲੇ ਉਚਾਰਨ ਵਾਲੇ ਸਭ ਪਵਿਤ੍ਰ-ਆਤਮਕ ਹੋ ਜਾਂਦੇ ਹਨ, ਇਸ ਬਾਣੀ ਵਿਚ ਉਹਨਾਂ ਨੂੰ ਸਤਿਗੁਰੂ ਹੀ ਦਿੱਸਦਾ ਹੈ।", wordMeaning = "ਭਰਪੂਰੇ = ਗੁਰੂ (ਆਪਣੀ ਬਾਣੀ ਵਿਚ) ਭਰਪੂਰ ਹੈ, ਬਾਣੀ ਗੁਰੂ-ਰੂਪ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-305", gurmukhi = "ਬਿਨਵੰਤਿ ਨਾਨਕੁ. ਗੁਰ ਚਰਣ ਲਾਗੇ; ਵਾਜੇ ਅਨਹਦ ਤੂਰੇ ॥੪੦॥੧॥", transliteration = "binavant naanak. gur charan laage; vaaje anahad toore ||40||1||", translation = "Prays Nanak, touching the Guru's Feet, the unstruck sound current of the celestial bugles vibrates and resounds. ||40||1||", hindi = "बिनवंति नानकु. गुर चरण लागे; वाजे अनहद तूरे ॥४०॥१॥", punjabi = "ਨਾਨਕ ਬੇਨਤੀ ਕਰਦਾ ਹੈ-ਜੇਹੜੇ ਬੰਦੇ ਗੁਰੂ ਦੀ ਚਰਨੀਂ ਲੱਗਦੇ ਹਨ, ਉਹਨਾਂ ਦੇ ਅੰਦਰ ਇਕ-ਰਸ (ਖ਼ੁਸ਼ੀ ਦੇ) ਵਾਜੇ ਵੱਜ ਪੈਂਦੇ ਹਨ (ਉਹਨਾਂ ਦੇ ਅੰਦਰ ਆਤਮਕ ਆਨੰਦ ਪੈਦਾ ਹੋ ਜਾਂਦਾ ਹੈ) ॥੪੦॥੧॥", wordMeaning = "ਅਨਹਦ = ਇਕ-ਰਸ। ਤੂਰੇ = ਵਾਜੇ। ਮਨੋਰਥ = ਮਨ ਦੀਆਂ ਦੌੜਾਂ ॥੪੦॥੧॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-306", gurmukhi = "ਮੁੰਦਾਵਣੀ ਮਹਲਾ ੫ ॥", transliteration = "mundaavnee mahlaa 5 ||", translation = "Mundaavanee, Fifth Mehl:", hindi = "मुंदावणी महला ५ ॥", punjabi = "ਮੁਹਰ ਛਾਪ ਪੰਜਵੀਂ ਪਾਤਿਸ਼ਾਹੀ।", wordMeaning = "ਮੁੰਦਾਵਣੀ = (मुद् = to please, ਪ੍ਰਸ਼ਨ ਕਰਨਾ मोदयति = pleases)। ਮੁਦਾਵਣੀ, ਜਾਂ, ਮੁੰਦਾਵਣੀ = ਆਤਮਕ ਪ੍ਰਸੰਨਤਾ ਦੇਣ ਵਾਲੀ ਵਸਤ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-307", gurmukhi = "ਥਾਲ ਵਿਚਿ. ਤਿੰਨਿ ਵਸਤੂ ਪਈਓ; ਸਤੁ ਸੰਤੋਖੁ ਵੀਚਾਰੋ ॥", transliteration = "thaal vich. tinn vastoo paeeo; sat santokh veechaaro ||", translation = "Upon this Plate, three things have been placed: Truth, Contentment and Contemplation.", hindi = "थाल विचि. तिंनि वसतू पईओ; सतु संतोखु वीचारो ॥", punjabi = "(ਉਸ ਮਨੁੱਖ ਦੇ ਹਿਰਦੇ-) ਥਾਲ ਵਿਚ ਉੱਚਾ ਆਚਰਨ, ਸੰਤੋਖ ਅਤੇ ਆਤਮਕ ਜੀਵਨ ਦੀ ਸੂਝ-ਇਹ ਤਿੰਨ ਵਸਤੂਆਂ ਟਿਕੀਆਂ ਰਹਿੰਦੀਆਂ ਹਨ,", wordMeaning = "ਥਾਲ ਵਿਚਿ = (ਉਸ ਹਿਰਦੇ-) ਥਾਲ ਵਿਚ। ਤਿੰਨਿ ਵਸਤੂ = ਤਿੰਨ ਚੀਜ਼ਾਂ (ਸਤੁ, ਸੰਤੋਖੁ ਅਤੇ ਵੀਚਾਰ)।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-308", gurmukhi = "ਅੰਮ੍ਰਿਤ ਨਾਮੁ. ਠਾਕੁਰ ਕਾ ਪਇਓ; ਜਿਸ ਕਾ ਸਭਸੁ ਅਧਾਰੋ ॥", transliteration = "amrit naam. thaakur kaa paio; jis kaa sabhas adhaaro ||", translation = "The Ambrosial Nectar of the Naam, the Name of our Lord and Master, has been placed upon it as well; it is the Support of all.", hindi = "अंम्रित नामु. ठाकुर का पइओ; जिस का सभसु अधारो ॥", punjabi = "(ਜਿਸ ਮਨੁੱਖ ਦੇ ਹਿਰਦੇ-ਥਾਲ ਵਿਚ) ਪਰਮਾਤਮਾ ਦਾ ਆਤਮਕ ਜੀਵਨ ਦੇਣ ਵਾਲਾ ਨਾਮ ਆ ਵੱਸਦਾ ਹੈ (ਇਹ 'ਅੰਮ੍ਰਿਤ ਨਾਮੁ' ਐਸਾ ਹੈ) ਕਿ ਇਸ ਦਾ ਆਸਰਾ ਹਰੇਕ ਜੀਵ ਲਈ (ਜ਼ਰੂਰੀ) ਹੈ।", wordMeaning = "ਅੰਮ੍ਰਿਤ = ਆਤਮਕ ਜੀਵਨ ਦੇਣ ਵਾਲਾ। ਜਿਸ ਕਾ = (ਸੰਬੰਧਕ 'ਕਾ' ਦੇ ਕਾਰਨ ਲਫ਼ਜ਼ 'ਜਿਸੁ' ਦਾ (ੁ) ਉਡ ਗਿਆ ਹੈ) ਜਿਸ (ਨਾਮ) ਦਾ। ਸਭਸੁ = ਹਰੇਕ ਜੀਵ ਨੂੰ। ਅਧਾਰੋ = ਆਸਰਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-309", gurmukhi = "ਜੇ ਕੋ ਖਾਵੈ. ਜੇ ਕੋ ਭੁੰਚੈ; ਤਿਸ ਕਾ ਹੋਇ ਉਧਾਰੋ ॥", transliteration = "je ko khaavai. je ko bhunchai; tis kaa hoi udhaaro ||", translation = "One who eats it and enjoys it shall be saved.", hindi = "जे को खावै. जे को भुंचै; तिस का होइ उधारो ॥", punjabi = "(ਇਸ ਆਤਮਕ ਭੋਜਨ ਨੂੰ) ਜੇ ਕੋਈ ਮਨੁੱਖ ਸਦਾ ਖਾਂਦਾ ਰਹਿੰਦਾ ਹੈ, ਤਾਂ ਉਸ ਮਨੁੱਖ ਦਾ ਵਿਕਾਰਾਂ ਤੋਂ ਬਚਾਉ ਹੋ ਜਾਂਦਾ ਹੈ।", wordMeaning = "ਕੋ = ਕੋਈ (ਮਨੁੱਖ)। ਭੁੰਚੈ = ਭੁੰਚਦਾ ਹੈ, ਖਾਂਦਾ ਹੈ, ਮਾਣਦਾ ਹੈ। ਤਿਸ ਕਾ = (ਸੰਬੰਧਕ 'ਕਾ' ਦੇ ਕਾਰਨ ਲਫ਼ਜ਼ 'ਤਿਸੁ ਦਾ (ੁ) ਉਡ ਗਿਆ ਹੈ) ਉਸ (ਮਨੁੱਖ) ਦਾ। ਉਧਾਰੋ = ਪਾਰ-ਉਤਾਰਾ, ਵਿਕਾਰਾਂ ਤੋਂ ਬਚਾਉ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-310", gurmukhi = "ਏਹ ਵਸਤੁ. ਤਜੀ ਨਹ ਜਾਈ; ਨਿਤ ਨਿਤ ਰਖੁ ਉਰਿ ਧਾਰੋ ॥", transliteration = "eh vasat. tjee nah jaaee; nit nit rakh ur dhaaro ||", translation = "This thing can never be forsaken; keep this always and forever in your mind.", hindi = "एह वसतु. तजी नह जाई; नित नित रखु उरि धारो ॥", punjabi = "(ਜੇ ਆਤਮਕ 'ਉਧਾਰ' ਦੀ ਲੋੜ ਹੈ ਤਾਂ) ਆਤਮਕ ਪ੍ਰਸੰਨਤਾ ਦੇਣ ਵਾਲੀ ਇਹ ਨਾਮ-ਵਸਤੂ ਤਿਆਗੀ ਨਹੀਂ ਜਾ ਸਕਦੀ, ਇਸ ਨੂੰ ਸਦਾ ਹੀ ਆਪਣੇ ਹਿਰਦੇ ਵਿਚ ਸਾਂਭ ਰੱਖ।", wordMeaning = "ਏਹ ਵਸਤੁ = ਆਤਮਕ ਪ੍ਰਸੰਨਤਾ ਦੇਣ ਵਾਲੀ ਇਹ ਚੀਜ਼, ਇਹ ਮੁਦਾਵਣੀ। ਤਜੀ ਨਹ ਜਾਈ = ਤਿਆਗੀ ਨਹੀਂ ਜਾ ਸਕਦੀ। ਰਖੁ = ਸਾਂਭ ਕੇ ਰੱਖੋ। ਉਰਿ = ਹਿਰਦੇ ਵਿਚ। ਧਾਰੋ = ਟਿਕਾਓ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-311", gurmukhi = "ਤਮ ਸੰਸਾਰੁ. ਚਰਨ ਲਗਿ ਤਰੀਐ; ਸਭੁ ਨਾਨਕ ਬ੍ਰਹਮ ਪਸਾਰੋ ॥੧॥", transliteration = "tam sansaar. charan lag treeai; sabh naanak braham psaaro ||1||", translation = "The dark world-ocean is crossed over, by grasping the Feet of the Lord; O Nanak, it is all the extension of God. ||1||", hindi = "तम संसारु. चरन लगि तरीऐ; सभु नानक ब्रहम पसारो ॥१॥", punjabi = "ਹੇ ਨਾਨਕ! (ਇਸ ਨਾਮ ਵਸਤੂ ਦੀ ਬਰਕਤਿ ਨਾਲ) ਪ੍ਰਭੂ ਦੀ ਚਰਨੀਂ ਲੱਗ ਕੇ ਘੁੱਪ ਹਨੇਰਾ ਸੰਸਾਰ-ਸਮੁੰਦਰ ਤਰਿਆ ਜਾ ਸਕਦਾ ਹੈ ਅਤੇ ਹਰ ਥਾਂ ਪਰਮਾਤਮਾ ਦੇ ਆਪੇ ਦਾ ਪਰਕਾਸ਼ ਹੀ (ਦਿੱਸਣ ਲੱਗ ਪੈਂਦਾ ਹੈ) ॥੧॥", wordMeaning = "ਤਮ = (तमस्) ਹਨੇਰਾ। ਤਮ ਸੰਸਾਰੁ = (ਵਿਕਾਰਾਂ ਦੇ ਕਾਰਨ ਬਣਿਆ ਹੋਇਆ) ਘੁੱਪ ਹਨੇਰਾ ਜਗਤ। ਲਗਿ = ਲਗ ਕੇ। ਸਭੁ = ਹਰ ਥਾਂ। ਬ੍ਰਹਮ ਪਸਾਰੋ = ਪਰਮਾਤਮਾ ਦਾ ਖਿਲਾਰਾ, ਪਰਮਾਤਮਾ ਦੇ ਆਪੇ ਦਾ ਪਰਕਾਸ਼ ॥੧॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-312", gurmukhi = "ਸਲੋਕ ਮਹਲਾ ੫ ॥", transliteration = "salok mahlaa 5 ||", translation = "Salok, Fifth Mehl:", hindi = "सलोक महला ५ ॥", punjabi = "ਸਲੋਕ ਪੰਜਵੀਂ ਪਾਤਿਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-313", gurmukhi = "ਤੇਰਾ ਕੀਤਾ. ਜਾਤੋ ਨਾਹੀ; ਮੈਨੋ ਜੋਗੁ ਕੀਤੋਈ ॥", transliteration = "teraa keetaa. jaato naahee; maino jog keetoee ||", translation = "I have not appreciated what You have done for me, Lord; only You can make me worthy.", hindi = "तेरा कीता. जातो नाही; मैनो जोगु कीतोई ॥", punjabi = "(ਹੇ ਪ੍ਰਭੂ!) ਮੈਂ ਤੇਰੇ ਕੀਤੇ ਉਪਕਾਰ ਦੀ ਕਦਰ ਨਹੀਂ ਸਮਝ ਸਕਦਾ, (ਉਪਕਾਰ ਦੀ ਦਾਤ ਸਾਂਭਣ ਲਈ) ਤੂੰ (ਆਪ ਹੀ) ਮੈਨੂੰ ਫਬਵਾਂ ਭਾਂਡਾ ਬਣਾਇਆ ਹੈ।", wordMeaning = "ਕੀਤਾ = ਕੀਤਾ ਹੋਇਆ (ਉਪਕਾਰ)। ਜਾਤੋ ਨਾਹੀ = (ਤੇਰੇ ਕੀਤੇ ਉਪਕਾਰ ਦੀ) ਮੈਂ ਕਦਰ ਨਹੀਂ ਸਮਝੀ। ਮੈਨੋ = ਮੈਨੂੰ। ਕੀਤੋਈ = ਤੂੰ (ਮੈਨੂੰ) ਬਣਾਇਆ ਹੈ। ਜੋਗੁ = ਲਾਇਕ, (ਉਪਕਾਰ ਦੀ ਦਾਤ ਸਾਂਭਣ ਲਈ) ਫਬਵਾਂ (ਭਾਂਡਾ)। ਮੈ", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-314", gurmukhi = "ਮੈ ਨਿਰਗੁਣਿਆਰੇ. ਕੋ ਗੁਣੁ ਨਾਹੀ; ਆਪੇ ਤਰਸੁ ਪਇਓਈ ॥", transliteration = "mai nirguniaare. ko gun naahee; aape taras paioee ||", translation = "I am unworthy - I have no worth or virtues at all. You have taken pity on me.", hindi = "मै निरगुणिआरे. को गुणु नाही; आपे तरसु पइओई ॥", punjabi = "ਮੈਂ ਗੁਣ-ਹੀਨ ਵਿਚ ਕੋਈ ਗੁਣ ਨਹੀਂ ਹੈ। ਤੈਨੂੰ ਆਪ ਨੂੰ ਹੀ ਮੇਰੇ ਉਤੇ ਤਰਸ ਆ ਗਿਆ।", wordMeaning = "ਨਿਰਗੁਣਿਆਰੇ = ਮੈਂ ਗੁਣ-ਹੀਨ ਵਿਚ। ਕੋ ਗੁਣੁ = ਕੋਈ ਗੁਣ। ਆਪੇ = ਆਪ ਹੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-315", gurmukhi = "ਤਰਸੁ ਪਇਆ. ਮਿਹਰਾਮਤਿ ਹੋਈ; ਸਤਿਗੁਰੁ ਸਜਣੁ ਮਿਲਿਆ ॥", transliteration = "taras paiaa. mihraamat hoee; stigur sajan miliaa ||", translation = "You took pity on me, and blessed me with Your Mercy, and I have met the True Guru, my Friend.", hindi = "तरसु पइआ. मिहरामति होई; सतिगुरु सजणु मिलिआ ॥", punjabi = "ਹੇ ਪ੍ਰਭੂ! ਤੇਰੇ ਮਨ ਵਿਚ ਮੇਰੇ ਵਾਸਤੇ ਤਰਸ ਪੈਦਾ ਹੋਇਆ, ਮੇਰੇ ਉੱਤੇ ਤੇਰੀ ਮਿਹਰ ਹੋਈ, ਤਾਂ ਮੈਨੂੰ ਮਿੱਤਰ ਗੁਰੂ ਮਿਲ ਪਿਆ (ਤੇਰਾ ਇਹ ਉਪਕਾਰ ਭੁਲਾਇਆ ਨਹੀਂ ਜਾ ਸਕਦਾ)।", wordMeaning = "ਮਿਹਰਾਮਤਿ = ਮਿਹਰ, ਦਇਆ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-316", gurmukhi = "ਨਾਨਕ. ਨਾਮੁ ਮਿਲੈ ਤਾਂ ਜੀਵਾਂ; ਤਨੁ ਮਨੁ ਥੀਵੈ ਹਰਿਆ ॥੧॥", transliteration = "naanak. naam milai taan jeevaan; tan man theevai hriaa ||1||", translation = "O Nanak, if I am blessed with the Naam, I live, and my body and mind blossom forth. ||1||", hindi = "नानक. नामु मिलै तां जीवां; तनु मनु थीवै हरिआ ॥१॥", punjabi = "ਨਾਨਕ ਆਖਦਾ ਹੈ- (ਹੁਣ ਪਿਆਰੇ ਗੁਰੂ ਪਾਸੋਂ) ਜਦੋਂ ਮੈਨੂੰ (ਤੇਰਾ) ਨਾਮ ਮਿਲਦਾ ਹੈ, ਤਾਂ ਮੇਰੇ ਅੰਦਰ ਆਤਮਕ ਜੀਵਨ ਪੈਦਾ ਹੋ ਜਾਂਦਾ ਹੈ, ਮੇਰਾ ਤਨ ਮੇਰਾ ਮਨ (ਉਸ ਆਤਮਕ ਜੀਵਨ ਦੀ ਬਰਕਤਿ ਨਾਲ) ਖਿੜ ਆਉਂਦਾ ਹੈ ॥੧॥", wordMeaning = "ਮਿਲੈ = ਮਿਲਦਾ ਹੈ। ਤਾਂ = ਤਦੋਂ। ਜੀਵਾਂ = ਮੈਂ ਜੀਊ ਪੈਂਦਾ ਹਾਂ, ਮੈਨੂੰ ਆਤਮਕ ਜੀਵਨ ਲੱਭ ਪੈਂਦਾ ਹੈ। ਥੀਵੈ = ਹੋ ਜਾਂਦਾ ਹੈ। ਹਰਿਆ = (ਆਤਮਕ ਜੀਵਨ ਨਾਲ) ਹਰਾ-ਭਰਾ ॥੧॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-317", gurmukhi = "ਪਉੜੀ ॥", transliteration = "pauree ||", translation = "Pauree:", hindi = "पउड़ी ॥", punjabi = "ਪਉੜੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-318", gurmukhi = "ਤਿਥੈ ਤੂ ਸਮਰਥੁ; ਜਿਥੈ ਕੋਇ ਨਾਹਿ ॥", transliteration = "tithai too samarath; jithai koi naah ||", translation = "Where You are, Almighty Lord, there is no one else.", hindi = "तिथै तू समरथु; जिथै कोइ नाहि ॥", punjabi = "(ਹੇ ਪ੍ਰਭੂ!) ਜਿੱਥੇ ਹੋਰ ਕੋਈ (ਜੀਵ ਸਹਾਇਤਾ ਕਰਨ ਜੋਗਾ) ਨਹੀਂ ਉਥੇ, ਹੇ ਪ੍ਰਭੂ! ਤੂੰ ਹੀ ਮਦਦ ਕਰਨ ਜੋਗਾ ਹੈਂ।", wordMeaning = "ਸਮਰਥੁ = ਸਹਾਇਤਾ ਕਰਨ ਜੋਗਾ।", startsAtMs = 0L, endsAtMs = 0L),
