    BaniLine(id = "rehras-sahib-337", gurmukhi = "ਸਾਕਤ ਨਿੰਦਕ ਦੁਸਟ; ਖਿਨ ਮਾਹਿ ਬਿਦਾਰਿਅਨੁ ॥", transliteration = "saakat nindak dusat; khin maah bidaarian ||", translation = "In an instant, You have destroyed the faithless cynics and slanderous enemies.", hindi = "साकत निंदक दुसट; खिन माहि बिदारिअनु ॥", punjabi = "ਜੋ ਉਸ ਦੇ ਚਰਨਾਂ ਤੋਂ ਟੁੱਟੇ ਹੋਏ ਹਨ, ਜੋ ਨਿੰਦਾ ਕਰਦੇ ਰਹਿੰਦੇ ਹਨ, ਜੋ ਗੰਦੇ ਆਚਰਨ ਵਾਲੇ ਹਨ, ਉਹਨਾਂ ਨੂੰ ਇਕ ਪਲ ਵਿਚ ਉਸ ਨੇ ਮਾਰ ਮੁਕਾਇਆ ਹੈ।", wordMeaning = "ਸਾਕਤੁ = ਟੁਟੇ ਹੋਏ, ਵਿਛੁੜੇ ਹੋਏ। ਬਿਦਾਰਿਅਨੁ = ਨਾਸ ਕਰ ਦਿੱਤੇ ਉਸ ਨੇ[", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-338", gurmukhi = "ਤਿਸੁ ਸਾਹਿਬ ਕੀ ਟੇਕ; ਨਾਨਕ. ਮਨੈ ਮਾਹਿ ॥", transliteration = "tis saahib kee tek; naanak. mnai maah ||", translation = "That Lord and Master is my Anchor and Support; O Nanak, hold firm in your mind.", hindi = "तिसु साहिब की टेक; नानक. मनै माहि ॥", punjabi = "ਨਾਨਕ ਦੇ ਮਨ ਵਿਚ ਭੀ ਉਸ ਮਾਲਕ ਦਾ ਆਸਰਾ ਹੈ,", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "rehras-sahib-339", gurmukhi = "ਜਿਸੁ ਸਿਮਰਤ ਸੁਖੁ ਹੋਇ; ਸਗਲੇ ਦੂਖ ਜਾਹਿ ॥੨॥", transliteration = "jis simarat sukh hoi; sagle dookh jaah ||2||", translation = "Remembering Him in meditation, happiness comes, and all sorrows and pains simply vanish. ||2||", hindi = "जिसु सिमरत सुखु होइ; सगले दूख जाहि ॥२॥", punjabi = "ਜਿਸ ਨੂੰ ਸਿਮਰਿਆਂ ਸੁਖ ਮਿਲਦਾ ਹੈ ਤੇ ਸਾਰੇ ਦੁੱਖ ਦੂਰ ਹੋ ਜਾਂਦੇ ਹਨ ॥੨॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L)
)
